/**
 * 표·운영체제 단축키 170개의 한 줄 설명 — 열 언어.
 *
 * 키 이름은 어느 언어 안에서도 라틴 글자 그대로 둔다. Ctrl은 어디서나 Ctrl이고
 * Cmd는 Cmd다. 옮기는 것은 "무엇을 하는가"와 "무엇을 하나 틀리기 쉬운가"
 * 한 문장뿐이다 — /cmd가 명령 이름을 그렇게 다룬다.
 *
 * 윈도우와 맥이 갈리는 자리는 문장 안에서 반드시 어느 쪽인지 밝힌다.
 *
 * 열 칸을 배열로 적는다 — 순서는 ko·en·es·pt·ja·de·fr·hi·zh·tw.
 */
import type { Ten } from './types.ts';

export const SC_DESC_OFFICE: Record<string, Ten> = {
  /* ═════════ excel ═════════ */
  'excel-fill-down': ["위 칸의 내용을 아래로 선택한 칸들에 그대로 채웁니다 — 값만이 아니라 서식까지 따라 내려옵니다.", "Fills the cells you selected below with the cell above, carrying the formatting down and not just the value.", "Rellena las celdas seleccionadas debajo con la celda superior, arrastrando también el formato y no solo el valor.", "Preenche as células selecionadas abaixo com a célula de cima, levando o formato junto e não apenas o valor.", "上のセルの内容を、選んだ下のセルへ埋めます。値だけでなく書式まで一緒に降りてきます。", "Füllt die darunter markierten Zellen mit der Zelle darüber — samt Format, nicht nur mit dem Wert.", "Remplit les cellules sélectionnées en dessous avec la cellule du dessus, en emportant le format et pas seulement la valeur.", "ऊपर वाली cell को नीचे चुनी हुई cells में भर देता है, और मान के साथ formatting भी नीचे आ जाती है।", "把上面一格填进你选中的下方单元格，连格式一起带下来，不只是值。", "把上面一格填進你選取的下方儲存格，連格式一起帶下來，不只是值。"],
  'excel-fill-right': ["왼쪽 칸의 내용을 오른쪽으로 선택한 칸들에 채웁니다 — 아래로 채우는 Ctrl+D와 방향만 다릅니다.", "Fills the cells you selected to the right with the cell on the left; it is Ctrl+D turned sideways.", "Rellena hacia la derecha las celdas seleccionadas con la celda de la izquierda; es Ctrl+D girado.", "Preenche à direita as células selecionadas com a célula da esquerda; é o Ctrl+D virado de lado.", "左のセルの内容を、選んだ右のセルへ埋めます。下に埋める Ctrl+D の向きを変えただけです。", "Füllt die rechts markierten Zellen mit der Zelle links — dasselbe wie Ctrl+D, nur seitwärts.", "Remplit vers la droite les cellules sélectionnées avec celle de gauche ; c est Ctrl+D pivoté.", "बाईं cell को दाईं ओर चुनी हुई cells में भर देता है; यह Ctrl+D का बग़ल वाला रूप है।", "用左边一格填满你选中的右侧单元格，相当于横过来的 Ctrl+D。", "用左邊一格填滿你選取的右側儲存格，相當於橫過來的 Ctrl+D。"],
  'excel-flash-fill': ["예시 한두 줄만 적어 주면 나머지 규칙을 알아채 채워 줍니다. 윈도우에만 조합이 있고 맥에서는 Data 메뉴로 들어가야 합니다.", "Guesses the pattern from the example you typed and fills the rest of the column; the combination exists only on Windows, so on a Mac you go through the Data menu.", "Deduce el patrón del ejemplo que escribiste y rellena el resto de la columna; la combinación solo existe en Windows, en Mac se usa el menú Data.", "Deduz o padrão do exemplo que você digitou e preenche o resto da coluna; a combinação só existe no Windows, no Mac use o menu Data.", "書いた例から規則を読み取って残りを埋めます。組み合わせは Windows にしかなく、Mac では Data メニューから呼びます。", "Erkennt das Muster an Ihrem Beispiel und füllt den Rest der Spalte; die Tastenfolge gibt es nur unter Windows, auf dem Mac über das Menü Data.", "Devine le motif à partir de votre exemple et remplit le reste de la colonne ; la combinaison n existe que sous Windows, sur Mac il faut passer par le menu Data.", "आपके लिखे उदाहरण से नियम पहचानकर बाक़ी column भर देता है; यह combination केवल Windows पर है, Mac पर Data मेनू से जाना पड़ता है।", "根据你写的示例猜出规律，把这一列剩下的补齐；这个组合只有 Windows 有，Mac 上要走 Data 菜单。", "根據你寫的範例猜出規律，把這一欄剩下的補齊；這個組合只有 Windows 有，Mac 上要走 Data 選單。"],
  'excel-edit-cell': ["칸 안으로 커서를 넣어 고칩니다. 그냥 타이핑하면 기존 내용을 덮어쓰지만 F2는 뒤에 이어 씁니다.", "Puts the cursor inside the cell so you can edit it; typing straight away would overwrite the contents, while F2 continues from the end.", "Coloca el cursor dentro de la celda para editarla; escribir directamente sobrescribe el contenido, mientras F2 sigue desde el final.", "Coloca o cursor dentro da célula para editar; digitar direto sobrescreve o conteúdo, enquanto F2 continua a partir do fim.", "セルの中にカーソルを入れて編集します。そのまま打つと中身を上書きしますが、F2 は末尾から続けて書けます。", "Setzt den Cursor in die Zelle zum Bearbeiten; einfaches Tippen überschreibt den Inhalt, F2 schreibt am Ende weiter.", "Place le curseur dans la cellule pour la modifier ; taper directement écrase le contenu, alors que F2 reprend à la fin.", "cell के भीतर cursor रखकर उसे बदलने देता है; सीधे टाइप करने पर पुराना मिट जाता है, F2 अंत से आगे लिखता है।", "把光标放进单元格里改内容；直接输入会覆盖原有内容，而 F2 是从末尾接着写。", "把游標放進儲存格裡改內容；直接輸入會覆蓋原有內容，而 F2 是從結尾接著寫。"],
  'excel-enter-and-fill-selection': ["여러 칸을 골라 두고 한 번 입력하면 고른 칸 전부가 같은 값으로 채워집니다. 한 칸만 골랐을 때는 아래로 내려가지 않고 그 자리에 머무릅니다.", "Select a range, type once, and every selected cell gets that entry; with a single cell it stays put instead of dropping down a row.", "Selecciona un rango, escribe una vez y todas las celdas reciben ese valor; con una sola celda el cursor se queda en su sitio en vez de bajar.", "Selecione um intervalo, digite uma vez e todas as células recebem aquele valor; com uma única célula o cursor fica onde está em vez de descer.", "範囲を選んで一度入力すれば、選んだ全てのセルが同じ値になります。単一セルなら下へ移らずその場に留まります。", "Bereich markieren, einmal tippen — alle markierten Zellen erhalten den Eintrag; bei einer einzelnen Zelle bleibt der Cursor stehen statt nach unten zu springen.", "Sélectionnez une plage, tapez une fois et toutes les cellules reçoivent la saisie ; sur une seule cellule, le curseur reste en place au lieu de descendre.", "एक range चुनकर एक बार टाइप करें और सभी चुनी हुई cells में वही मान चला जाता है; एक ही cell हो तो cursor नीचे नहीं जाता, वहीं रुकता है।", "先选一片区域，输入一次，所有选中的单元格都会填上同样的内容；只选一格时光标留在原地，不往下跳。", "先選一片區域，輸入一次，所有選取的儲存格都會填上同樣的內容；只選一格時游標留在原地，不往下跳。"],
  'excel-new-line-in-cell': ["한 칸 안에서 줄을 바꿉니다. Enter만 누르면 아래 칸으로 넘어가 버리고, 맥은 Ctrl+Option+Enter입니다.", "Breaks the line inside the same cell; Enter on its own would jump to the cell below, and on a Mac the combination is Ctrl+Option+Enter.", "Salta de línea dentro de la misma celda; Enter a secas saltaría a la celda de abajo, y en Mac la combinación es Ctrl+Option+Enter.", "Quebra a linha dentro da mesma célula; Enter sozinho pularia para a célula de baixo, e no Mac a combinação é Ctrl+Option+Enter.", "同じセルの中で改行します。Enter だけでは下のセルへ移ってしまい、Mac では Ctrl+Option+Enter です。", "Bricht die Zeile innerhalb derselben Zelle um; Enter allein springt in die Zelle darunter, auf dem Mac lautet die Folge Ctrl+Option+Enter.", "Passe à la ligne dans la même cellule ; Enter seul sauterait à la cellule du dessous, et sur Mac la combinaison est Ctrl+Option+Enter.", "एक ही cell के भीतर नई पंक्ति शुरू करता है; अकेला Enter नीचे की cell पर चला जाता है, और Mac पर यह Ctrl+Option+Enter है।", "在同一个单元格里换行；只按 Enter 会跳到下一格，Mac 上则是 Ctrl+Option+Enter。", "在同一個儲存格裡換行；只按 Enter 會跳到下一格，Mac 上則是 Ctrl+Option+Enter。"],
  'excel-insert-date': ["오늘 날짜를 고정된 값으로 적어 넣습니다. 날마다 바뀌는 TODAY 함수와 달리 한 번 찍히면 그대로 남습니다.", "Types today date in as a fixed value; unlike the TODAY function it never changes again tomorrow.", "Escribe la fecha de hoy como valor fijo; a diferencia de la función TODAY, mañana no cambiará.", "Escreve a data de hoje como valor fixo; diferente da função TODAY, ela não muda amanhã.", "今日の日付を固定値として書き込みます。毎日変わる TODAY 関数と違い、一度入ればそのままです。", "Trägt das heutige Datum als festen Wert ein; anders als die Funktion TODAY ändert es sich morgen nicht.", "Écrit la date du jour comme valeur figée ; contrairement à la fonction TODAY, elle ne changera pas demain.", "आज की तारीख़ एक स्थिर मान के रूप में भर देता है; TODAY function की तरह यह कल बदलती नहीं।", "把今天的日期作为固定值写进去；和每天都变的 TODAY 函数不同，它写下就不再变。", "把今天的日期作為固定值寫進去；和每天都變的 TODAY 函數不同，它寫下就不再變。"],
  'excel-insert-time': ["지금 시각을 고정된 값으로 적어 넣습니다. 윈도우와 맥이 갈리는 자리로, 윈도우는 Ctrl+Shift+;이고 맥은 Cmd+;입니다.", "Types the current time in as a fixed value; this is one place the platforms split — Ctrl+Shift+; on Windows but Cmd+; on a Mac.", "Escribe la hora actual como valor fijo; aquí las plataformas se separan: Ctrl+Shift+; en Windows y Cmd+; en Mac.", "Escreve a hora atual como valor fixo; aqui as plataformas divergem: Ctrl+Shift+; no Windows e Cmd+; no Mac.", "現在の時刻を固定値として書き込みます。ここは環境で分かれる箇所で、Windows は Ctrl+Shift+;、Mac は Cmd+; です。", "Trägt die aktuelle Uhrzeit als festen Wert ein; hier gehen die Systeme auseinander — Ctrl+Shift+; unter Windows, Cmd+; auf dem Mac.", "Écrit l heure actuelle comme valeur figée ; c est un point de divergence : Ctrl+Shift+; sous Windows mais Cmd+; sur Mac.", "अभी का समय स्थिर मान के रूप में भर देता है; यहाँ दोनों platform अलग हैं — Windows पर Ctrl+Shift+; और Mac पर Cmd+;।", "把当前时间作为固定值写进去；这里两个平台不一样，Windows 是 Ctrl+Shift+;，Mac 是 Cmd+;。", "把目前時間作為固定值寫進去；這裡兩個平台不一樣，Windows 是 Ctrl+Shift+;，Mac 是 Cmd+;。"],
  'excel-copy-formula-from-above': ["바로 위 칸의 수식을 글자 그대로 가져옵니다 — 참조가 한 줄 밀리는 Ctrl+D와 달리 =A1이 =A1로 그대로 옵니다.", "Copies the formula from the cell above letter for letter, so =A1 stays =A1 instead of shifting a row down as Ctrl+D would.", "Copia la fórmula de la celda superior letra por letra, así =A1 sigue siendo =A1 en vez de desplazarse una fila como haría Ctrl+D.", "Copia a fórmula da célula de cima letra por letra, então =A1 continua =A1 em vez de descer uma linha como o Ctrl+D faria.", "すぐ上のセルの数式を文字どおり写します。参照が一行ずれる Ctrl+D と違い、=A1 は =A1 のまま入ります。", "Kopiert die Formel der Zelle darüber zeichengetreu, sodass =A1 auch =A1 bleibt und nicht wie bei Ctrl+D eine Zeile verrutscht.", "Copie la formule de la cellule du dessus à la lettre : =A1 reste =A1 au lieu de glisser d une ligne comme avec Ctrl+D.", "ऊपर वाली cell का formula अक्षर-दर-अक्षर उठा लेता है, इसलिए =A1 वैसा ही रहता है, Ctrl+D की तरह एक पंक्ति खिसकता नहीं।", "把上一格的公式原字照搬，=A1 仍是 =A1，不像 Ctrl+D 那样引用往下挪一行。", "把上一格的公式原字照搬，=A1 仍是 =A1，不像 Ctrl+D 那樣參照往下挪一列。"],
  'excel-repeat-last-action': ["방금 한 동작을 한 번 더 되풀이합니다 — 되돌린 것을 다시 하는 redo도 같은 키이고, 윈도우에서는 수식을 고치고 있지 않을 때 F4가 같은 일을 합니다.", "Repeats whatever you just did, doubles as redo, and on Windows F4 does the same thing whenever you are not editing a formula.", "Repite lo que acabas de hacer, sirve también como rehacer y, en Windows, F4 hace lo mismo cuando no estás editando una fórmula.", "Repete o que você acabou de fazer, serve também como refazer e, no Windows, F4 faz o mesmo quando você não está editando uma fórmula.", "直前の操作をもう一度繰り返します。やり直し(redo)も同じキーで、Windows では数式を編集していないとき F4 が同じ働きをします。", "Wiederholt die letzte Aktion, dient gleichzeitig als Wiederherstellen, und unter Windows tut F4 dasselbe, solange Sie keine Formel bearbeiten.", "Répète ce que vous venez de faire, sert aussi de rétablir, et sous Windows F4 fait la même chose tant que vous ne modifiez pas une formule.", "आपने अभी जो किया उसे दोहरा देता है, redo का काम भी करता है, और Windows पर जब आप formula नहीं लिख रहे हों तो F4 भी यही करता है।", "把你刚做的动作再做一遍，同时也是重做；在 Windows 上，只要不是在编辑公式，F4 的作用一样。", "把你剛做的動作再做一遍，同時也是重做；在 Windows 上，只要不是在編輯公式，F4 的作用一樣。"],
  'excel-insert-hyperlink': ["고른 칸에 링크를 답니다. 칸에 이미 글이 있으면 그 글이 링크 이름이 되고, 문서 안의 다른 칸으로 가는 링크도 여기서 만듭니다.", "Attaches a link to the selected cell; existing text becomes the link label, and the same dialog also links to another place inside the workbook.", "Añade un enlace a la celda seleccionada; el texto que ya haya será la etiqueta, y el mismo cuadro permite enlazar a otro sitio del libro.", "Adiciona um link à célula selecionada; o texto que já existe vira o rótulo, e a mesma caixa também liga para outro ponto da pasta de trabalho.", "選んだセルにリンクを付けます。既に文字があればそれがリンク名になり、同じ画面からブック内の別の場所へも張れます。", "Hängt der markierten Zelle einen Link an; vorhandener Text wird die Beschriftung, und derselbe Dialog verlinkt auch an eine Stelle innerhalb der Arbeitsmappe.", "Ajoute un lien à la cellule sélectionnée ; le texte déjà présent devient le libellé, et la même boîte permet aussi de viser un autre endroit du classeur.", "चुनी हुई cell में link जोड़ता है; पहले से लिखा text उसका नाम बन जाता है, और उसी box से workbook के भीतर किसी जगह का link भी बनता है।", "给选中的单元格加链接；单元格里已有的文字会变成链接名，同一个对话框也能链到工作簿内的其他位置。", "給選取的儲存格加連結；儲存格裡已有的文字會變成連結名稱，同一個對話框也能連到工作簿內的其他位置。"],
  'excel-paste-special': ["값만·서식만·행열 바꿔 붙이기 같은 선택 창을 엽니다. 맥은 Cmd+Ctrl+V로, Windows의 Ctrl+Alt+V와 조합이 다릅니다.", "Opens the dialog where you choose values only, formats only, transpose and the rest; the Mac combination is Cmd+Ctrl+V, not Ctrl+Alt+V.", "Abre el cuadro donde eliges solo valores, solo formato, transponer y demás; en Mac la combinación es Cmd+Ctrl+V, no Ctrl+Alt+V.", "Abre a caixa onde você escolhe somente valores, somente formato, transpor e o resto; no Mac a combinação é Cmd+Ctrl+V, não Ctrl+Alt+V.", "値のみ・書式のみ・行列を入れ替えて貼るなどを選ぶ画面を開きます。Mac は Cmd+Ctrl+V で、Ctrl+Alt+V ではありません。", "Öffnet den Dialog für Werte, Formate, Transponieren und alles Weitere; auf dem Mac lautet die Folge Cmd+Ctrl+V, nicht Ctrl+Alt+V.", "Ouvre la boîte où l on choisit valeurs seules, format seul, transposer, etc. ; sur Mac la combinaison est Cmd+Ctrl+V et non Ctrl+Alt+V.", "वह box खोलता है जहाँ केवल मान, केवल format, पंक्ति-स्तंभ बदलकर चिपकाना आदि चुनते हैं; Mac पर यह Cmd+Ctrl+V है, Ctrl+Alt+V नहीं।", "打开可以选择只粘值、只粘格式、行列转置等的对话框；Mac 上的组合是 Cmd+Ctrl+V，不是 Ctrl+Alt+V。", "開啟可以選擇只貼值、只貼格式、行列轉置等的對話框；Mac 上的組合是 Cmd+Ctrl+V，不是 Ctrl+Alt+V。"],
  'excel-paste-values': ["수식은 버리고 계산된 숫자만 붙입니다. V Enter로 이어 누르는 것은 윈도우 창의 글쇠라서, 맥에서는 창이 뜬 뒤 Values를 골라야 합니다.", "Drops the formulas and pastes the numbers they produced; the V then Enter part is a Windows dialog accelerator, so on a Mac you pick Values in the dialog instead.", "Descarta las fórmulas y pega los números resultantes; la parte V y Enter es un acelerador del cuadro de Windows, así que en Mac eliges Values en el cuadro.", "Descarta as fórmulas e cola os números que elas produziram; a parte V e Enter é um atalho da caixa do Windows, então no Mac você escolhe Values na caixa.", "数式を捨てて計算結果の数値だけを貼ります。V Enter と続けるのは Windows のダイアログの割り当てなので、Mac では開いた画面で Values を選びます。", "Verwirft die Formeln und fügt nur die berechneten Zahlen ein; das V und Enter ist eine Windows-Dialogtaste, auf dem Mac wählen Sie im Dialog Values.", "Abandonne les formules et ne colle que les nombres obtenus ; le V puis Enter est un raccourci de la boîte Windows, sur Mac vous choisissez Values dans la boîte.", "formula हटाकर केवल निकला हुआ अंक चिपकाता है; V और Enter वाला हिस्सा Windows के box का accelerator है, इसलिए Mac पर box में Values चुनना पड़ता है।", "丢掉公式，只粘贴算出来的数字；接着按 V 再按 Enter 是 Windows 对话框的快捷字母，Mac 上要在弹出的对话框里选 Values。", "丟掉公式，只貼上算出來的數字；接著按 V 再按 Enter 是 Windows 對話框的快捷字母，Mac 上要在跳出的對話框裡選 Values。"],
  'excel-select-column': ["칸이 놓인 열 전체를 고릅니다. 표(Table) 안에서 누르면 먼저 표의 열만 잡히고, 한 번 더 누르면 시트의 열 전체가 잡힙니다.", "Selects the whole column the cell sits in; inside a table the first press grabs only the table column and a second press takes the entire sheet column.", "Selecciona toda la columna donde está la celda; dentro de una tabla la primera pulsación toma solo la columna de la tabla y la segunda toda la columna de la hoja.", "Seleciona a coluna inteira onde a célula está; dentro de uma tabela a primeira vez pega só a coluna da tabela e a segunda pega a coluna toda da planilha.", "セルのある列を丸ごと選びます。テーブル内では一度目はテーブルの列だけ、もう一度押すとシート全体の列になります。", "Markiert die gesamte Spalte der Zelle; in einer Tabelle greift der erste Druck nur die Tabellenspalte, der zweite die ganze Blattspalte.", "Sélectionne toute la colonne de la cellule ; dans un tableau, la première pression ne prend que la colonne du tableau, la seconde toute la colonne de la feuille.", "जिस column में cell है उसे पूरा चुन लेता है; Table के भीतर पहली बार केवल table का column आता है और दूसरी बार पूरी sheet का column।", "选中该单元格所在的整列；在表格（Table）里第一次只选表格的那一列，再按一次才是整张工作表的列。", "選取該儲存格所在的整欄；在表格（Table）裡第一次只選表格的那一欄，再按一次才是整張工作表的欄。"],
  'excel-select-row': ["칸이 놓인 행 전체를 고릅니다. 이 상태에서 Ctrl+Shift+Plus를 누르면 묻지 않고 행이 하나 끼어듭니다.", "Selects the whole row the cell sits in; with the row selected, Ctrl+Shift+Plus inserts a new row without asking anything.", "Selecciona toda la fila donde está la celda; con la fila seleccionada, Ctrl+Shift+Plus inserta una fila nueva sin preguntar nada.", "Seleciona a linha inteira onde a célula está; com a linha selecionada, Ctrl+Shift+Plus insere uma nova linha sem perguntar nada.", "セルのある行を丸ごと選びます。行を選んだ状態で Ctrl+Shift+Plus を押すと、何も聞かれずに行が一つ挿入されます。", "Markiert die gesamte Zeile der Zelle; ist die Zeile markiert, fügt Ctrl+Shift+Plus ohne Rückfrage eine neue Zeile ein.", "Sélectionne toute la ligne de la cellule ; la ligne étant sélectionnée, Ctrl+Shift+Plus insère une ligne sans rien demander.", "जिस row में cell है उसे पूरा चुन लेता है; row चुनी हो तो Ctrl+Shift+Plus बिना कुछ पूछे एक नई row डाल देता है।", "选中该单元格所在的整行；选好整行后按 Ctrl+Shift+Plus，会直接插入一行而不再询问。", "選取該儲存格所在的整列；選好整列後按 Ctrl+Shift+Plus，會直接插入一列而不再詢問。"],
  'excel-select-current-region': ["처음 누르면 칸을 둘러싼 데이터 덩어리만, 한 번 더 누르면 시트 전체가 잡힙니다 — 빈 줄이 덩어리의 경계입니다.", "The first press takes the block of data around the cell and a second press takes the whole sheet; an empty row or column is where the block ends.", "La primera pulsación toma el bloque de datos alrededor de la celda y la segunda toda la hoja; una fila o columna vacía marca el borde del bloque.", "A primeira vez pega o bloco de dados em volta da célula e a segunda pega a planilha inteira; uma linha ou coluna vazia é onde o bloco termina.", "一度目はセルを囲むデータの塊だけ、もう一度押すとシート全体を選びます。空の行や列が塊の境目です。", "Der erste Druck nimmt den Datenblock um die Zelle, der zweite das ganze Blatt; eine leere Zeile oder Spalte begrenzt den Block.", "La première pression prend le bloc de données autour de la cellule, la seconde toute la feuille ; une ligne ou colonne vide marque la limite du bloc.", "पहली बार cell के चारों ओर का data-खंड चुनता है और दूसरी बार पूरी sheet; ख़ाली पंक्ति या स्तंभ ही खंड की सीमा है।", "第一次按选中单元格周围的数据块，再按一次选整张工作表；空行或空列就是数据块的边界。", "第一次按選取儲存格周圍的資料區塊，再按一次選整張工作表；空列或空欄就是資料區塊的邊界。"],
  'excel-select-to-end-of-data': ["그 방향으로 값이 끊기는 곳까지 한 번에 잡습니다. 중간에 빈 칸이 하나 있으면 거기서 멈추니, 네 방향 화살표 모두 같은 식으로 씁니다.", "Extends the selection until the values stop in that direction; one empty cell in the middle stops it early, and all four arrows work the same way.", "Extiende la selección hasta donde se cortan los valores en esa dirección; una celda vacía en medio la detiene antes, y las cuatro flechas funcionan igual.", "Estende a seleção até onde os valores param naquela direção; uma célula vazia no meio interrompe antes, e as quatro setas funcionam igual.", "その向きに値が途切れるところまで一気に選びます。途中に空のセルが一つあればそこで止まり、四方向の矢印どれも同じ使い方です。", "Erweitert die Markierung bis dort, wo die Werte in dieser Richtung enden; eine leere Zelle dazwischen stoppt früher, und alle vier Pfeiltasten wirken gleich.", "Étend la sélection jusqu à la fin des valeurs dans cette direction ; une cellule vide au milieu l arrête plus tôt, et les quatre flèches s utilisent pareil.", "उस दिशा में जहाँ मान ख़त्म होते हैं वहाँ तक चुन लेता है; बीच में एक ख़ाली cell हो तो वहीं रुक जाता है, और चारों तीर एक तरह काम करते हैं।", "沿这个方向一直选到数据断开的地方；中间只要有一个空格就会提前停下，四个方向键用法相同。", "沿這個方向一直選到資料斷開的地方；中間只要有一個空格就會提前停下，四個方向鍵用法相同。"],
  'excel-select-to-last-cell': ["시트가 기억하는 마지막 칸까지 한 번에 잡습니다. 지운 자리의 서식이 남아 있으면 데이터보다 훨씬 멀리까지 잡히는 것이 이 때문입니다.", "Extends the selection to the last cell the sheet remembers using; leftover formatting from deleted rows is why it often reaches far beyond your data.", "Extiende la selección hasta la última celda que la hoja recuerda usar; el formato que quedó de filas borradas explica que a veces llegue mucho más allá de tus datos.", "Estende a seleção até a última célula que a planilha lembra ter usado; formatação sobrando de linhas apagadas é o motivo de às vezes ir muito além dos dados.", "シートが記憶している最後のセルまで一気に選びます。消した行の書式が残っていると、データよりずっと遠くまで伸びるのはこのためです。", "Erweitert die Markierung bis zur letzten Zelle, die das Blatt als benutzt kennt; zurückgebliebene Formate gelöschter Zeilen sind der Grund, wenn sie weit über die Daten hinausreicht.", "Étend la sélection jusqu à la dernière cellule dont la feuille se souvient ; des formats restés après suppression expliquent qu elle dépasse souvent largement vos données.", "sheet जिस अंतिम cell को इस्तेमाल हुआ मानता है वहाँ तक चुन लेता है; मिटाई गई पंक्तियों की बची formatting के कारण यह अक्सर data से बहुत आगे तक पहुँच जाता है।", "一直选到工作表记住的最后一格；删掉的行留下的格式，就是它常常远远超出实际数据范围的原因。", "一直選到工作表記住的最後一格；刪掉的列留下的格式，就是它常常遠遠超出實際資料範圍的原因。"],
  'excel-go-to-last-cell': ["시트가 쓴 것으로 아는 맨 끝 칸으로 뛰어갑니다. 데이터는 100줄인데 여기가 5만 줄이면 파일이 부푼 까닭을 찾은 것입니다.", "Jumps to the last cell the sheet counts as used; if your data ends at row 100 but this lands on row 50000, you have just found why the file is bloated.", "Salta a la última celda que la hoja considera usada; si tus datos acaban en la fila 100 pero cae en la 50000, ya sabes por qué el archivo está inflado.", "Salta para a última célula que a planilha considera usada; se seus dados terminam na linha 100 mas ele cai na 50000, você achou o motivo do arquivo inchado.", "シートが使用済みとみなす最後のセルへ飛びます。データが 100 行なのにここが 5 万行なら、ファイルが膨れた原因を見つけたことになります。", "Springt zur letzten Zelle, die das Blatt als benutzt zählt; enden Ihre Daten bei Zeile 100, landet der Sprung aber bei 50000, kennen Sie den Grund für die aufgeblähte Datei.", "Saute à la dernière cellule que la feuille considère utilisée ; si vos données s arrêtent ligne 100 mais que vous atterrissez ligne 50000, vous savez pourquoi le fichier est énorme.", "sheet जिसे अंतिम प्रयुक्त cell मानता है वहाँ पहुँच जाता है; data 100वीं पंक्ति पर ख़त्म हो और यह 50000 पर उतरे, तो फ़ाइल के फूलने का कारण मिल गया।", "跳到工作表认为用过的最后一格；数据只到第 100 行而它落在第 50000 行，文件为什么这么大就有答案了。", "跳到工作表認為用過的最後一格；資料只到第 100 列而它落在第 50000 列，檔案為什麼這麼大就有答案了。"],
  'excel-go-to-first-cell': ["시트의 첫 칸 A1으로 돌아옵니다. 창을 고정해 두었다면 고정선 안쪽의 첫 칸으로 갑니다.", "Takes you back to A1; if panes are frozen it lands on the first cell inside the frozen edge instead.", "Vuelve a A1; si hay paneles inmovilizados aterriza en la primera celda dentro del borde congelado.", "Volta para A1; se houver painéis congelados, ele para na primeira célula dentro da borda congelada.", "シートの先頭 A1 へ戻ります。ウィンドウ枠を固定していれば、固定線の内側の先頭セルに入ります。", "Bringt Sie zurück nach A1; sind Fenster fixiert, landet der Sprung in der ersten Zelle hinter der fixierten Kante.", "Ramène en A1 ; si des volets sont figés, l atterrissage se fait sur la première cellule après la zone figée.", "sheet की पहली cell A1 पर लौट आता है; panes freeze किए हों तो freeze रेखा के अंदर की पहली cell पर पहुँचता है।", "回到工作表的第一格 A1；如果冻结了窗格，则落在冻结线内侧的第一格。", "回到工作表的第一格 A1；如果凍結了窗格，則落在凍結線內側的第一格。"],
  'excel-next-sheet': ["오른쪽 시트로 넘어갑니다. PageDown 글쇠가 없는 맥 노트북에서는 Fn+Ctrl+Down으로 누르고, 맥에서는 Option+Right가 더 편합니다.", "Moves one sheet tab to the right; on a Mac laptop without a PageDown key it is Fn+Ctrl+Down, and Option+Right is the easier Mac route.", "Pasa a la hoja de la derecha; en un portátil Mac sin tecla PageDown se hace con Fn+Ctrl+Down, y Option+Right es la vía más cómoda en Mac.", "Passa para a aba da direita; em um notebook Mac sem tecla PageDown use Fn+Ctrl+Down, e Option+Right é o caminho mais fácil no Mac.", "右のシートへ移ります。PageDown が無い Mac のノートでは Fn+Ctrl+Down で、Mac では Option+Right のほうが楽です。", "Wechselt ein Blatt nach rechts; auf einem Mac-Notebook ohne PageDown-Taste über Fn+Ctrl+Down, und Option+Right ist auf dem Mac der bequemere Weg.", "Passe à la feuille de droite ; sur un portable Mac sans touche PageDown, c est Fn+Ctrl+Down, et Option+Right reste plus simple sur Mac.", "दाईं ओर की sheet पर चला जाता है; जिस Mac laptop में PageDown नहीं है वहाँ Fn+Ctrl+Down, और Mac पर Option+Right आसान रास्ता है।", "切到右边一张工作表；Mac 笔记本没有 PageDown 键时用 Fn+Ctrl+Down，Mac 上更省事的是 Option+Right。", "切到右邊一張工作表；Mac 筆電沒有 PageDown 鍵時用 Fn+Ctrl+Down，Mac 上更省事的是 Option+Right。"],
  'excel-previous-sheet': ["왼쪽 시트로 넘어갑니다. 맥에서는 Option+Left가 같은 일을 하고, PageUp이 없는 노트북은 Fn+Ctrl+Up입니다.", "Moves one sheet tab to the left; on a Mac Option+Left does the same, and a laptop without PageUp needs Fn+Ctrl+Up.", "Pasa a la hoja de la izquierda; en Mac Option+Left hace lo mismo, y un portátil sin PageUp necesita Fn+Ctrl+Up.", "Passa para a aba da esquerda; no Mac Option+Left faz o mesmo, e um notebook sem PageUp precisa de Fn+Ctrl+Up.", "左のシートへ移ります。Mac では Option+Left が同じ働きで、PageUp が無いノートでは Fn+Ctrl+Up です。", "Wechselt ein Blatt nach links; auf dem Mac tut Option+Left dasselbe, und ein Notebook ohne PageUp braucht Fn+Ctrl+Up.", "Passe à la feuille de gauche ; sur Mac, Option+Left fait la même chose, et un portable sans PageUp demande Fn+Ctrl+Up.", "बाईं ओर की sheet पर चला जाता है; Mac पर Option+Left वही करता है, और जिस laptop में PageUp नहीं है वहाँ Fn+Ctrl+Up।", "切到左边一张工作表；Mac 上 Option+Left 效果相同，没有 PageUp 键的笔记本用 Fn+Ctrl+Up。", "切到左邊一張工作表；Mac 上 Option+Left 效果相同，沒有 PageUp 鍵的筆電用 Fn+Ctrl+Up。"],
  'excel-insert-sheet': ["새 시트를 지금 시트 앞에 끼워 넣습니다. 맥 노트북에서는 Fn까지 함께 눌러야 F11이 F11로 갑니다.", "Inserts a new sheet in front of the current one; on a Mac laptop you must hold Fn as well for F11 to reach Excel.", "Inserta una hoja nueva delante de la actual; en un portátil Mac hay que pulsar también Fn para que F11 llegue a Excel.", "Insere uma nova planilha antes da atual; em um notebook Mac é preciso segurar Fn para que F11 chegue ao Excel.", "新しいシートを今のシートの前に挿入します。Mac のノートでは Fn も一緒に押さないと F11 が Excel に届きません。", "Fügt ein neues Blatt vor dem aktuellen ein; auf einem Mac-Notebook müssen Sie zusätzlich Fn halten, damit F11 in Excel ankommt.", "Insère une nouvelle feuille devant la feuille active ; sur un portable Mac, il faut aussi maintenir Fn pour que F11 parvienne à Excel.", "मौजूदा sheet से पहले एक नई sheet जोड़ देता है; Mac laptop पर Fn भी दबाना पड़ता है वरना F11 Excel तक नहीं पहुँचता।", "在当前工作表前面插入一张新表；Mac 笔记本要同时按住 Fn，F11 才会传到 Excel。", "在目前工作表前面插入一張新表；Mac 筆電要同時按住 Fn，F11 才會傳到 Excel。"],
  'excel-insert-cells': ["끼워 넣을 방향을 묻는 창을 엽니다. 행이나 열을 통째로 골라 둔 뒤에 누르면 묻지 않고 바로 한 줄이 들어갑니다.", "Opens the Insert dialog asking which way to push the cells; with a whole row or column already selected it just inserts one without asking.", "Abre el cuadro Insert que pregunta hacia dónde desplazar las celdas; si ya seleccionaste una fila o columna entera, inserta directamente sin preguntar.", "Abre a caixa Insert perguntando para onde empurrar as células; com uma linha ou coluna inteira já selecionada, ele insere direto sem perguntar.", "どちらへ押しやるかを尋ねる挿入画面を開きます。行や列を丸ごと選んでから押せば、何も聞かれず一つ挿入されます。", "Öffnet den Insert-Dialog mit der Frage, wohin die Zellen verschoben werden; ist eine ganze Zeile oder Spalte markiert, wird ohne Rückfrage eingefügt.", "Ouvre la boîte Insert qui demande dans quel sens décaler les cellules ; avec une ligne ou une colonne entière déjà sélectionnée, l insertion se fait sans question.", "यह पूछने वाला Insert box खोलता है कि cells किस दिशा में खिसकें; पूरी row या column पहले से चुनी हो तो बिना पूछे एक जुड़ जाती है।", "打开 Insert 对话框询问单元格往哪边挪；若已整行或整列选好，则不再询问直接插入一条。", "開啟 Insert 對話框詢問儲存格往哪邊挪；若已整列或整欄選好，則不再詢問直接插入一條。"],
  'excel-delete-cells': ["칸을 지우고 남은 칸을 끌어와 자리를 메웁니다. 내용만 비우는 Delete와 달리 칸 자체가 없어져 아래 줄이 올라옵니다.", "Removes the cells and pulls the rest in to close the gap; unlike Delete, which only clears contents, the cells themselves go and the rows below move up.", "Quita las celdas y arrastra el resto para cerrar el hueco; a diferencia de Delete, que solo borra el contenido, desaparecen las celdas y las filas de abajo suben.", "Remove as células e traz o resto para fechar o vão; diferente do Delete, que só limpa o conteúdo, as células saem e as linhas de baixo sobem.", "セルを削除し、残りを寄せて隙間を埋めます。中身だけ消す Delete と違い、セル自体が無くなって下の行が上がります。", "Entfernt die Zellen und zieht den Rest nach, um die Lücke zu schließen; anders als Delete, das nur Inhalte löscht, verschwinden die Zellen und die Zeilen darunter rücken hoch.", "Supprime les cellules et rapproche le reste pour combler le trou ; contrairement à Delete qui n effface que le contenu, les cellules disparaissent et les lignes du dessous remontent.", "cells हटाकर बाक़ी को खींचकर जगह भर देता है; केवल सामग्री मिटाने वाले Delete से अलग, यहाँ cell ख़ुद चली जाती है और नीचे की पंक्तियाँ ऊपर आ जाती हैं।", "删掉单元格并把其余的挪过来补上空缺；和只清内容的 Delete 不同，这里单元格本身消失，下面的行会往上移。", "刪掉儲存格並把其餘的挪過來補上空缺；和只清內容的 Delete 不同，這裡儲存格本身消失，下面的列會往上移。"],
  'excel-hide-rows': ["고른 행을 감춥니다. 지우는 것이 아니라 높이를 0으로 접는 것이고, 맥의 Cmd+(는 사실 Cmd+Shift+9입니다.", "Hides the selected rows — it folds their height to zero rather than deleting them, and the Mac Cmd+( is really Cmd+Shift+9.", "Oculta las filas seleccionadas: pliega su altura a cero en vez de borrarlas, y el Cmd+( de Mac es en realidad Cmd+Shift+9.", "Oculta as linhas selecionadas: dobra a altura delas para zero em vez de apagar, e o Cmd+( do Mac é na verdade Cmd+Shift+9.", "選んだ行を隠します。削除ではなく高さを 0 に畳むだけで、Mac の Cmd+( は実は Cmd+Shift+9 です。", "Blendet die markierten Zeilen aus — ihre Höhe wird auf null gefaltet, nicht gelöscht, und das Mac-Cmd+( ist eigentlich Cmd+Shift+9.", "Masque les lignes sélectionnées : leur hauteur passe à zéro, rien n est supprimé, et le Cmd+( du Mac est en fait Cmd+Shift+9.", "चुनी हुई rows छिपा देता है — मिटाता नहीं, उनकी ऊँचाई शून्य कर देता है, और Mac का Cmd+( असल में Cmd+Shift+9 है।", "隐藏选中的行；这不是删除，只是把行高折成 0，而 Mac 的 Cmd+( 其实就是 Cmd+Shift+9。", "隱藏選取的列；這不是刪除，只是把列高折成 0，而 Mac 的 Cmd+( 其實就是 Cmd+Shift+9。"],
  'excel-hide-columns': ["고른 열을 감춥니다. 윈도우는 Ctrl+0, 맥은 Cmd+)이고, 감춘 열은 머리글 번호가 건너뛰는 것으로 알아봅니다.", "Hides the selected columns — Ctrl+0 on Windows, Cmd+) on a Mac — and you spot a hidden column by the gap in the header letters.", "Oculta las columnas seleccionadas: Ctrl+0 en Windows y Cmd+) en Mac; se nota una columna oculta por el salto en las letras de cabecera.", "Oculta as colunas selecionadas: Ctrl+0 no Windows e Cmd+) no Mac; percebe-se uma coluna oculta pelo salto nas letras do cabeçalho.", "選んだ列を隠します。Windows は Ctrl+0、Mac は Cmd+) で、隠れた列は見出しの文字が飛ぶことで気づけます。", "Blendet die markierten Spalten aus — Ctrl+0 unter Windows, Cmd+) auf dem Mac — erkennbar an der Lücke in den Spaltenbuchstaben.", "Masque les colonnes sélectionnées : Ctrl+0 sous Windows, Cmd+) sur Mac ; un saut dans les lettres d en-tête révèle une colonne cachée.", "चुने हुए columns छिपा देता है — Windows पर Ctrl+0, Mac पर Cmd+) — और छिपा column header के अक्षरों में छूटी कड़ी से पहचाना जाता है।", "隐藏选中的列；Windows 是 Ctrl+0，Mac 是 Cmd+)，列标字母中间断号就说明有列被隐藏了。", "隱藏選取的欄；Windows 是 Ctrl+0，Mac 是 Cmd+)，欄標字母中間斷號就說明有欄被隱藏了。"],
  'excel-unhide-columns': ["감춰 둔 열을 다시 펼칩니다. 윈도우에서는 Ctrl+Shift+0을 자판 배열 바꾸기가 가로채는 일이 많아 고장난 것처럼 보이고, 행은 Ctrl+Shift+9입니다.", "Brings hidden columns back; on Windows the keyboard-layout switcher often swallows Ctrl+Shift+0 so it looks broken, and rows use Ctrl+Shift+9 instead.", "Devuelve las columnas ocultas; en Windows el cambiador de teclado suele interceptar Ctrl+Shift+0 y parece que no funciona, y para filas es Ctrl+Shift+9.", "Traz de volta as colunas ocultas; no Windows o alternador de teclado costuma engolir Ctrl+Shift+0 e parece quebrado, e para linhas use Ctrl+Shift+9.", "隠した列を再び表示します。Windows ではキーボード配列の切り替えが Ctrl+Shift+0 を横取りして壊れて見えることが多く、行は Ctrl+Shift+9 です。", "Holt ausgeblendete Spalten zurück; unter Windows fängt der Tastaturlayout-Umschalter Ctrl+Shift+0 oft ab, sodass es defekt wirkt, für Zeilen gilt Ctrl+Shift+9.", "Réaffiche les colonnes masquées ; sous Windows, le changement de disposition clavier intercepte souvent Ctrl+Shift+0 et l on croit à une panne, tandis que les lignes utilisent Ctrl+Shift+9.", "छिपे columns फिर दिखा देता है; Windows पर keyboard layout बदलने वाला Ctrl+Shift+0 को अक्सर छीन लेता है इसलिए यह ख़राब लगता है, और rows के लिए Ctrl+Shift+9 है।", "把隐藏的列重新显示出来；在 Windows 上切换键盘布局常把 Ctrl+Shift+0 抢走，看着像失灵，行则用 Ctrl+Shift+9。", "把隱藏的欄重新顯示出來；在 Windows 上切換鍵盤配置常把 Ctrl+Shift+0 搶走，看著像失靈，列則用 Ctrl+Shift+9。"],
  'excel-group-rows': ["고른 행이나 열을 접을 수 있는 한 묶음으로 만듭니다. 윈도우는 Alt+Shift+Right, 맥은 Cmd+Shift+K로 아예 다릅니다.", "Bundles the selected rows or columns into a collapsible group; the keys are unrelated across platforms — Alt+Shift+Right on Windows, Cmd+Shift+K on a Mac.", "Agrupa las filas o columnas seleccionadas en un bloque plegable; las teclas no se parecen: Alt+Shift+Right en Windows y Cmd+Shift+K en Mac.", "Agrupa as linhas ou colunas selecionadas em um bloco recolhível; as teclas não têm relação: Alt+Shift+Right no Windows e Cmd+Shift+K no Mac.", "選んだ行や列を折りたためる一つの組にします。キーは環境で全く別で、Windows は Alt+Shift+Right、Mac は Cmd+Shift+K です。", "Fasst die markierten Zeilen oder Spalten zu einer einklappbaren Gruppe zusammen; die Tasten haben nichts miteinander zu tun — Alt+Shift+Right unter Windows, Cmd+Shift+K auf dem Mac.", "Regroupe les lignes ou colonnes sélectionnées en un bloc repliable ; les touches n ont rien à voir : Alt+Shift+Right sous Windows, Cmd+Shift+K sur Mac.", "चुनी हुई rows या columns को समेटने योग्य एक समूह बना देता है; कुंजियाँ दोनों platform पर बिलकुल अलग हैं — Windows पर Alt+Shift+Right, Mac पर Cmd+Shift+K।", "把选中的行或列打成一个可折叠的组；两个平台的按键毫无关系，Windows 是 Alt+Shift+Right，Mac 是 Cmd+Shift+K。", "把選取的列或欄打成一個可折疊的群組；兩個平台的按鍵毫無關係，Windows 是 Alt+Shift+Right，Mac 是 Cmd+Shift+K。"],
  'excel-ungroup-rows': ["묶어 둔 행이나 열을 풀어 접기 표시를 없앱니다. 윈도우는 Alt+Shift+Left, 맥은 Cmd+Shift+J입니다.", "Undoes a group so the collapse handles disappear; Alt+Shift+Left on Windows and Cmd+Shift+J on a Mac.", "Deshace el grupo y quitan los controles de plegado; Alt+Shift+Left en Windows y Cmd+Shift+J en Mac.", "Desfaz o grupo e os controles de recolher desaparecem; Alt+Shift+Left no Windows e Cmd+Shift+J no Mac.", "組をほどいて折りたたみの印を消します。Windows は Alt+Shift+Left、Mac は Cmd+Shift+J です。", "Löst eine Gruppe, sodass die Klappzeichen verschwinden; Alt+Shift+Left unter Windows, Cmd+Shift+J auf dem Mac.", "Défait le groupe et les poignées de repli disparaissent ; Alt+Shift+Left sous Windows et Cmd+Shift+J sur Mac.", "समूह खोल देता है और समेटने के निशान हट जाते हैं; Windows पर Alt+Shift+Left और Mac पर Cmd+Shift+J।", "解散分组，折叠标记随之消失；Windows 是 Alt+Shift+Left，Mac 是 Cmd+Shift+J。", "解散群組，折疊標記隨之消失；Windows 是 Alt+Shift+Left，Mac 是 Cmd+Shift+J。"],
  'excel-format-cells': ["숫자 꼴·정렬·테두리·채우기를 한자리에서 정하는 창입니다. 여기서 1은 숫자열의 1이고, 오른쪽 숫자판의 1은 듣지 않습니다.", "Opens the one dialog that holds number, alignment, border and fill; the 1 is the one on the number row, not the one on the numeric keypad.", "Abre el único cuadro con número, alineación, borde y relleno; el 1 es el de la fila de números, no el del teclado numérico.", "Abre a caixa única com número, alinhamento, borda e preenchimento; o 1 é o da linha de números, não o do teclado numérico.", "数値・配置・罫線・塗りつぶしを一つにまとめた画面を開きます。ここの 1 は数字列の 1 で、テンキーの 1 では効きません。", "Öffnet den einen Dialog für Zahl, Ausrichtung, Rahmen und Füllung; gemeint ist die 1 der Zahlenreihe, nicht die des Ziffernblocks.", "Ouvre l unique boîte réunissant nombre, alignement, bordure et remplissage ; le 1 est celui de la rangée de chiffres, pas celui du pavé numérique.", "संख्या, संरेखण, border और भरण एक ही जगह रखने वाला box खोलता है; यहाँ 1 अंकों की पंक्ति का 1 है, numeric keypad का नहीं।", "打开集数字、对齐、边框、填充于一处的对话框；这里的 1 是数字行的 1，小键盘的 1 不管用。", "開啟集數字、對齊、框線、填滿於一處的對話框；這裡的 1 是數字列的 1，數字鍵盤的 1 不管用。"],
  'excel-bold': ["고른 칸의 글씨를 굵게 바꾸거나 되돌립니다 — 한 번 더 누르면 풀립니다.", "Turns the text in the selected cells bold, and pressing it again takes the bold off.", "Pone en negrita el texto de las celdas seleccionadas, y al pulsar otra vez lo quita.", "Deixa o texto das células selecionadas em negrito, e pressionar de novo remove.", "選んだセルの文字を太字にします。もう一度押せば元に戻ります。", "Macht den Text der markierten Zellen fett; ein zweiter Druck nimmt es zurück.", "Met en gras le texte des cellules sélectionnées ; une seconde pression l enlève.", "चुनी हुई cells का text मोटा कर देता है, और दोबारा दबाने पर हट जाता है।", "把选中单元格的文字加粗，再按一次取消。", "把選取儲存格的文字加粗，再按一次取消。"],
  'excel-underline': ["고른 칸의 글씨에 밑줄을 넣거나 뺍니다. 윈도우는 Ctrl+U, 맥은 Cmd+U로 수정 글쇠만 다릅니다.", "Adds or removes an underline in the selected cells; only the modifier differs — Ctrl+U on Windows, Cmd+U on a Mac.", "Añade o quita el subrayado en las celdas seleccionadas; solo cambia el modificador: Ctrl+U en Windows y Cmd+U en Mac.", "Adiciona ou remove o sublinhado nas células selecionadas; só o modificador muda: Ctrl+U no Windows e Cmd+U no Mac.", "選んだセルの文字に下線を付けたり外したりします。修飾キーだけが違い、Windows は Ctrl+U、Mac は Cmd+U です。", "Setzt oder entfernt eine Unterstreichung in den markierten Zellen; nur die Modifiziertaste unterscheidet sich — Ctrl+U unter Windows, Cmd+U auf dem Mac.", "Ajoute ou retire un soulignement dans les cellules sélectionnées ; seule la touche de modification change : Ctrl+U sous Windows, Cmd+U sur Mac.", "चुनी हुई cells के text में रेखांकन जोड़ता या हटाता है; केवल modifier बदलता है — Windows पर Ctrl+U, Mac पर Cmd+U।", "给选中单元格的文字加或去掉下划线；只有修饰键不同，Windows 是 Ctrl+U，Mac 是 Cmd+U。", "給選取儲存格的文字加或去掉底線；只有輔助鍵不同，Windows 是 Ctrl+U，Mac 是 Cmd+U。"],
  'excel-outline-border': ["고른 자리 바깥쪽에만 선을 두릅니다. 윈도우는 Ctrl+Shift+&, 맥은 Cmd+Option+0으로 조합이 아예 다릅니다.", "Draws a line around the outside of the selection only; the combinations are unrelated — Ctrl+Shift+& on Windows, Cmd+Option+0 on a Mac.", "Dibuja una línea solo alrededor de la selección; las combinaciones no se parecen: Ctrl+Shift+& en Windows y Cmd+Option+0 en Mac.", "Desenha uma linha apenas em volta da seleção; as combinações não têm relação: Ctrl+Shift+& no Windows e Cmd+Option+0 no Mac.", "選んだ範囲の外側だけに線を引きます。組み合わせは全く別で、Windows は Ctrl+Shift+&、Mac は Cmd+Option+0 です。", "Zieht eine Linie nur um den Rand der Markierung; die Tastenfolgen sind völlig verschieden — Ctrl+Shift+& unter Windows, Cmd+Option+0 auf dem Mac.", "Trace un trait uniquement autour de la sélection ; les combinaisons diffèrent totalement : Ctrl+Shift+& sous Windows, Cmd+Option+0 sur Mac.", "चुने हुए हिस्से के केवल बाहरी किनारे पर रेखा खींचता है; दोनों combination बिलकुल अलग हैं — Windows पर Ctrl+Shift+&, Mac पर Cmd+Option+0।", "只在所选区域的外圈画线；两个平台的组合完全不同，Windows 是 Ctrl+Shift+&，Mac 是 Cmd+Option+0。", "只在所選區域的外圈畫線；兩個平台的組合完全不同，Windows 是 Ctrl+Shift+&，Mac 是 Cmd+Option+0。"],
  'excel-remove-borders': ["고른 자리의 선을 모두 지웁니다. 윈도우는 Ctrl+Shift+_, 맥은 Cmd+Option+Minus입니다.", "Wipes every border from the selection; Ctrl+Shift+_ on Windows and Cmd+Option+Minus on a Mac.", "Borra todos los bordes de la selección; Ctrl+Shift+_ en Windows y Cmd+Option+Minus en Mac.", "Apaga todas as bordas da seleção; Ctrl+Shift+_ no Windows e Cmd+Option+Minus no Mac.", "選んだ範囲の罫線をすべて消します。Windows は Ctrl+Shift+_、Mac は Cmd+Option+Minus です。", "Entfernt alle Rahmen aus der Markierung; Ctrl+Shift+_ unter Windows und Cmd+Option+Minus auf dem Mac.", "Efface toutes les bordures de la sélection ; Ctrl+Shift+_ sous Windows et Cmd+Option+Minus sur Mac.", "चुने हुए हिस्से की सभी रेखाएँ मिटा देता है; Windows पर Ctrl+Shift+_ और Mac पर Cmd+Option+Minus।", "清掉所选区域的全部边框；Windows 是 Ctrl+Shift+_，Mac 是 Cmd+Option+Minus。", "清掉所選區域的全部框線；Windows 是 Ctrl+Shift+_，Mac 是 Cmd+Option+Minus。"],
  'excel-align-center': ["칸 안의 내용을 가운데로 맞춥니다. 윈도우에는 한 번에 누르는 조합이 없어 리본을 Alt+H·A·C 순서로 밟아야 하고, 맥은 Cmd+E 하나입니다.", "Centres what is in the cell; Windows has no single combination so you step through the ribbon as Alt then H, A, C, while a Mac has plain Cmd+E.", "Centra el contenido de la celda; Windows no tiene una combinación única, hay que recorrer la cinta con Alt y luego H, A, C, mientras en Mac basta Cmd+E.", "Centraliza o conteúdo da célula; o Windows não tem uma combinação única, você percorre a faixa com Alt e depois H, A, C, enquanto no Mac basta Cmd+E.", "セルの中身を中央に揃えます。Windows には一発の組み合わせが無く、リボンを Alt から H・A・C と辿りますが、Mac は Cmd+E 一つです。", "Zentriert den Zellinhalt; Windows hat keine einzelne Tastenfolge, man läuft über das Menüband mit Alt, dann H, A, C, auf dem Mac genügt Cmd+E.", "Centre le contenu de la cellule ; Windows n a pas de combinaison unique, on parcourt le ruban avec Alt puis H, A, C, alors que sur Mac Cmd+E suffit.", "cell की सामग्री को बीच में कर देता है; Windows पर कोई एक combination नहीं है, ribbon को Alt फिर H, A, C से चलना पड़ता है, जबकि Mac पर सिर्फ़ Cmd+E।", "把单元格内容居中；Windows 没有一次按完的组合，要沿功能区按 Alt 再 H、A、C，而 Mac 只需 Cmd+E。", "把儲存格內容置中；Windows 沒有一次按完的組合，要沿功能區按 Alt 再 H、A、C，而 Mac 只需 Cmd+E。"],
  'excel-wrap-text': ["긴 글을 칸 안에서 여러 줄로 접습니다. 윈도우도 맥도 기본 조합이 없어 리본이나 Format Cells의 Alignment로 가야 하고, 손으로 줄을 나누려면 Alt+Enter입니다.", "Folds long text onto several lines inside the cell; neither platform ships a default combination, so you use the ribbon or the Alignment tab of Format Cells, and Alt+Enter is the manual way to break a line.", "Pliega el texto largo en varias líneas dentro de la celda; ninguna plataforma trae combinación por defecto, se usa la cinta o la pestaña Alignment de Format Cells, y Alt+Enter parte la línea a mano.", "Dobra o texto longo em várias linhas dentro da célula; nenhuma plataforma traz combinação padrão, use a faixa ou a aba Alignment de Format Cells, e Alt+Enter quebra a linha na mão.", "長い文字をセルの中で複数行に折り返します。Windows も Mac も既定の組み合わせが無く、リボンか Format Cells の Alignment を使い、手で改行するなら Alt+Enter です。", "Bricht langen Text innerhalb der Zelle auf mehrere Zeilen um; keine Plattform bringt eine Standardtastenfolge mit, man nutzt das Menüband oder das Register Alignment in Format Cells, und Alt+Enter bricht manuell um.", "Replie un texte long sur plusieurs lignes dans la cellule ; aucune plateforme ne fournit de combinaison par défaut, il faut le ruban ou l onglet Alignment de Format Cells, et Alt+Enter coupe la ligne à la main.", "लंबे text को cell के भीतर कई पंक्तियों में मोड़ देता है; किसी भी platform पर डिफ़ॉल्ट combination नहीं है, ribbon या Format Cells के Alignment से करना पड़ता है, और हाथ से तोड़ने के लिए Alt+Enter है।", "把长文字在单元格里折成多行；两个平台都没有默认组合，要走功能区或 Format Cells 的 Alignment，手动断行则用 Alt+Enter。", "把長文字在儲存格裡折成多行；兩個平台都沒有預設組合，要走功能區或 Format Cells 的 Alignment，手動斷行則用 Alt+Enter。"],
  'excel-format-general': ["숫자 꼴을 아무 서식도 없는 General로 되돌립니다. 날짜에 걸면 날짜가 아니라 그 밑에 있던 일련번호가 드러납니다.", "Strips the number format back to General; run it on a date and you see the serial number that was under it all along.", "Devuelve el formato de número a General; aplícalo a una fecha y aparece el número de serie que había debajo.", "Volta o formato numérico para General; aplique em uma data e aparece o número de série que estava por baixo.", "数値の書式を何も付いていない General に戻します。日付に当てると、その下にあった連番が現れます。", "Setzt das Zahlenformat auf General zurück; auf ein Datum angewandt erscheint die Seriennummer, die darunter lag.", "Ramène le format de nombre à General ; appliqué à une date, il révèle le numéro de série qui se cachait dessous.", "संख्या का format हटाकर General कर देता है; किसी तारीख़ पर लगाएँ तो नीचे छिपा serial number दिख जाता है।", "把数字格式还原为不带任何格式的 General；用在日期上，底下的序列号就露出来了。", "把數字格式還原為不帶任何格式的 General；用在日期上，底下的序號就露出來了。"],
  'excel-format-currency': ["소수 두 자리와 화폐 기호를 붙입니다. 기호는 컴퓨터의 지역 설정을 따르고, 미국 자판에서 $는 Shift+4 자리입니다.", "Applies two decimals with a currency symbol taken from your system locale; on a US layout the $ sits on Shift+4.", "Aplica dos decimales con el símbolo de moneda de la configuración regional; en un teclado de EE. UU. el $ está en Shift+4.", "Aplica duas casas decimais com o símbolo de moeda da configuração regional; em teclado dos EUA o $ fica em Shift+4.", "小数二桁と通貨記号を付けます。記号は OS の地域設定に従い、US 配列では $ は Shift+4 の位置です。", "Wendet zwei Dezimalstellen mit dem Währungszeichen Ihrer Systemregion an; auf US-Layout liegt das $ auf Shift+4.", "Applique deux décimales avec le symbole monétaire de vos paramètres régionaux ; sur un clavier US, le $ est sur Shift+4.", "दो दशमलव और आपके system locale का मुद्रा चिह्न लगाता है; US layout पर $ Shift+4 पर होता है।", "套上两位小数和货币符号，符号取自系统区域设置；美式键盘上 $ 在 Shift+4。", "套上兩位小數和貨幣符號，符號取自系統地區設定；美式鍵盤上 $ 在 Shift+4。"],
  'excel-format-percent': ["소수 없는 백분율 꼴로 바꿉니다. 값을 곱하는 것이 아니라 보이는 방식만 바뀌어 0.5가 50%로 읽힙니다.", "Switches to a percent format with no decimals; the stored value does not change, so 0.5 simply reads as 50%.", "Cambia a formato de porcentaje sin decimales; el valor guardado no cambia, así que 0,5 se lee como 50%.", "Muda para formato de porcentagem sem decimais; o valor guardado não muda, então 0,5 aparece como 50%.", "小数なしのパーセント表示にします。値そのものは変わらず、0.5 が 50% と読めるようになるだけです。", "Wechselt zu einem Prozentformat ohne Dezimalstellen; der gespeicherte Wert bleibt gleich, 0,5 liest sich einfach als 50%.", "Passe à un format pourcentage sans décimale ; la valeur stockée ne change pas, 0,5 s affiche simplement 50%.", "बिना दशमलव वाला प्रतिशत format लगा देता है; भीतर का मान बदलता नहीं, इसलिए 0.5 केवल 50% पढ़ा जाता है।", "改成不带小数的百分比格式；存的值没变，只是 0.5 现在读作 50%。", "改成不帶小數的百分比格式；存的值沒變，只是 0.5 現在讀作 50%。"],
  'excel-format-comma': ["천 단위 쉼표와 소수 두 자리를 붙입니다. 마이너스 숫자는 괄호가 아니라 빼기 기호로 나옵니다.", "Applies a thousands separator with two decimals, and negatives come out with a minus sign rather than in brackets.", "Aplica separador de miles con dos decimales, y los negativos salen con signo menos en lugar de entre paréntesis.", "Aplica separador de milhares com duas casas decimais, e os negativos saem com sinal de menos, não entre parênteses.", "桁区切りのカンマと小数二桁を付けます。負の数は括弧ではなくマイナス記号で出ます。", "Wendet ein Tausendertrennzeichen mit zwei Dezimalstellen an; negative Zahlen erscheinen mit Minuszeichen statt in Klammern.", "Applique un séparateur de milliers avec deux décimales, et les négatifs sortent avec un signe moins plutôt qu entre parenthèses.", "हज़ार का विभाजक और दो दशमलव लगाता है, और ऋणात्मक संख्याएँ कोष्ठक की जगह ऋण चिह्न के साथ आती हैं।", "套上千位分隔符和两位小数；负数用减号显示，而不是括号。", "套上千位分隔符和兩位小數；負數用減號顯示，而不是括號。"],
  'excel-format-date': ["일·월·연으로 된 날짜 꼴로 바꿉니다. 실제 값은 그대로인 채 보이는 모양만 바뀌므로, 글자로 적힌 날짜는 이 키로 고쳐지지 않습니다.", "Switches the cell to a day-month-year date format; only the display changes, so a date that was typed as text will not budge.", "Cambia la celda a un formato de fecha día-mes-año; solo cambia la apariencia, así que una fecha escrita como texto no se moverá.", "Muda a célula para um formato de data dia-mês-ano; só a exibição muda, então uma data digitada como texto não se altera.", "日・月・年の日付書式にします。変わるのは見え方だけなので、文字列として入った日付はこのキーでは直りません。", "Stellt die Zelle auf ein Datumsformat mit Tag, Monat und Jahr; nur die Anzeige ändert sich, ein als Text eingegebenes Datum bleibt unberührt.", "Passe la cellule à un format date jour-mois-année ; seul l affichage change, une date saisie comme texte ne bougera pas.", "cell को दिन-महीना-वर्ष वाले तारीख़ format में बदल देता है; केवल दिखावट बदलती है, इसलिए text के रूप में लिखी तारीख़ नहीं सुधरती।", "把单元格改成日-月-年的日期格式；只改显示方式，所以以文本输入的日期不会因此变过来。", "把儲存格改成日-月-年的日期格式；只改顯示方式，所以以文字輸入的日期不會因此變過來。"],
  'excel-autosum': ["위나 왼쪽의 숫자를 알아서 SUM으로 묶어 줍니다. 범위를 엑셀이 짐작한 것이니 Enter 전에 눈으로 확인해야 하고, 맥은 Cmd+Shift+T입니다.", "Guesses the numbers above or to the left and wraps them in SUM; check the range it picked before pressing Enter, and note the Mac key is Cmd+Shift+T.", "Adivina los números de arriba o de la izquierda y los envuelve en SUM; revisa el rango antes de pulsar Enter, y en Mac la tecla es Cmd+Shift+T.", "Adivinha os números acima ou à esquerda e os envolve em SUM; confira o intervalo antes de pressionar Enter, e no Mac a tecla é Cmd+Shift+T.", "上か左の数値を見当で SUM に包みます。範囲は Excel の推測なので Enter の前に目で確かめ、Mac では Cmd+Shift+T です。", "Errät die Zahlen darüber oder links und packt sie in SUM; prüfen Sie den gewählten Bereich vor dem Enter, und auf dem Mac lautet die Taste Cmd+Shift+T.", "Devine les nombres au-dessus ou à gauche et les enveloppe dans SUM ; vérifiez la plage avant d appuyer sur Enter, et sur Mac la touche est Cmd+Shift+T.", "ऊपर या बाईं ओर के अंकों का अंदाज़ा लगाकर उन्हें SUM में लपेट देता है; Enter दबाने से पहले चुनी हुई range देख लें, और Mac पर कुंजी Cmd+Shift+T है।", "自动猜出上方或左侧的数字并套上 SUM；按 Enter 前先看一眼它选的范围，Mac 上的键是 Cmd+Shift+T。", "自動猜出上方或左側的數字並套上 SUM；按 Enter 前先看一眼它選的範圍，Mac 上的鍵是 Cmd+Shift+T。"],
  'excel-insert-function': ["함수를 골라 인자를 칸칸이 채우는 창을 엽니다. 맥에서는 같은 키가 Formula Builder라는 이름으로 열립니다.", "Opens the window where you pick a function and fill its arguments one box at a time; on a Mac the same key opens it under the name Formula Builder.", "Abre la ventana para elegir una función y rellenar sus argumentos uno a uno; en Mac la misma tecla la abre con el nombre Formula Builder.", "Abre a janela para escolher uma função e preencher seus argumentos um a um; no Mac a mesma tecla abre com o nome Formula Builder.", "関数を選んで引数を一つずつ埋める画面を開きます。Mac では同じキーが Formula Builder という名前で開きます。", "Öffnet das Fenster, in dem Sie eine Funktion wählen und ihre Argumente einzeln eintragen; auf dem Mac öffnet dieselbe Taste den Formula Builder.", "Ouvre la fenêtre où l on choisit une fonction et remplit ses arguments un par un ; sur Mac, la même touche l ouvre sous le nom Formula Builder.", "वह window खोलता है जहाँ function चुनकर उसके तर्क एक-एक भरते हैं; Mac पर वही कुंजी इसे Formula Builder नाम से खोलती है।", "打开选函数并逐格填参数的窗口；Mac 上同一个键打开的它叫 Formula Builder。", "開啟選函數並逐格填參數的視窗；Mac 上同一個鍵開啟的它叫 Formula Builder。"],
  'excel-absolute-reference': ["수식을 고치는 중에 A1 → $A$1 → A$1 → $A1을 돌려 가며 바꿉니다. 여기가 가장 많이 어긋나는 자리로, 맥은 F4가 아니라 Cmd+T입니다.", "While you are editing a formula it cycles A1 to $A$1 to A$1 to $A1; this is the biggest platform trap, because on a Mac it is Cmd+T and not F4.", "Mientras editas una fórmula alterna A1, $A$1, A$1 y $A1; es la mayor trampa entre plataformas, porque en Mac es Cmd+T y no F4.", "Enquanto você edita uma fórmula, alterna A1, $A$1, A$1 e $A1; é a maior pegadinha entre plataformas, porque no Mac é Cmd+T e não F4.", "数式を編集している間に A1 → $A$1 → A$1 → $A1 と切り替えます。ここが最大の落とし穴で、Mac では F4 ではなく Cmd+T です。", "Wechselt beim Bearbeiten einer Formel zwischen A1, $A$1, A$1 und $A1; das ist die größte Plattformfalle, denn auf dem Mac heißt sie Cmd+T und nicht F4.", "Pendant l édition d une formule, fait tourner A1, $A$1, A$1 et $A1 ; c est le plus gros piège entre plateformes, car sur Mac c est Cmd+T et non F4.", "formula लिखते समय A1, $A$1, A$1 और $A1 के बीच घुमाता है; यही सबसे बड़ा platform-जाल है, क्योंकि Mac पर यह F4 नहीं बल्कि Cmd+T है।", "在编辑公式时循环切换 A1、$A$1、A$1、$A1；这是跨平台最大的坑，Mac 上是 Cmd+T 而不是 F4。", "在編輯公式時循環切換 A1、$A$1、A$1、$A1；這是跨平台最大的坑，Mac 上是 Cmd+T 而不是 F4。"],
  'excel-show-formulas': ["결과 대신 수식을 그대로 보여 주는 상태로 바꿉니다. 누르는 키는 숫자 1 왼쪽에 있는 억음 부호(`)입니다.", "Flips the sheet to showing formulas instead of results; the key is the grave accent to the left of the 1.", "Cambia la hoja para mostrar fórmulas en vez de resultados; la tecla es el acento grave a la izquierda del 1.", "Faz a planilha mostrar as fórmulas em vez dos resultados; a tecla é o acento grave à esquerda do 1.", "結果ではなく数式そのものを表示する状態に切り替えます。押すキーは 1 の左にあるバッククォート(`)です。", "Schaltet das Blatt auf die Anzeige der Formeln statt der Ergebnisse um; die Taste ist der Gravis links neben der 1.", "Fait afficher les formules au lieu des résultats ; la touche est l accent grave à gauche du 1.", "परिणाम की जगह formula दिखाने वाली स्थिति में बदल देता है; कुंजी 1 के बाईं ओर का grave accent (`) है।", "让工作表显示公式而不是结果；要按的键是数字 1 左边的反引号（`）。", "讓工作表顯示公式而不是結果；要按的鍵是數字 1 左邊的反引號（`）。"],
  'excel-recalculate-all': ["열려 있는 모든 통합 문서에서 바뀐 수식을 다시 셉니다. 맥은 F9가 아니라 Cmd+=이고, 자동 계산을 끈 문서에서 특히 자주 쓰입니다.", "Recalculates the changed formulas in every open workbook; on a Mac the key is Cmd+= rather than F9, and it matters most when automatic calculation is off.", "Recalcula las fórmulas cambiadas en todos los libros abiertos; en Mac la tecla es Cmd+= y no F9, y es clave cuando el cálculo automático está apagado.", "Recalcula as fórmulas alteradas em todas as pastas abertas; no Mac a tecla é Cmd+= e não F9, e importa mais quando o cálculo automático está desligado.", "開いている全てのブックで、変わった数式を計算し直します。Mac では F9 ではなく Cmd+= で、自動計算を切っているときに特に使います。", "Berechnet in allen offenen Arbeitsmappen die geänderten Formeln neu; auf dem Mac lautet die Taste Cmd+= statt F9, und sie zählt vor allem bei abgeschalteter Automatik.", "Recalcule les formules modifiées dans tous les classeurs ouverts ; sur Mac la touche est Cmd+= et non F9, surtout utile quand le calcul automatique est désactivé.", "खुली हुई सभी workbook में बदले हुए formula फिर से गिनता है; Mac पर कुंजी F9 नहीं बल्कि Cmd+= है, और स्वतः गणना बंद हो तो यह ख़ास काम आता है।", "重新计算所有打开工作簿里变动过的公式；Mac 上的键是 Cmd+= 而不是 F9，关掉自动重算时尤其常用。", "重新計算所有開啟工作簿裡變動過的公式；Mac 上的鍵是 Cmd+= 而不是 F9，關掉自動重算時尤其常用。"],
  'excel-calculate-sheet': ["지금 보고 있는 시트만 다시 셉니다. 무거운 문서에서 전체를 도는 F9를 피하려고 쓰는 키입니다.", "Recalculates only the sheet in front of you; it exists so you can avoid the full sweep of F9 in a heavy workbook.", "Recalcula solo la hoja que tienes delante; sirve para evitar la pasada completa de F9 en un libro pesado.", "Recalcula somente a planilha que está à frente; serve para evitar a varredura completa do F9 em uma pasta pesada.", "今表示しているシートだけを計算し直します。重いブックで全体を回る F9 を避けるためのキーです。", "Berechnet nur das vorderste Blatt neu; damit umgehen Sie in einer schweren Mappe den kompletten Durchlauf von F9.", "Recalcule seulement la feuille affichée ; elle évite le balayage complet de F9 dans un classeur lourd.", "केवल सामने खुली sheet को फिर गिनता है; भारी workbook में F9 के पूरे चक्कर से बचने के लिए यही है।", "只重算当前这张工作表；在很重的工作簿里，用它避开 F9 的全盘计算。", "只重算目前這張工作表；在很重的工作簿裡，用它避開 F9 的全盤計算。"],
  'excel-evaluate-formula-part': ["수식 입력줄에서 한 조각만 골라 누르면 그 조각의 값이 그 자리에 보입니다. 확인한 뒤에는 Esc로 빠져나와야 하고, Enter를 누르면 그 조각이 값으로 바뀌어 버립니다.", "Select one piece of a formula in the formula bar and this shows what that piece returns; leave with Esc, because Enter replaces the piece with its value for good.", "Selecciona un trozo de la fórmula en la barra y muestra lo que devuelve ese trozo; sal con Esc, porque Enter sustituye el trozo por su valor de forma definitiva.", "Selecione um trecho da fórmula na barra e ele mostra o que aquele trecho devolve; saia com Esc, pois Enter troca o trecho pelo valor de vez.", "数式バーで一部分だけ選んで押すと、その部分が返す値が見えます。確認したら Esc で抜けること — Enter を押すとその部分が値に置き換わってしまいます。", "Markieren Sie ein Stück der Formel in der Bearbeitungsleiste, und es zeigt, was dieses Stück zurückgibt; verlassen Sie es mit Esc, denn Enter ersetzt das Stück endgültig durch seinen Wert.", "Sélectionnez un morceau de la formule dans la barre et il affiche ce que ce morceau renvoie ; sortez avec Esc, car Enter remplace définitivement le morceau par sa valeur.", "formula bar में formula का एक टुकड़ा चुनें और यह दिखा देता है कि वह टुकड़ा क्या देता है; बाहर निकलने के लिए Esc दबाएँ, क्योंकि Enter उस टुकड़े को हमेशा के लिए मान से बदल देता है।", "在编辑栏里选中公式的一段，它就显示这一段算出什么；看完要按 Esc 退出，按 Enter 会把这一段永久换成数值。", "在資料編輯列裡選取公式的一段，它就顯示這一段算出什麼；看完要按 Esc 離開，按 Enter 會把這一段永久換成數值。"],
  'excel-expand-formula-bar': ["수식 입력줄을 여러 줄 높이로 늘렸다 줄입니다. 긴 IF 중첩을 볼 때 시트를 가리지 않게 되돌릴 수 있습니다.", "Grows the formula bar to several lines and shrinks it back; useful for reading a long nested IF without it covering the sheet for good.", "Agranda la barra de fórmulas a varias líneas y la vuelve a encoger; útil para leer un IF anidado largo sin taparlo todo.", "Aumenta a barra de fórmulas para várias linhas e volta a encolher; útil para ler um IF aninhado longo sem cobrir a planilha.", "数式バーを数行の高さに広げたり戻したりします。長い入れ子の IF を読むときに、シートを覆いっぱなしにせずに済みます。", "Vergrößert die Bearbeitungsleiste auf mehrere Zeilen und wieder zurück; praktisch, um ein langes verschachteltes IF zu lesen, ohne das Blatt dauerhaft zu verdecken.", "Agrandit la barre de formule sur plusieurs lignes puis la réduit ; pratique pour lire un IF imbriqué long sans masquer la feuille en permanence.", "formula bar को कई पंक्तियों तक बड़ा करता और फिर छोटा कर देता है; लंबे nested IF को पढ़ते समय sheet को स्थायी रूप से ढके बिना काम चल जाता है।", "把编辑栏拉高成好几行，再收回去；看长长的嵌套 IF 时不用一直挡着表格。", "把資料編輯列拉高成好幾列，再收回去；看長長的嵌套 IF 時不用一直擋著表格。"],
  'excel-name-manager': ["이름 붙인 범위를 다루는 창을 엽니다. 윈도우의 Ctrl+F3은 이름 목록 전체를 관리하는 창이고, 맥의 Cmd+F3은 새 이름을 정하는 창입니다.", "Opens the window for named ranges; Ctrl+F3 on Windows manages the whole list of names, while Cmd+F3 on a Mac opens Define Name for one new name.", "Abre la ventana de rangos con nombre; Ctrl+F3 en Windows gestiona toda la lista, mientras Cmd+F3 en Mac abre Define Name para un nombre nuevo.", "Abre a janela de intervalos nomeados; Ctrl+F3 no Windows gerencia a lista toda, enquanto Cmd+F3 no Mac abre Define Name para um nome novo.", "名前を付けた範囲を扱う画面を開きます。Windows の Ctrl+F3 は名前の一覧を管理する画面で、Mac の Cmd+F3 は新しい名前を決める画面です。", "Öffnet das Fenster für benannte Bereiche; Ctrl+F3 verwaltet unter Windows die ganze Namensliste, Cmd+F3 öffnet auf dem Mac Define Name für einen neuen Namen.", "Ouvre la fenêtre des plages nommées ; sous Windows, Ctrl+F3 gère toute la liste des noms, tandis que sur Mac Cmd+F3 ouvre Define Name pour un nom neuf.", "नामित range वाली window खोलता है; Windows का Ctrl+F3 पूरी नाम-सूची संभालता है, जबकि Mac का Cmd+F3 एक नए नाम के लिए Define Name खोलता है।", "打开命名区域的窗口；Windows 的 Ctrl+F3 管理整份名称清单，而 Mac 的 Cmd+F3 打开 Define Name 新建一个名称。", "開啟命名範圍的視窗；Windows 的 Ctrl+F3 管理整份名稱清單，而 Mac 的 Cmd+F3 開啟 Define Name 新建一個名稱。"],
  'excel-toggle-filter': ["머리글에 필터 화살표를 켜거나 끕니다. 끄면 걸어 둔 조건까지 함께 사라지니, 잠시 다 보고 싶을 때는 조건만 지우는 편이 낫습니다.", "Turns the filter arrows on the header row on and off; switching it off throws away the conditions you set, so clear the filter instead when you only want to peek at everything.", "Activa y desactiva las flechas de filtro en la fila de encabezado; al apagarlas se pierden las condiciones, así que si solo quieres verlo todo, mejor limpia el filtro.", "Liga e desliga as setas de filtro na linha de cabeçalho; desligar joga fora as condições, então se você só quer ver tudo, limpe o filtro em vez disso.", "見出し行のフィルターの矢印を出したり消したりします。消すと設定した条件も一緒に失われるので、一時的に全部見たいだけなら条件を解除するほうが賢明です。", "Schaltet die Filterpfeile in der Kopfzeile ein und aus; beim Ausschalten gehen die gesetzten Bedingungen verloren — wollen Sie nur kurz alles sehen, heben Sie besser den Filter auf.", "Active et désactive les flèches de filtre de la ligne d en-tête ; en désactivant, les conditions posées disparaissent, donc pour tout voir un instant mieux vaut effacer le filtre.", "header पंक्ति के filter तीर चालू-बंद करता है; बंद करने पर लगाई शर्तें भी चली जाती हैं, इसलिए थोड़ी देर सब देखना हो तो केवल शर्त हटाना बेहतर है।", "打开或关掉标题行上的筛选箭头；关掉会连你设的条件一起丢掉，只想临时看全部时，不如先清除筛选条件。", "開啟或關掉標題列上的篩選箭頭；關掉會連你設的條件一起丟掉，只想暫時看全部時，不如先清除篩選條件。"],
  'excel-create-table': ["고른 범위를 머리글과 이름을 가진 진짜 표로 바꿉니다. 맥에서는 같은 Cmd+T가 수식을 고치는 중에는 참조 꼴을 바꾸는 키라서 상황을 봐야 합니다.", "Turns the selected range into a real table with headers and a name; on a Mac the very same Cmd+T switches reference styles while you are editing a formula, so context decides.", "Convierte el rango seleccionado en una tabla real con encabezados y nombre; en Mac ese mismo Cmd+T cambia el tipo de referencia si estás editando una fórmula, así que depende del contexto.", "Converte o intervalo selecionado em uma tabela real com cabeçalhos e nome; no Mac o mesmo Cmd+T troca o estilo de referência quando você edita uma fórmula, então o contexto decide.", "選んだ範囲を、見出しと名前を持つ本当のテーブルにします。Mac では同じ Cmd+T が数式編集中は参照の形を切り替えるキーなので、状況で意味が変わります。", "Verwandelt den markierten Bereich in eine echte Tabelle mit Kopfzeile und Namen; auf dem Mac wechselt genau dasselbe Cmd+T beim Bearbeiten einer Formel den Bezugstyp — der Kontext entscheidet.", "Transforme la plage sélectionnée en véritable tableau avec en-têtes et nom ; sur Mac, ce même Cmd+T change le type de référence pendant l édition d une formule, tout dépend du contexte.", "चुनी हुई range को header और नाम वाली असली Table बना देता है; Mac पर वही Cmd+T formula लिखते समय reference का रूप बदलता है, इसलिए संदर्भ मायने रखता है।", "把选中的区域变成带标题和名称的真正表格；在 Mac 上，同一个 Cmd+T 在编辑公式时是切换引用形式，得看当时的上下文。", "把選取的區域變成帶標題和名稱的真正表格；在 Mac 上，同一個 Cmd+T 在編輯公式時是切換參照形式，得看當時的情境。"],
  'excel-find': ["시트나 문서 전체에서 글자를 찾습니다. 기본은 보이는 값을 뒤지므로, 수식 안의 글자를 찾으려면 Options에서 찾는 곳을 Formulas로 바꿔야 합니다.", "Searches the sheet or the whole workbook for text; by default it looks at what is displayed, so switch Look in to Formulas to search inside formulas.", "Busca texto en la hoja o en todo el libro; por defecto mira lo que se muestra, así que cambia Look in a Formulas para buscar dentro de las fórmulas.", "Procura texto na planilha ou em toda a pasta; por padrão olha o que está exibido, então mude Look in para Formulas para buscar dentro das fórmulas.", "シートやブック全体から文字を探します。既定では表示されている値を見るので、数式の中を探すには Options で探す場所を Formulas に変えます。", "Sucht Text im Blatt oder in der ganzen Arbeitsmappe; standardmäßig prüft es das Angezeigte, für die Suche in Formeln stellen Sie Look in auf Formulas.", "Cherche du texte dans la feuille ou tout le classeur ; par défaut il regarde ce qui est affiché, passez Look in à Formulas pour chercher dans les formules.", "sheet या पूरी workbook में text खोजता है; डिफ़ॉल्ट रूप से यह दिखने वाले मान देखता है, इसलिए formula के भीतर खोजने के लिए Look in को Formulas करें।", "在工作表或整个工作簿里找文字；默认只查显示出来的值，要在公式里找，得把 Look in 改成 Formulas。", "在工作表或整個工作簿裡找文字；預設只查顯示出來的值，要在公式裡找，得把 Look in 改成 Formulas。"],
  'excel-replace': ["찾은 글자를 다른 글자로 바꿉니다. 맥에서 Cmd+H는 앱을 숨기는 키라서, 엑셀의 바꾸기는 Cmd+Shift+H입니다.", "Replaces what you find with something else; on a Mac Cmd+H hides the app, which is why replace lives on Cmd+Shift+H.", "Sustituye lo encontrado por otra cosa; en Mac Cmd+H oculta la aplicación, por eso reemplazar está en Cmd+Shift+H.", "Substitui o que foi encontrado por outra coisa; no Mac Cmd+H esconde o aplicativo, por isso substituir fica em Cmd+Shift+H.", "見つけた文字を別の文字に置き換えます。Mac の Cmd+H はアプリを隠すキーなので、置換は Cmd+Shift+H に置かれています。", "Ersetzt das Gefundene durch etwas anderes; auf dem Mac blendet Cmd+H die App aus, deshalb liegt Ersetzen auf Cmd+Shift+H.", "Remplace ce qui est trouvé par autre chose ; sur Mac, Cmd+H masque l application, d où le remplacement sur Cmd+Shift+H.", "मिले हुए text को किसी और से बदल देता है; Mac पर Cmd+H app छिपाता है, इसलिए replace Cmd+Shift+H पर है।", "把找到的文字换成别的；Mac 上 Cmd+H 是隐藏应用，所以替换放在 Cmd+Shift+H。", "把找到的文字換成別的；Mac 上 Cmd+H 是隱藏應用程式，所以取代放在 Cmd+Shift+H。"],
  'excel-freeze-panes': ["머리글 줄을 화면에 붙여 두고 아래만 굴립니다. 윈도우도 맥도 기본 조합이 없어 View 메뉴로 가야 하고, 고정선은 고른 칸의 위와 왼쪽에 그어지니 머리글 바로 아래 칸을 먼저 골라야 합니다.", "Pins the header rows so only the body scrolls; neither platform has a default combination, so you use the View menu, and the line is drawn above and to the left of the selected cell — pick the cell just below the headers first.", "Fija las filas de encabezado y solo se desplaza el cuerpo; ninguna plataforma tiene combinación por defecto, se usa el menú View, y la línea se traza arriba y a la izquierda de la celda seleccionada, así que elige primero la celda bajo los encabezados.", "Fixa as linhas de cabeçalho e só o corpo rola; nenhuma plataforma tem combinação padrão, use o menu View, e a linha é traçada acima e à esquerda da célula selecionada, então escolha primeiro a célula logo abaixo dos cabeçalhos.", "見出し行を画面に留めて本体だけを送ります。Windows も Mac も既定の組み合わせが無いので View メニューを使い、固定線は選んだセルの上と左に引かれるため、見出しのすぐ下のセルを先に選びます。", "Heftet die Kopfzeilen an, sodass nur der Rumpf scrollt; keine Plattform hat eine Standardtastenfolge, man nutzt das Menü View, und die Linie verläuft über und links der markierten Zelle — wählen Sie zuerst die Zelle direkt unter den Kopfzeilen.", "Épingle les lignes d en-tête pour ne faire défiler que le corps ; aucune plateforme n a de combinaison par défaut, on passe par le menu View, et la ligne se trace au-dessus et à gauche de la cellule sélectionnée, donc choisissez d abord la cellule juste sous les en-têtes.", "header पंक्तियों को स्क्रीन पर टिका देता है और केवल बाक़ी हिस्सा चलता है; किसी platform पर डिफ़ॉल्ट combination नहीं है, View मेनू से करना पड़ता है, और रेखा चुनी हुई cell के ऊपर और बाईं ओर खिंचती है, इसलिए पहले header के ठीक नीचे की cell चुनें।", "把标题行钉在屏幕上，只滚动下面的内容；两个平台都没有默认组合，要走 View 菜单，而冻结线画在所选单元格的上方和左侧，所以先选标题下面那一格。", "把標題列釘在畫面上，只捲動下面的內容；兩個平台都沒有預設組合，要走 View 選單，而凍結線畫在所選儲存格的上方和左側，所以先選標題下面那一格。"],
  'excel-save-as': ["새 이름이나 다른 형식으로 저장하는 창을 엽니다. 맥은 F12가 아니라 Cmd+Shift+S입니다.", "Opens the dialog for saving under a new name or another format; on a Mac it is Cmd+Shift+S rather than F12.", "Abre el cuadro para guardar con otro nombre o formato; en Mac es Cmd+Shift+S y no F12.", "Abre a caixa para salvar com outro nome ou formato; no Mac é Cmd+Shift+S e não F12.", "別の名前や別の形式で保存する画面を開きます。Mac では F12 ではなく Cmd+Shift+S です。", "Öffnet den Dialog zum Speichern unter neuem Namen oder anderem Format; auf dem Mac ist es Cmd+Shift+S statt F12.", "Ouvre la boîte pour enregistrer sous un autre nom ou format ; sur Mac c est Cmd+Shift+S et non F12.", "नए नाम या दूसरे format में सहेजने का box खोलता है; Mac पर यह F12 नहीं बल्कि Cmd+Shift+S है।", "打开用新名字或别的格式保存的对话框；Mac 上是 Cmd+Shift+S，不是 F12。", "開啟用新名字或別的格式儲存的對話框；Mac 上是 Cmd+Shift+S，不是 F12。"],
  'excel-print-preview': ["인쇄했을 때 어떻게 잘리는지 미리 봅니다. 윈도우에만 있는 조합이고, 맥에서는 Cmd+P로 뜬 인쇄 창 안에서 미리보기를 봅니다.", "Shows how the sheet will break across pages before you print; the combination is Windows only, and on a Mac the preview sits inside the Cmd+P print dialog.", "Muestra cómo se cortará la hoja al imprimir; la combinación es solo de Windows, y en Mac la vista previa está dentro del cuadro de impresión de Cmd+P.", "Mostra como a planilha vai se dividir nas páginas antes de imprimir; a combinação é só do Windows, e no Mac a prévia fica dentro da caixa de impressão do Cmd+P.", "印刷したときにどこで切れるかを先に見せます。組み合わせは Windows だけで、Mac では Cmd+P の印刷画面の中にプレビューがあります。", "Zeigt vor dem Drucken, wie das Blatt auf die Seiten fällt; die Tastenfolge gibt es nur unter Windows, auf dem Mac steckt die Vorschau im Druckdialog von Cmd+P.", "Montre comment la feuille se découpera à l impression ; la combinaison n existe que sous Windows, sur Mac l aperçu est dans la boîte d impression de Cmd+P.", "छापने से पहले दिखाता है कि sheet पन्नों पर कहाँ कटेगी; यह combination केवल Windows पर है, Mac पर यह झलक Cmd+P के print box के भीतर होती है।", "在打印前看清表格会怎样分页；这个组合只有 Windows 有，Mac 的预览在 Cmd+P 的打印窗口里。", "在列印前看清表格會怎樣分頁；這個組合只有 Windows 有，Mac 的預覽在 Cmd+P 的列印視窗裡。"],
  'excel-insert-comment': ["답글을 달 수 있는 요즘 방식의 댓글을 붙입니다. Shift만 없이 Shift+F2를 누르면 옛 방식의 메모(note)가 붙으니 둘을 섞지 않도록 합니다.", "Attaches a modern threaded comment that others can reply to; plain Shift+F2 inserts the old-style note instead, and the two are not the same thing.", "Añade un comentario moderno con respuestas; Shift+F2 a secas inserta la nota antigua, y no son lo mismo.", "Adiciona um comentário moderno com respostas; Shift+F2 sozinho insere a nota antiga, e os dois não são a mesma coisa.", "返信できる今のかたちのコメントを付けます。Shift+F2 だけなら昔のメモ(note)が付き、両者は別物です。", "Hängt einen modernen Kommentar mit Antwortfunktion an; einfaches Shift+F2 fügt dagegen die alte Notiz ein, und beides ist nicht dasselbe.", "Ajoute un commentaire moderne auquel on peut répondre ; Shift+F2 seul insère l ancienne note, et les deux ne sont pas la même chose.", "जवाब देने योग्य आजकल का comment जोड़ता है; अकेला Shift+F2 पुराने ढंग का note डालता है, और दोनों एक चीज़ नहीं हैं।", "插入可以回复的新式批注；只按 Shift+F2 插入的是旧式备注，两者不是一回事。", "插入可以回覆的新式註解；只按 Shift+F2 插入的是舊式附註，兩者不是一回事。"],
  'excel-spell-check': ["시트나 고른 범위의 철자를 훑습니다. 수식 자체는 건너뛰고 눈에 보이는 글자만 봅니다.", "Runs a spell check over the sheet or the selected range, skipping the formulas and looking only at visible text.", "Revisa la ortografía de la hoja o del rango seleccionado, saltándose las fórmulas y mirando solo el texto visible.", "Faz a verificação ortográfica na planilha ou no intervalo selecionado, pulando as fórmulas e olhando só o texto visível.", "シートや選んだ範囲の綴りを調べます。数式そのものは飛ばし、目に見える文字だけを見ます。", "Prüft die Rechtschreibung im Blatt oder im markierten Bereich, überspringt die Formeln und sieht nur den sichtbaren Text.", "Vérifie l orthographe de la feuille ou de la plage sélectionnée, en ignorant les formules et en ne regardant que le texte visible.", "sheet या चुनी हुई range की वर्तनी जाँचता है, formula छोड़ देता है और केवल दिखने वाला text देखता है।", "对工作表或选中区域做拼写检查；跳过公式本身，只看看得见的文字。", "對工作表或選取區域做拼字檢查；跳過公式本身，只看看得見的文字。"],
  /* ═════════ sheets ═════════ */
  'sheets-tool-finder': ["메뉴 이름을 치면 그 기능으로 바로 갑니다. 단축키가 없는 기능에 닿는 가장 빠른 길이고, 맥에서는 Option+/입니다.", "Type the name of a menu item and it takes you straight there; it is the fastest way to reach anything that has no shortcut, and on a Mac it is Option+/.", "Escribe el nombre de una opción del menú y te lleva directo; es la vía más rápida para lo que no tiene atajo, y en Mac es Option+/.", "Digite o nome de um item de menu e ele leva você direto; é o caminho mais rápido para o que não tem atalho, e no Mac é Option+/.", "メニュー名を打つとその機能へ直行します。ショートカットが無い機能に届く最短の道で、Mac では Option+/ です。", "Tippen Sie den Namen eines Menüpunkts, und es geht direkt dorthin; der schnellste Weg zu allem ohne eigenes Tastenkürzel, auf dem Mac Option+/.", "Tapez le nom d un élément de menu et vous y êtes conduit directement ; c est la voie la plus rapide vers ce qui n a pas de raccourci, et sur Mac c est Option+/.", "मेनू का नाम टाइप करें और यह सीधे उस काम पर ले जाता है; जिन चीज़ों का shortcut नहीं है उन तक पहुँचने का सबसे तेज़ रास्ता, और Mac पर यह Option+/ है।", "输入菜单项的名字，它就直接带你过去；这是抵达那些没有快捷键的功能最快的办法，Mac 上是 Option+/。", "輸入選單項目的名字，它就直接帶你過去；這是抵達那些沒有快速鍵的功能最快的辦法，Mac 上是 Option+/。"],
  'sheets-shortcut-list': ["단축키 목록을 화면에 그대로 띄웁니다. 시트마다 다른 것을 외울 필요 없이 여기서 찾는 편이 빠릅니다.", "Puts the whole shortcut list on screen, which beats memorising the ones you use twice a year.", "Muestra en pantalla la lista completa de atajos, mejor que memorizar los que usas dos veces al año.", "Mostra na tela a lista completa de atalhos, melhor do que memorizar os que você usa duas vezes por ano.", "ショートカットの一覧をそのまま画面に出します。年に二度しか使わないものを覚えるより、ここで探すほうが速いです。", "Zeigt die komplette Kürzelliste auf dem Bildschirm — bequemer, als sich die zwei Mal im Jahr benötigten zu merken.", "Affiche à l écran la liste complète des raccourcis, plus pratique que de retenir ceux qu on utilise deux fois par an.", "पूरी shortcut सूची स्क्रीन पर दिखा देता है, जिन्हें साल में दो बार इस्तेमाल करते हैं उन्हें याद रखने से यह बेहतर है।", "把整份快捷键清单直接显示在屏幕上，比去记那些一年只用两次的组合省事。", "把整份快速鍵清單直接顯示在螢幕上，比去記那些一年只用兩次的組合省事。"],
  'sheets-insert-rows-or-columns': ["행을 골라 두었으면 위에, 열을 골라 두었으면 왼쪽에 새로 끼워 넣습니다. 무엇이 들어가는지는 조합이 아니라 먼저 무엇을 골랐는지가 정합니다.", "Inserts above when rows are selected and to the left when columns are selected; what appears is decided by your selection, not by the keys.", "Inserta arriba si hay filas seleccionadas y a la izquierda si hay columnas; lo que aparece lo decide tu selección, no las teclas.", "Insere acima quando linhas estão selecionadas e à esquerda quando colunas estão; o que aparece é decidido pela seleção, não pelas teclas.", "行を選んでいれば上に、列を選んでいれば左に挿入します。何が入るかはキーではなく、先に何を選んだかで決まります。", "Fügt bei markierten Zeilen darüber und bei markierten Spalten links ein; was erscheint, entscheidet die Auswahl, nicht die Tasten.", "Insère au-dessus si des lignes sont sélectionnées, à gauche si ce sont des colonnes ; c est la sélection qui décide, pas les touches.", "rows चुनी हों तो ऊपर और columns चुने हों तो बाईं ओर नया जोड़ देता है; क्या जुड़ेगा यह कुंजियाँ नहीं, आपका चयन तय करता है।", "选中的是行就在上面插入，选中的是列就在左边插入；插进来的是什么，由你的选择决定，不是由按键决定。", "選取的是列就在上面插入，選取的是欄就在左邊插入；插進來的是什麼，由你的選擇決定，不是由按鍵決定。"],
  'sheets-delete-rows-or-columns': ["골라 둔 행이나 열을 없앱니다. Delete는 내용만 비우지만 이것은 줄 자체를 걷어내 아래나 오른쪽이 당겨 올라옵니다.", "Removes the rows or columns you selected; Delete would only clear the contents, while this takes the lines away and pulls the rest in.", "Elimina las filas o columnas seleccionadas; Delete solo vaciaría el contenido, esto quita las líneas y el resto se desplaza.", "Remove as linhas ou colunas selecionadas; Delete só limparia o conteúdo, isto retira as linhas e o resto se desloca.", "選んだ行や列を削除します。Delete は中身を空にするだけですが、これは行自体を取り除き、下や右が寄ってきます。", "Entfernt die markierten Zeilen oder Spalten; Delete würde nur den Inhalt leeren, dies nimmt die Linien weg und der Rest rückt nach.", "Supprime les lignes ou colonnes sélectionnées ; Delete ne viderait que le contenu, ici les lignes disparaissent et le reste se rapproche.", "चुनी हुई rows या columns हटा देता है; Delete केवल सामग्री ख़ाली करता, यह पंक्ति ही उठा लेता है और बाक़ी खिंच आता है।", "删掉选中的行或列；Delete 只是清空内容，而这是把整条抽走，后面的会补上来。", "刪掉選取的列或欄；Delete 只是清空內容，而這是把整條抽走，後面的會補上來。"],
  'sheets-insert-row-below': ["아래쪽에 행 하나를 끼워 넣습니다. 한 번에 누르는 조합이 아니라 메뉴를 밟는 순서이고, 크롬이 아닌 브라우저에서는 첫 걸음이 Alt+Shift+I가 됩니다.", "Adds one row below; this is a menu walk pressed in order rather than one combination, and in browsers other than Chrome the first step becomes Alt+Shift+I.", "Añade una fila debajo; no es una combinación sino un recorrido de menú pulsado en orden, y en navegadores que no son Chrome el primer paso es Alt+Shift+I.", "Adiciona uma linha abaixo; não é uma combinação, mas um caminho de menu pressionado em ordem, e em navegadores que não sejam Chrome o primeiro passo vira Alt+Shift+I.", "下に行を一つ挿入します。同時押しではなく順に押すメニューの道筋で、Chrome 以外のブラウザーでは最初が Alt+Shift+I になります。", "Fügt eine Zeile darunter ein; das ist kein Griff, sondern ein Menüweg in Reihenfolge, und in anderen Browsern als Chrome lautet der erste Schritt Alt+Shift+I.", "Ajoute une ligne en dessous ; ce n est pas une combinaison mais un parcours de menu appuyé dans l ordre, et hors de Chrome la première étape devient Alt+Shift+I.", "नीचे एक row जोड़ता है; यह एक साथ दबाने वाला combination नहीं, क्रम से दबाने वाला मेनू-रास्ता है, और Chrome के अलावा दूसरे browser में पहला कदम Alt+Shift+I हो जाता है।", "在下面插入一行；这不是一次按完的组合，而是按顺序走菜单，在非 Chrome 浏览器里第一步变成 Alt+Shift+I。", "在下面插入一列；這不是一次按完的組合，而是按順序走選單，在非 Chrome 瀏覽器裡第一步變成 Alt+Shift+I。"],
  'sheets-insert-column-right': ["오른쪽에 열 하나를 끼워 넣습니다. 이것도 순서대로 밟는 메뉴 길이라, 마지막 O는 숫자 0이 아니라 알파벳 O입니다.", "Adds one column to the right; it is another menu walk pressed in order, and the last key is the letter O, not a zero.", "Añade una columna a la derecha; es otro recorrido de menú en orden, y la última tecla es la letra O, no un cero.", "Adiciona uma coluna à direita; é outro caminho de menu em ordem, e a última tecla é a letra O, não um zero.", "右に列を一つ挿入します。これも順に押すメニューの道筋で、最後の O は数字の 0 ではなく英字の O です。", "Fügt eine Spalte rechts ein; ebenfalls ein Menüweg in Reihenfolge, und die letzte Taste ist der Buchstabe O, keine Null.", "Ajoute une colonne à droite ; encore un parcours de menu dans l ordre, et la dernière touche est la lettre O, pas un zéro.", "दाईं ओर एक column जोड़ता है; यह भी क्रम से चलने वाला मेनू-रास्ता है, और अंतिम कुंजी अक्षर O है, शून्य नहीं।", "在右边插入一列；同样是按顺序走菜单，最后一个是字母 O，不是数字 0。", "在右邊插入一欄；同樣是按順序走選單，最後一個是字母 O，不是數字 0。"],
  'sheets-select-column': ["칸이 놓인 열 전체를 고릅니다. 맥에서 Cmd+Space는 Spotlight가 가져가므로, 시트는 두 운영체제 모두 Ctrl+Space를 씁니다.", "Selects the whole column the cell sits in; Cmd+Space belongs to Spotlight on a Mac, so Sheets keeps Ctrl+Space on both systems.", "Selecciona toda la columna de la celda; en Mac Cmd+Space es de Spotlight, por eso Sheets usa Ctrl+Space en los dos sistemas.", "Seleciona a coluna inteira da célula; no Mac Cmd+Space pertence ao Spotlight, então o Sheets usa Ctrl+Space nos dois sistemas.", "セルのある列を丸ごと選びます。Mac では Cmd+Space が Spotlight に取られるため、Sheets は両方の環境で Ctrl+Space を使います。", "Markiert die ganze Spalte der Zelle; Cmd+Space gehört auf dem Mac zu Spotlight, daher nutzt Sheets auf beiden Systemen Ctrl+Space.", "Sélectionne toute la colonne de la cellule ; Cmd+Space appartient à Spotlight sur Mac, donc Sheets garde Ctrl+Space sur les deux systèmes.", "जिस column में cell है उसे पूरा चुनता है; Mac पर Cmd+Space Spotlight का है, इसलिए Sheets दोनों systems पर Ctrl+Space रखता है।", "选中该单元格所在的整列；Mac 上 Cmd+Space 归 Spotlight，所以 Sheets 在两个系统里都用 Ctrl+Space。", "選取該儲存格所在的整欄；Mac 上 Cmd+Space 歸 Spotlight，所以 Sheets 在兩個系統裡都用 Ctrl+Space。"],
  'sheets-select-row': ["칸이 놓인 행 전체를 고릅니다. 이 상태에서 Ctrl+Alt+Minus를 누르면 그 행이 통째로 사라집니다.", "Selects the whole row the cell sits in; with the row selected, Ctrl+Alt+Minus deletes that entire row.", "Selecciona toda la fila de la celda; con la fila seleccionada, Ctrl+Alt+Minus borra esa fila entera.", "Seleciona a linha inteira da célula; com a linha selecionada, Ctrl+Alt+Minus apaga a linha toda.", "セルのある行を丸ごと選びます。行を選んだ状態で Ctrl+Alt+Minus を押すと、その行がまるごと消えます。", "Markiert die ganze Zeile der Zelle; ist die Zeile markiert, löscht Ctrl+Alt+Minus die komplette Zeile.", "Sélectionne toute la ligne de la cellule ; la ligne étant sélectionnée, Ctrl+Alt+Minus supprime la ligne entière.", "जिस row में cell है उसे पूरा चुनता है; row चुनी हो तो Ctrl+Alt+Minus उस पूरी row को मिटा देता है।", "选中该单元格所在的整行；选好整行后按 Ctrl+Alt+Minus，这一行会整条被删掉。", "選取該儲存格所在的整列；選好整列後按 Ctrl+Alt+Minus，這一列會整條被刪掉。"],
  'sheets-fill-down': ["위 칸을 아래로 고른 칸들에 채웁니다. 엑셀과 조합이 같지만, 시트는 채운 뒤에도 원본 칸의 조건부 서식을 함께 가져옵니다.", "Fills the selected cells below with the cell above; the combination matches Excel, and Sheets carries the conditional formatting of the source cell along with it.", "Rellena hacia abajo las celdas seleccionadas con la celda superior; la combinación coincide con Excel, y Sheets arrastra también el formato condicional del origen.", "Preenche para baixo as células selecionadas com a célula de cima; a combinação é igual à do Excel, e o Sheets leva também a formatação condicional da origem.", "上のセルを、選んだ下のセルへ埋めます。組み合わせは Excel と同じですが、Sheets は元のセルの条件付き書式まで一緒に運びます。", "Füllt die markierten Zellen darunter mit der Zelle darüber; die Tastenfolge entspricht Excel, und Sheets nimmt die bedingte Formatierung der Quellzelle mit.", "Remplit vers le bas les cellules sélectionnées avec celle du dessus ; la combinaison est celle d Excel, et Sheets emporte aussi la mise en forme conditionnelle de la source.", "ऊपर वाली cell से नीचे चुनी cells भर देता है; combination Excel जैसा ही है, और Sheets स्रोत cell की conditional formatting भी साथ ले आता है।", "用上面一格填满下方选中的单元格；组合与 Excel 相同，而且 Sheets 会把源单元格的条件格式一起带过来。", "用上面一格填滿下方選取的儲存格；組合與 Excel 相同，而且 Sheets 會把來源儲存格的條件格式一起帶過來。"],
  'sheets-fill-right': ["왼쪽 칸을 오른쪽으로 고른 칸들에 채웁니다. 수식 안의 상대 참조는 한 칸씩 밀려 A1이 B1이 됩니다.", "Fills the selected cells to the right with the cell on the left, and relative references shift along, so A1 becomes B1.", "Rellena hacia la derecha con la celda de la izquierda, y las referencias relativas se desplazan, así que A1 pasa a B1.", "Preenche à direita com a célula da esquerda, e as referências relativas se deslocam, então A1 vira B1.", "左のセルを、選んだ右のセルへ埋めます。相対参照は一つずつずれ、A1 は B1 になります。", "Füllt die markierten Zellen rechts mit der Zelle links; relative Bezüge verschieben sich mit, aus A1 wird B1.", "Remplit vers la droite avec la cellule de gauche ; les références relatives se décalent, A1 devient B1.", "बाईं cell से दाईं ओर चुनी cells भर देता है, और सापेक्ष reference खिसकते हैं, इसलिए A1 का B1 बन जाता है।", "用左边一格填满右侧选中的单元格；相对引用会跟着挪，A1 变成 B1。", "用左邊一格填滿右側選取的儲存格；相對參照會跟著挪，A1 變成 B1。"],
  'sheets-insert-link': ["고른 칸에 링크를 답니다. 칸에 글이 있으면 그 글이 링크가 되고, 시트 안의 다른 시트나 범위도 여기서 고를 수 있습니다.", "Adds a link to the selected cell; existing text becomes the link, and the same box also offers other sheets and ranges inside the file.", "Añade un enlace a la celda seleccionada; el texto existente se convierte en enlace, y el mismo cuadro ofrece otras hojas y rangos del archivo.", "Adiciona um link à célula selecionada; o texto existente vira o link, e a mesma caixa também oferece outras abas e intervalos do arquivo.", "選んだセルにリンクを付けます。文字があればそれがリンクになり、同じ画面からファイル内の別のシートや範囲も選べます。", "Fügt der markierten Zelle einen Link hinzu; vorhandener Text wird der Link, und dasselbe Feld bietet auch andere Blätter und Bereiche der Datei an.", "Ajoute un lien à la cellule sélectionnée ; le texte présent devient le lien, et la même boîte propose aussi d autres feuilles et plages du fichier.", "चुनी हुई cell में link जोड़ता है; पहले से लिखा text ही link बन जाता है, और उसी box में फ़ाइल की दूसरी sheet और range भी मिलती हैं।", "给选中的单元格加链接；已有文字会变成链接，同一个框里也能选文件内的其他工作表和区域。", "給選取的儲存格加連結；已有文字會變成連結，同一個框裡也能選檔案內的其他工作表和區域。"],
  'sheets-insert-date': ["오늘 날짜를 고정된 값으로 적어 넣습니다. 맥에서는 Cmd+;인데, 같은 자리에서 엑셀은 Ctrl+;을 쓰므로 두 앱을 오가면 헷갈립니다.", "Types today date in as a fixed value; on a Mac it is Cmd+; whereas Excel wants Ctrl+; for the same job, which is easy to mix up.", "Escribe la fecha de hoy como valor fijo; en Mac es Cmd+; mientras Excel pide Ctrl+; para lo mismo, algo fácil de confundir.", "Escreve a data de hoje como valor fixo; no Mac é Cmd+; enquanto o Excel pede Ctrl+; para a mesma coisa, fácil de confundir.", "今日の日付を固定値として書き込みます。Mac では Cmd+; ですが、同じ用途で Excel は Ctrl+; なので行き来すると混乱します。", "Trägt das heutige Datum als festen Wert ein; auf dem Mac ist es Cmd+;, während Excel für dieselbe Aufgabe Ctrl+; erwartet — leicht zu verwechseln.", "Écrit la date du jour comme valeur figée ; sur Mac c est Cmd+; alors qu Excel demande Ctrl+; pour la même chose, facile à confondre.", "आज की तारीख़ स्थिर मान के रूप में भरता है; Mac पर यह Cmd+; है जबकि Excel उसी काम के लिए Ctrl+; चाहता है, इसलिए गड़बड़ होना आसान है।", "把今天的日期作为固定值写进去；Mac 上是 Cmd+;，而 Excel 做同一件事要 Ctrl+;，两边来回很容易记错。", "把今天的日期作為固定值寫進去；Mac 上是 Cmd+;，而 Excel 做同一件事要 Ctrl+;，兩邊來回很容易記錯。"],
  'sheets-insert-time': ["지금 시각을 고정된 값으로 적어 넣습니다. 날짜 조합에 Shift만 더한 꼴이라, 함께 외우면 잊지 않습니다.", "Types the current time in as a fixed value; it is the date shortcut plus Shift, which makes the pair easy to remember together.", "Escribe la hora actual como valor fijo; es el atajo de la fecha más Shift, así que la pareja se recuerda junta.", "Escreve a hora atual como valor fixo; é o atalho da data mais Shift, então o par fica fácil de lembrar junto.", "現在の時刻を固定値として書き込みます。日付の組み合わせに Shift を足した形なので、対で覚えると忘れません。", "Trägt die aktuelle Uhrzeit als festen Wert ein; es ist das Datumskürzel plus Shift, das Paar merkt man sich zusammen.", "Écrit l heure actuelle comme valeur figée ; c est le raccourci de la date plus Shift, la paire se retient d un coup.", "अभी का समय स्थिर मान के रूप में भरता है; यह तारीख़ वाले shortcut में Shift जोड़ना है, इसलिए जोड़ी एक साथ याद रहती है।", "把当前时间作为固定值写进去；就是日期那个组合再加 Shift，配成一对就不容易忘。", "把目前時間作為固定值寫進去；就是日期那個組合再加 Shift，配成一對就不容易忘。"],
  'sheets-paste-values-only': ["서식과 수식을 버리고 값만 붙입니다. 웹에서 표를 복사해 올 때 색과 글꼴이 따라오는 것을 막는 키입니다.", "Pastes only the values, leaving formatting and formulas behind; it is what stops colours and fonts riding along when you copy a table from a web page.", "Pega solo los valores, sin formato ni fórmulas; es lo que evita que colores y tipografías te sigan al copiar una tabla de una web.", "Cola somente os valores, sem formatação nem fórmulas; é o que impede cores e fontes de vir junto ao copiar uma tabela da web.", "書式や数式を捨てて値だけを貼ります。ウェブから表を写すとき、色やフォントが付いてくるのを止めるキーです。", "Fügt nur die Werte ein, ohne Formate und Formeln; damit verhindern Sie, dass Farben und Schriften beim Kopieren einer Webtabelle mitkommen.", "Ne colle que les valeurs, sans mise en forme ni formules ; c est ce qui empêche couleurs et polices de suivre quand on copie un tableau du web.", "केवल मान चिपकाता है, formatting और formula छोड़ देता है; वेब से table copy करते समय रंग और font साथ आने से यही रोकता है।", "只粘值，把格式和公式都丢掉；从网页上复制表格时，就是靠它挡住颜色和字体跟过来。", "只貼值，把格式和公式都丟掉；從網頁上複製表格時，就是靠它擋住顏色和字體跟過來。"],
  'sheets-paste-special': ["서식만·행열 바꿈·조건부 서식만처럼 무엇을 붙일지 고르는 창을 엽니다. 이 조합은 브라우저나 자판 배열이 가로채는 일이 있어 Alt+/로 메뉴에서 찾는 길도 알아 두면 좋습니다.", "Opens the box where you choose format only, transposed, conditional formatting only and the rest; a browser or keyboard layout can swallow this combination, so knowing the Alt+/ menu route helps.", "Abre el cuadro donde eliges solo formato, transpuesto, solo formato condicional y demás; un navegador o una distribución de teclado puede interceptarlo, así que conviene conocer la ruta con Alt+/.", "Abre a caixa onde você escolhe somente formato, transposto, somente formatação condicional e o resto; um navegador ou layout de teclado pode engolir essa combinação, então vale conhecer o caminho pelo Alt+/.", "書式のみ・行と列の入れ替え・条件付き書式のみなど、何を貼るかを選ぶ画面を開きます。この組み合わせはブラウザーやキー配列に横取りされることがあるので、Alt+/ からメニューで辿る道も覚えておくと安心です。", "Öffnet das Feld für nur Format, transponiert, nur bedingte Formatierung und mehr; Browser oder Tastaturlayout können diese Folge abfangen, daher hilft der Weg über das Menü mit Alt+/.", "Ouvre la boîte où l on choisit format seul, transposé, mise en forme conditionnelle seule, etc. ; un navigateur ou une disposition clavier peut intercepter cette combinaison, d où l intérêt de la route par Alt+/.", "वह box खोलता है जहाँ केवल format, पंक्ति-स्तंभ बदला हुआ, केवल conditional formatting आदि चुनते हैं; यह combination browser या keyboard layout छीन सकता है, इसलिए Alt+/ से मेनू का रास्ता जानना काम आता है।", "打开可以选择只粘格式、行列转置、只粘条件格式等的对话框；浏览器或键盘布局可能抢走这个组合，所以最好也记得用 Alt+/ 走菜单。", "開啟可以選擇只貼格式、行列轉置、只貼條件格式等的對話框；瀏覽器或鍵盤配置可能搶走這個組合，所以最好也記得用 Alt+/ 走選單。"],
  'sheets-insert-comment': ["답글이 달리고 알림이 가는 댓글을 붙입니다. 아래의 메모(note)와 달리 사람을 @로 부를 수 있습니다.", "Attaches a comment that others can reply to and that sends a notification; unlike a note it lets you call someone with @.", "Añade un comentario con respuestas y notificación; a diferencia de una nota, permite mencionar a alguien con @.", "Adiciona um comentário com respostas e notificação; diferente de uma nota, permite chamar alguém com @.", "返信でき通知も飛ぶコメントを付けます。メモ(note)と違い、@ で人を呼べます。", "Hängt einen Kommentar an, auf den geantwortet wird und der eine Benachrichtigung sendet; anders als eine Notiz erlaubt er, jemanden mit @ zu rufen.", "Ajoute un commentaire auquel on peut répondre et qui envoie une notification ; contrairement à une note, il permet d appeler quelqu un avec @.", "ऐसा comment जोड़ता है जिसका जवाब दिया जा सकता है और सूचना जाती है; note से अलग, इसमें @ से किसी को बुला सकते हैं।", "插入可以回复并会发通知的评论；和备注不同，它可以用 @ 叫人。", "插入可以回覆並會發通知的註解；和附註不同，它可以用 @ 叫人。"],
  'sheets-insert-note': ["답글도 알림도 없는 조용한 메모를 붙입니다. 칸 오른쪽 위 검은 표시로만 드러나고, 엑셀의 옛 메모와 같은 물건입니다.", "Attaches a quiet note with no replies and no notifications; it shows only as a dark mark in the corner of the cell and matches the old Excel note.", "Añade una nota silenciosa, sin respuestas ni notificaciones; solo se ve como una marca oscura en la esquina de la celda y equivale a la nota antigua de Excel.", "Adiciona uma nota silenciosa, sem respostas nem notificações; aparece apenas como uma marca escura no canto da célula e equivale à nota antiga do Excel.", "返信も通知もない静かなメモを付けます。セルの右上の黒い印だけで示され、Excel の昔のメモと同じものです。", "Hängt eine stille Notiz ohne Antworten und Benachrichtigungen an; sie zeigt sich nur als dunkles Zeichen in der Zellenecke und entspricht der alten Excel-Notiz.", "Ajoute une note discrète, sans réponse ni notification ; elle n apparaît qu en petit repère sombre dans le coin de la cellule et correspond à l ancienne note d Excel.", "बिना जवाब और बिना सूचना वाला शांत note जोड़ता है; यह केवल cell के कोने में गहरे निशान से दिखता है और Excel के पुराने note जैसा ही है।", "插入一条安静的备注，没有回复也没有通知；只在单元格角上显示一个深色小标记，和 Excel 的旧式备注是同一种东西。", "插入一條安靜的附註，沒有回覆也沒有通知；只在儲存格角上顯示一個深色小標記，和 Excel 的舊式附註是同一種東西。"],
  'sheets-bold': ["고른 칸의 글씨를 굵게 바꾸거나 되돌립니다. 기울임은 Ctrl+I, 맥은 Cmd+I로 나란히 놓여 있습니다.", "Turns the selected text bold or takes it back; italic sits right beside it on Ctrl+I, or Cmd+I on a Mac.", "Pone en negrita el texto seleccionado o lo revierte; la cursiva está al lado, en Ctrl+I o Cmd+I en Mac.", "Deixa o texto selecionado em negrito ou desfaz; o itálico fica ao lado, em Ctrl+I ou Cmd+I no Mac.", "選んだ文字を太字にしたり戻したりします。斜体はすぐ隣の Ctrl+I、Mac では Cmd+I です。", "Macht den markierten Text fett oder nimmt es zurück; Kursiv liegt direkt daneben auf Ctrl+I, auf dem Mac Cmd+I.", "Met en gras le texte sélectionné ou l annule ; l italique est juste à côté, sur Ctrl+I ou Cmd+I sur Mac.", "चुने हुए text को मोटा करता या वापस करता है; तिरछा उसके बगल में Ctrl+I पर है, Mac पर Cmd+I।", "把选中的文字加粗或取消；斜体就在旁边，Ctrl+I，Mac 上是 Cmd+I。", "把選取的文字加粗或取消；斜體就在旁邊，Ctrl+I，Mac 上是 Cmd+I。"],
  'sheets-underline': ["고른 칸의 글씨에 밑줄을 넣거나 뺍니다. 링크에 저절로 생기는 밑줄과는 다른 서식이라 따로 걸립니다.", "Adds or removes an underline in the selected cells; it is a different property from the underline a link draws by itself.", "Añade o quita el subrayado en las celdas seleccionadas; es una propiedad distinta del subrayado que dibuja un enlace por sí mismo.", "Adiciona ou remove o sublinhado nas células selecionadas; é uma propriedade diferente do sublinhado que um link desenha por conta própria.", "選んだセルの文字に下線を付けたり外したりします。リンクに自動で付く下線とは別の書式です。", "Setzt oder entfernt eine Unterstreichung in den markierten Zellen; sie ist etwas anderes als die Unterstreichung, die ein Link von selbst zeichnet.", "Ajoute ou retire un soulignement dans les cellules sélectionnées ; c est une propriété distincte du soulignement propre aux liens.", "चुनी cells के text में रेखांकन जोड़ता या हटाता है; link पर अपने आप आने वाले रेखांकन से यह अलग गुण है।", "给选中单元格的文字加或去掉下划线；这和链接自带的下划线是两种不同的格式。", "給選取儲存格的文字加或去掉底線；這和連結自帶的底線是兩種不同的格式。"],
  'sheets-strikethrough': ["글씨에 취소선을 그어 다 한 일처럼 보이게 합니다. 시트에서 가장 많이 찾는 조합인데 두 운영체제가 전혀 다르니, 윈도우는 Alt+Shift+5이고 맥은 Cmd+Shift+X입니다.", "Draws a line through the text so it reads as done; it is the most looked-up Sheets shortcut and the two systems share nothing — Alt+Shift+5 on Windows, Cmd+Shift+X on a Mac.", "Tacha el texto para que se lea como hecho; es el atajo más buscado de Sheets y los sistemas no coinciden: Alt+Shift+5 en Windows y Cmd+Shift+X en Mac.", "Risca o texto para parecer concluído; é o atalho mais procurado do Sheets e os sistemas não combinam: Alt+Shift+5 no Windows e Cmd+Shift+X no Mac.", "文字に取り消し線を引き、済んだことのように見せます。Sheets で最も検索される組み合わせなのに両環境で全く別で、Windows は Alt+Shift+5、Mac は Cmd+Shift+X です。", "Zieht einen Strich durch den Text, damit er als erledigt gilt; es ist das meistgesuchte Sheets-Kürzel, und beide Systeme haben nichts gemeinsam — Alt+Shift+5 unter Windows, Cmd+Shift+X auf dem Mac.", "Barre le texte pour le marquer comme fait ; c est le raccourci Sheets le plus recherché et les deux systèmes n ont rien en commun : Alt+Shift+5 sous Windows, Cmd+Shift+X sur Mac.", "text पर काट की रेखा खींचकर उसे पूरा हुआ जैसा दिखाता है; Sheets में सबसे ज़्यादा खोजा जाने वाला combination है और दोनों systems में कुछ भी समान नहीं — Windows पर Alt+Shift+5, Mac पर Cmd+Shift+X।", "给文字画上删除线，看着像已经做完；这是 Sheets 里被查得最多的组合，而两个系统毫无共同点：Windows 是 Alt+Shift+5，Mac 是 Cmd+Shift+X。", "給文字畫上刪除線，看著像已經做完；這是 Sheets 裡被查得最多的組合，而兩個系統毫無共同點：Windows 是 Alt+Shift+5，Mac 是 Cmd+Shift+X。"],
  'sheets-align-center': ["칸 안의 내용을 가운데로 맞춥니다. 엑셀은 윈도우에 이 조합이 없어 리본을 밟아야 하지만, 시트는 두 운영체제 모두 한 번에 됩니다.", "Centres the contents of the cell; Excel on Windows has no such combination and needs the ribbon, while Sheets gives it to you in one press on both systems.", "Centra el contenido de la celda; Excel en Windows no tiene esta combinación y exige la cinta, mientras Sheets lo hace de una vez en ambos sistemas.", "Centraliza o conteúdo da célula; o Excel no Windows não tem essa combinação e exige a faixa, enquanto o Sheets resolve de uma vez nos dois sistemas.", "セルの中身を中央に揃えます。Excel の Windows にはこの組み合わせが無くリボンを辿りますが、Sheets は両環境で一発です。", "Zentriert den Zellinhalt; Excel unter Windows kennt diese Folge nicht und braucht das Menüband, Sheets erledigt es auf beiden Systemen mit einem Griff.", "Centre le contenu de la cellule ; Excel sous Windows n a pas cette combinaison et impose le ruban, alors que Sheets le fait d une pression sur les deux systèmes.", "cell की सामग्री बीच में कर देता है; Windows के Excel में यह combination नहीं है और ribbon चलना पड़ता है, जबकि Sheets दोनों systems पर एक ही बार में कर देता है।", "把单元格内容居中；Windows 版 Excel 没有这个组合、得走功能区，而 Sheets 在两个系统上一按就好。", "把儲存格內容置中；Windows 版 Excel 沒有這個組合、得走功能區，而 Sheets 在兩個系統上一按就好。"],
  'sheets-align-left': ["칸 안의 내용을 왼쪽으로 맞춥니다. 엑셀에서 Ctrl+Shift+L은 필터를 켜고 끄는 키라서, 두 앱을 오갈 때 가장 잘 헷갈리는 자리입니다.", "Aligns the contents to the left; in Excel the very same Ctrl+Shift+L toggles the filter, which is the easiest mix-up between the two apps.", "Alinea el contenido a la izquierda; en Excel ese mismo Ctrl+Shift+L activa el filtro, la confusión más habitual entre ambas aplicaciones.", "Alinha o conteúdo à esquerda; no Excel o mesmo Ctrl+Shift+L liga o filtro, a confusão mais comum entre os dois aplicativos.", "セルの中身を左に揃えます。Excel では同じ Ctrl+Shift+L がフィルターの入り切りなので、二つのアプリを行き来すると最も混同しやすい箇所です。", "Richtet den Inhalt links aus; in Excel schaltet genau dasselbe Ctrl+Shift+L den Filter, die häufigste Verwechslung zwischen beiden Programmen.", "Aligne le contenu à gauche ; dans Excel, ce même Ctrl+Shift+L active le filtre, c est la confusion la plus courante entre les deux applications.", "सामग्री को बाईं ओर लगाता है; Excel में वही Ctrl+Shift+L filter चालू-बंद करता है, और दोनों apps के बीच यही सबसे बड़ी उलझन है।", "把内容左对齐；在 Excel 里同一个 Ctrl+Shift+L 是开关筛选，这是两个软件之间最容易搞混的地方。", "把內容靠左對齊；在 Excel 裡同一個 Ctrl+Shift+L 是開關篩選，這是兩個軟體之間最容易搞混的地方。"],
  'sheets-align-right': ["칸 안의 내용을 오른쪽으로 맞춥니다. 숫자는 기본으로 오른쪽에 붙으니, 이 키가 필요하다면 그 값이 글자로 들어와 있을 수 있습니다.", "Aligns the contents to the right; numbers already sit right by default, so needing this key can mean the value came in as text.", "Alinea el contenido a la derecha; los números ya van a la derecha por defecto, así que necesitar esta tecla puede indicar que el valor entró como texto.", "Alinha o conteúdo à direita; números já ficam à direita por padrão, então precisar dessa tecla pode indicar que o valor entrou como texto.", "セルの中身を右に揃えます。数値は既定で右に寄るので、このキーが必要なら、その値は文字列として入っている疑いがあります。", "Richtet den Inhalt rechts aus; Zahlen stehen ohnehin rechts, wer diese Taste braucht, hat den Wert womöglich als Text erfasst.", "Aligne le contenu à droite ; les nombres y sont déjà par défaut, donc avoir besoin de cette touche peut signaler une valeur saisie comme texte.", "सामग्री को दाईं ओर लगाता है; अंक डिफ़ॉल्ट रूप से दाईं ओर ही होते हैं, इसलिए इस कुंजी की ज़रूरत पड़ना बताता है कि मान text के रूप में आया होगा।", "把内容右对齐；数字本来就默认靠右，需要用这个键，往往说明那个值是以文本进来的。", "把內容靠右對齊；數字本來就預設靠右，需要用這個鍵，往往說明那個值是以文字進來的。"],
  'sheets-clear-formatting': ["굵기·색·숫자 꼴 같은 서식만 걷어내고 내용은 그대로 둡니다. 값을 지우는 Delete와 하는 일이 정반대입니다.", "Strips the formatting — bold, colour, number format — and leaves the contents alone; it is the opposite of Delete, which removes the value.", "Quita solo el formato (negrita, color, formato numérico) y deja el contenido; es lo contrario de Delete, que borra el valor.", "Remove só a formatação (negrito, cor, formato numérico) e deixa o conteúdo; é o oposto do Delete, que apaga o valor.", "太字・色・数値書式といった書式だけを取り除き、中身はそのまま残します。値を消す Delete とは正反対の働きです。", "Entfernt nur die Formatierung — fett, Farbe, Zahlenformat — und lässt den Inhalt stehen; das Gegenteil von Delete, das den Wert löscht.", "Retire seulement la mise en forme — gras, couleur, format numérique — et laisse le contenu ; l inverse de Delete qui efface la valeur.", "केवल formatting हटाता है — मोटा, रंग, संख्या-रूप — और सामग्री छोड़ देता है; यह Delete का उलटा है, जो मान मिटाता है।", "只清掉格式（加粗、颜色、数字格式），内容留着；这和删值的 Delete 正好相反。", "只清掉格式（粗體、顏色、數字格式），內容留著；這和刪值的 Delete 正好相反。"],
  'sheets-border-outer': ["고른 자리의 바깥 테두리만 그립니다. 안쪽 선까지 넣으려면 다른 번호를 함께 눌러야 합니다.", "Draws only the outer border of the selection; the inner lines need the other numbers in the same family.", "Dibuja solo el borde exterior de la selección; las líneas internas requieren los otros números de la misma familia.", "Desenha apenas a borda externa da seleção; as linhas internas exigem os outros números da mesma família.", "選んだ範囲の外枠だけを引きます。内側の線を入れるには同じ系列の別の番号を押します。", "Zeichnet nur den äußeren Rahmen der Markierung; für die Innenlinien braucht es die anderen Zahlen derselben Reihe.", "Ne trace que la bordure extérieure de la sélection ; les traits intérieurs demandent les autres chiffres de la même série.", "चुने हुए हिस्से की केवल बाहरी border खींचता है; भीतरी रेखाओं के लिए उसी परिवार के दूसरे अंक चाहिए।", "只画所选区域的外框；里面的线要用同一组里的其他数字。", "只畫所選區域的外框；裡面的線要用同一組裡的其他數字。"],
  'sheets-border-remove': ["고른 자리의 테두리를 모두 지웁니다. 표에 남은 선 때문에 인쇄가 지저분할 때 먼저 눌러 볼 키입니다.", "Removes every border from the selection; it is the first key to try when leftover lines make a printout look messy.", "Elimina todos los bordes de la selección; es la primera tecla que probar cuando las líneas sobrantes ensucian la impresión.", "Remove todas as bordas da seleção; é a primeira tecla a tentar quando linhas sobrando deixam a impressão suja.", "選んだ範囲の罫線をすべて消します。残った線で印刷が汚くなったとき、まず押してみるキーです。", "Entfernt alle Rahmen aus der Markierung; die erste Taste, wenn übrig gebliebene Linien den Ausdruck unruhig machen.", "Supprime toutes les bordures de la sélection ; la première touche à essayer quand des traits résiduels salissent l impression.", "चुने हुए हिस्से की सभी border हटा देता है; बची हुई रेखाओं से छपाई गंदी लगे तो पहले यही आज़माएँ।", "清掉所选区域的全部边框；残留的线让打印显得乱时，先按它试试。", "清掉所選區域的全部框線；殘留的線讓列印顯得亂時，先按它試試。"],
  'sheets-format-decimal': ["소수 두 자리와 천 단위 쉼표가 붙은 숫자 꼴로 바꿉니다. 이 여섯 가지 숫자 꼴은 맥에서도 Cmd가 아니라 Ctrl을 씁니다.", "Switches to a number format with two decimals and a thousands separator; all six of these number formats use Ctrl even on a Mac, not Cmd.", "Cambia a un formato numérico con dos decimales y separador de miles; estos seis formatos usan Ctrl incluso en Mac, no Cmd.", "Muda para um formato numérico com duas casas e separador de milhares; todos esses seis formatos usam Ctrl mesmo no Mac, não Cmd.", "小数二桁と桁区切りの付いた数値書式にします。この六つの数値書式は Mac でも Cmd ではなく Ctrl を使います。", "Wechselt zu einem Zahlenformat mit zwei Dezimalstellen und Tausendertrennzeichen; alle sechs dieser Formate nutzen auch auf dem Mac Ctrl, nicht Cmd.", "Passe à un format numérique à deux décimales avec séparateur de milliers ; ces six formats utilisent Ctrl même sur Mac, pas Cmd.", "दो दशमलव और हज़ार के विभाजक वाले संख्या-रूप में बदल देता है; ये छह संख्या-रूप Mac पर भी Cmd नहीं, Ctrl इस्तेमाल करते हैं।", "改成带两位小数和千位分隔符的数字格式；这六种数字格式在 Mac 上也用 Ctrl，不是 Cmd。", "改成帶兩位小數和千位分隔符的數字格式；這六種數字格式在 Mac 上也用 Ctrl，不是 Cmd。"],
  'sheets-format-time': ["시각 꼴로 바꿉니다. 값이 하루를 1로 보는 소수라서, 25시간을 그대로 보려면 시각 꼴이 아닌 기간 꼴이 필요합니다.", "Switches to a time format; the value underneath counts a day as 1, so showing 25 hours needs the duration format rather than this one.", "Cambia a formato de hora; el valor de fondo cuenta un día como 1, así que mostrar 25 horas exige el formato de duración y no este.", "Muda para formato de hora; o valor por baixo conta um dia como 1, então mostrar 25 horas exige o formato de duração, não este.", "時刻の書式にします。裏の値は一日を 1 と数えるので、25 時間をそのまま見せるには時刻ではなく期間の書式が必要です。", "Wechselt zu einem Zeitformat; der Wert darunter zählt einen Tag als 1, für 25 Stunden braucht es daher das Dauerformat.", "Passe à un format d heure ; la valeur sous-jacente compte un jour comme 1, afficher 25 heures demande donc le format durée.", "समय के रूप में बदल देता है; भीतर का मान एक दिन को 1 गिनता है, इसलिए 25 घंटे दिखाने के लिए अवधि वाला रूप चाहिए, यह नहीं।", "改成时间格式；底下的值把一天算作 1，所以要显示 25 小时得用时长格式，而不是这个。", "改成時間格式；底下的值把一天算作 1，所以要顯示 25 小時得用時長格式，而不是這個。"],
  'sheets-format-date': ["날짜 꼴로 바꿉니다. 글자로 들어온 날짜는 모양만 바뀌지 않으니, 그때는 값 자체를 다시 넣어야 합니다.", "Switches to a date format; a date that arrived as text will not change appearance, and then the value itself has to be re-entered.", "Cambia a formato de fecha; una fecha que llegó como texto no cambiará de aspecto y habrá que volver a introducir el valor.", "Muda para formato de data; uma data que veio como texto não muda de aparência, e aí o valor precisa ser digitado de novo.", "日付の書式にします。文字列として入った日付は見え方が変わらないので、その場合は値そのものを入れ直します。", "Wechselt zu einem Datumsformat; ein als Text eingetroffenes Datum ändert sein Aussehen nicht, dann muss der Wert neu eingegeben werden.", "Passe à un format date ; une date arrivée sous forme de texte ne changera pas d aspect, il faut alors ressaisir la valeur.", "तारीख़ के रूप में बदल देता है; text के रूप में आई तारीख़ की शक्ल नहीं बदलेगी, तब मान फिर से डालना पड़ता है।", "改成日期格式；以文本进来的日期不会因此改样子，那时得把值重新输入一遍。", "改成日期格式；以文字進來的日期不會因此改樣子，那時得把值重新輸入一遍。"],
  'sheets-format-currency': ["화폐 꼴로 바꿉니다. 시트의 숫자 꼴 번호는 1부터 6까지 시트가 정한 순서라서, 엑셀의 번호와 짝이 맞지 않습니다.", "Switches to a currency format; the numbers one to six are the order Sheets chose for itself and do not line up with the Excel ones.", "Cambia a formato de moneda; los números del uno al seis son el orden propio de Sheets y no coinciden con los de Excel.", "Muda para formato de moeda; os números de um a seis são a ordem que o Sheets escolheu e não coincidem com os do Excel.", "通貨の書式にします。数値書式の 1 から 6 までは Sheets が独自に決めた並びで、Excel の番号とは一致しません。", "Wechselt zu einem Währungsformat; die Ziffern eins bis sechs sind die eigene Reihenfolge von Sheets und deckt sich nicht mit Excel.", "Passe à un format monétaire ; les chiffres un à six suivent l ordre propre de Sheets et ne correspondent pas à ceux d Excel.", "मुद्रा के रूप में बदल देता है; एक से छह तक के अंक Sheets का अपना क्रम हैं और Excel के अंकों से मेल नहीं खाते।", "改成货币格式；数字 1 到 6 是 Sheets 自己排的顺序，和 Excel 的编号对不上。", "改成貨幣格式；數字 1 到 6 是 Sheets 自己排的順序，和 Excel 的編號對不上。"],
  'sheets-format-percent': ["백분율 꼴로 바꿉니다. 취소선이 Alt+Shift+5라 번호가 같아 보이지만, 이쪽은 Ctrl+Shift+5로 수정 글쇠가 다릅니다.", "Switches to a percent format; strikethrough uses the same digit as Alt+Shift+5, so watch the modifier — this one is Ctrl+Shift+5.", "Cambia a formato de porcentaje; el tachado usa el mismo dígito con Alt+Shift+5, así que fíjate en el modificador: este es Ctrl+Shift+5.", "Muda para formato de porcentagem; o riscado usa o mesmo dígito com Alt+Shift+5, então olhe o modificador: este é Ctrl+Shift+5.", "パーセントの書式にします。取り消し線が Alt+Shift+5 で同じ数字を使うので修飾キーに注意 — こちらは Ctrl+Shift+5 です。", "Wechselt zu einem Prozentformat; der Durchstrich nutzt dieselbe Ziffer mit Alt+Shift+5, achten Sie auf die Modifiziertaste — hier ist es Ctrl+Shift+5.", "Passe à un format pourcentage ; le barré utilise le même chiffre avec Alt+Shift+5, attention au modificateur : ici c est Ctrl+Shift+5.", "प्रतिशत के रूप में बदल देता है; काट की रेखा वही अंक Alt+Shift+5 के साथ लेती है, इसलिए modifier देखें — यह Ctrl+Shift+5 है।", "改成百分比格式；删除线用的是同一个数字加 Alt+Shift+5，所以要看清修饰键，这里是 Ctrl+Shift+5。", "改成百分比格式；刪除線用的是同一個數字加 Alt+Shift+5，所以要看清輔助鍵，這裡是 Ctrl+Shift+5。"],
  'sheets-format-exponent': ["1.2E+05처럼 지수 꼴로 바꿉니다. 아주 크거나 작은 숫자가 칸 너비에 잘려 ###으로 보일 때 쓸 만합니다.", "Switches to a scientific format like 1.2E+05, which helps when a very large or very small number is clipped into hashes by the column width.", "Cambia a formato científico como 1,2E+05, útil cuando un número enorme o minúsculo aparece como almohadillas por el ancho de la columna.", "Muda para formato científico como 1,2E+05, útil quando um número muito grande ou pequeno aparece como cerquilhas pela largura da coluna.", "1.2E+05 のような指数の書式にします。とても大きい・小さい数が列幅に切られて ### になるときに役立ちます。", "Wechselt zu einem wissenschaftlichen Format wie 1,2E+05 — hilfreich, wenn eine sehr große oder kleine Zahl von der Spaltenbreite zu Rauten gestaucht wird.", "Passe à un format scientifique comme 1,2E+05, pratique quand un nombre très grand ou très petit se réduit à des dièses faute de largeur.", "1.2E+05 जैसे घातांक रूप में बदल देता है; जब बहुत बड़ा या बहुत छोटा अंक column की चौड़ाई से कटकर ### दिखे तो यह काम आता है।", "改成 1.2E+05 这样的科学计数格式；数字太大或太小、被列宽挤成一串井号时很有用。", "改成 1.2E+05 這樣的科學記號格式；數字太大或太小、被欄寬擠成一串井號時很有用。"],
  'sheets-next-sheet': ["오른쪽 시트로 넘어갑니다. 엑셀은 Ctrl+PageDown인데 시트는 Alt+Down이라, 여기가 두 앱에서 가장 다른 자리입니다.", "Moves one tab to the right; Excel uses Ctrl+PageDown while Sheets uses Alt+Down, which is where the two apps differ most.", "Pasa a la pestaña de la derecha; Excel usa Ctrl+PageDown y Sheets Alt+Down, la mayor diferencia entre ambas aplicaciones.", "Passa para a aba da direita; o Excel usa Ctrl+PageDown e o Sheets Alt+Down, a maior diferença entre os dois aplicativos.", "右のシートへ移ります。Excel は Ctrl+PageDown なのに Sheets は Alt+Down で、二つのアプリで最も違う箇所です。", "Wechselt einen Tab nach rechts; Excel nutzt Ctrl+PageDown, Sheets dagegen Alt+Down — hier unterscheiden sich beide Programme am stärksten.", "Passe à l onglet de droite ; Excel utilise Ctrl+PageDown alors que Sheets prend Alt+Down, la plus grande différence entre les deux applications.", "दाईं ओर की sheet पर जाता है; Excel में Ctrl+PageDown है और Sheets में Alt+Down, दोनों apps में यही सबसे बड़ा अंतर है।", "切到右边一张工作表；Excel 用 Ctrl+PageDown，而 Sheets 用 Alt+Down，这是两个软件差别最大的地方。", "切到右邊一張工作表；Excel 用 Ctrl+PageDown，而 Sheets 用 Alt+Down，這是兩個軟體差別最大的地方。"],
  'sheets-previous-sheet': ["왼쪽 시트로 넘어갑니다. 맥에서는 Option+Up이고, 시트가 많을 때는 목록을 띄우는 편이 빠릅니다.", "Moves one tab to the left; on a Mac it is Option+Up, and with many tabs the sheet list is quicker.", "Pasa a la pestaña de la izquierda; en Mac es Option+Up, y con muchas pestañas la lista de hojas es más rápida.", "Passa para a aba da esquerda; no Mac é Option+Up, e com muitas abas a lista de planilhas é mais rápida.", "左のシートへ移ります。Mac では Option+Up で、シートが多いときは一覧を出すほうが速いです。", "Wechselt einen Tab nach links; auf dem Mac Option+Up, und bei vielen Tabs ist die Blattliste schneller.", "Passe à l onglet de gauche ; sur Mac c est Option+Up, et avec beaucoup d onglets la liste des feuilles va plus vite.", "बाईं ओर की sheet पर जाता है; Mac पर यह Option+Up है, और कई sheet हों तो सूची खोलना तेज़ पड़ता है।", "切到左边一张工作表；Mac 上是 Option+Up，表很多时不如直接调出工作表清单。", "切到左邊一張工作表；Mac 上是 Option+Up，表很多時不如直接調出工作表清單。"],
  'sheets-sheet-list': ["아래에 늘어선 시트를 목록으로 띄웁니다. 탭이 화면 밖으로 밀려났을 때 유일하게 빠른 길입니다.", "Pops up the tabs at the bottom as a list; when they have scrolled off the screen this is the only quick way in.", "Muestra las pestañas de abajo como lista; cuando se han salido de la pantalla es la única vía rápida.", "Mostra as abas de baixo como uma lista; quando elas saíram da tela, é o único caminho rápido.", "下に並んだシートを一覧で出します。タブが画面の外へ押し出されたときの唯一の速い道です。", "Zeigt die Registerkarten unten als Liste; sind sie aus dem Bild gerutscht, ist dies der einzige schnelle Weg.", "Affiche les onglets du bas sous forme de liste ; quand ils ont défilé hors de l écran, c est la seule voie rapide.", "नीचे लगी sheets को सूची के रूप में दिखा देता है; tab स्क्रीन से बाहर खिसक जाएँ तो यही एकमात्र तेज़ रास्ता है।", "把底部的工作表标签以列表弹出来；标签被挤到屏幕外时，这是唯一快的办法。", "把底部的工作表標籤以清單彈出來；標籤被擠到畫面外時，這是唯一快的辦法。"],
  'sheets-insert-sheet': ["새 시트를 맨 뒤에 만듭니다. 맥 노트북에서는 Fn까지 함께 눌러야 F11이 브라우저를 지나 시트에 닿습니다.", "Adds a new sheet at the end; on a Mac laptop you must hold Fn as well so that F11 gets past the browser and into Sheets.", "Añade una hoja nueva al final; en un portátil Mac hay que pulsar también Fn para que F11 pase del navegador a Sheets.", "Adiciona uma nova planilha no fim; em um notebook Mac é preciso segurar Fn para que F11 passe do navegador e chegue ao Sheets.", "新しいシートを末尾に作ります。Mac のノートでは Fn も押さないと、F11 がブラウザーを越えて Sheets に届きません。", "Fügt am Ende ein neues Blatt hinzu; auf einem Mac-Notebook müssen Sie Fn mithalten, damit F11 am Browser vorbei zu Sheets kommt.", "Ajoute une feuille à la fin ; sur un portable Mac, il faut aussi maintenir Fn pour que F11 franchisse le navigateur et atteigne Sheets.", "अंत में एक नई sheet बना देता है; Mac laptop पर Fn भी दबाना पड़ता है ताकि F11 browser को पार कर Sheets तक पहुँचे।", "在最后面新建一张工作表；Mac 笔记本要同时按住 Fn，F11 才能越过浏览器传到 Sheets。", "在最後面新增一張工作表；Mac 筆電要同時按住 Fn，F11 才能越過瀏覽器傳到 Sheets。"],
  'sheets-show-formulas': ["결과 대신 수식을 그대로 보여 줍니다. 맥에서도 Cmd가 아니라 Ctrl로 눌러야 듣습니다.", "Shows the formulas instead of the results; even on a Mac this one wants Ctrl and not Cmd.", "Muestra las fórmulas en vez de los resultados; incluso en Mac esta pide Ctrl y no Cmd.", "Mostra as fórmulas em vez dos resultados; mesmo no Mac esta pede Ctrl e não Cmd.", "結果ではなく数式をそのまま表示します。Mac でも Cmd ではなく Ctrl で押さないと効きません。", "Zeigt die Formeln statt der Ergebnisse; auch auf dem Mac braucht dieses Kürzel Ctrl und nicht Cmd.", "Affiche les formules au lieu des résultats ; même sur Mac, celui-ci veut Ctrl et non Cmd.", "परिणाम की जगह formula दिखा देता है; Mac पर भी यह Cmd से नहीं, Ctrl से चलता है।", "显示公式而不是结果；即使在 Mac 上，这个也要用 Ctrl 而不是 Cmd。", "顯示公式而不是結果；即使在 Mac 上，這個也要用 Ctrl 而不是 Cmd。"],
  'sheets-open-explore': ["고른 범위를 보고 요약과 차트를 제안하는 칸을 엽니다. 손으로 피벗을 만들기 전에 한 번 열어 볼 만합니다.", "Opens the panel that reads your selection and suggests summaries and charts; worth a look before you build a pivot by hand.", "Abre el panel que lee tu selección y propone resúmenes y gráficos; merece una mirada antes de armar una tabla dinámica a mano.", "Abre o painel que lê a sua seleção e sugere resumos e gráficos; vale olhar antes de montar uma dinâmica na mão.", "選んだ範囲を読んで要約やグラフを提案する画面を開きます。手でピボットを組む前に一度覗く価値があります。", "Öffnet die Leiste, die Ihre Auswahl liest und Zusammenfassungen samt Diagrammen vorschlägt; ein Blick lohnt, bevor Sie eine Pivot-Tabelle bauen.", "Ouvre le volet qui lit votre sélection et propose des synthèses et des graphiques ; à regarder avant de bâtir un tableau croisé à la main.", "आपकी चुनी range पढ़कर सारांश और chart सुझाने वाला panel खोलता है; हाथ से pivot बनाने से पहले एक बार देख लेना ठीक रहता है।", "打开会读取你所选区域、并给出汇总和图表建议的面板；手工做数据透视之前值得先看一眼。", "開啟會讀取你所選區域、並給出彙總和圖表建議的面板；手工做樞紐分析之前值得先看一眼。"],
  'sheets-find-and-replace': ["찾아서 바꾸는 창을 엽니다. 맥의 Cmd+H는 앱을 숨기는 자리라서 시트도 Cmd+Shift+H를 쓰고, 정규식 옵션이 이 창 안에 있습니다.", "Opens find and replace; Cmd+H hides the app on a Mac, so Sheets uses Cmd+Shift+H, and the regular expression option lives in this box.", "Abre buscar y reemplazar; en Mac Cmd+H oculta la aplicación, así que Sheets usa Cmd+Shift+H, y la opción de expresiones regulares está en este cuadro.", "Abre localizar e substituir; no Mac Cmd+H esconde o aplicativo, então o Sheets usa Cmd+Shift+H, e a opção de expressão regular está nesta caixa.", "検索と置換の画面を開きます。Mac の Cmd+H はアプリを隠すため Sheets も Cmd+Shift+H を使い、正規表現の選択肢はこの画面の中にあります。", "Öffnet Suchen und Ersetzen; auf dem Mac blendet Cmd+H die App aus, daher nutzt Sheets Cmd+Shift+H, und die Option für reguläre Ausdrücke steckt in diesem Fenster.", "Ouvre rechercher et remplacer ; sur Mac, Cmd+H masque l application, donc Sheets prend Cmd+Shift+H, et l option d expression régulière est dans cette boîte.", "खोजें और बदलें वाला box खोलता है; Mac पर Cmd+H app छिपाता है इसलिए Sheets Cmd+Shift+H लेता है, और regular expression का विकल्प इसी box में है।", "打开查找和替换；Mac 上 Cmd+H 是隐藏应用，所以 Sheets 用 Cmd+Shift+H，正则表达式的选项就在这个框里。", "開啟尋找和取代；Mac 上 Cmd+H 是隱藏應用程式，所以 Sheets 用 Cmd+Shift+H，正規表示式的選項就在這個框裡。"],
  'sheets-freeze-rows': ["머리글 줄을 화면에 붙여 둡니다. 시트에는 기본 조합이 아예 없어 View 메뉴의 Freeze를 쓰거나, 머리글 왼쪽 위의 굵은 회색 막대를 끌어내려야 합니다.", "Pins the header rows in place; Sheets ships no default combination at all, so you use Freeze in the View menu or drag the thick grey bar above the row numbers.", "Fija las filas de encabezado; Sheets no trae ninguna combinación por defecto, hay que usar Freeze en el menú View o arrastrar la barra gris gruesa junto a los números de fila.", "Fixa as linhas de cabeçalho; o Sheets não traz combinação padrão nenhuma, use Freeze no menu View ou arraste a barra cinza grossa acima dos números das linhas.", "見出し行を画面に固定します。Sheets には既定の組み合わせが一つも無いので、View メニューの Freeze を使うか、行番号の上の太い灰色の棒を引き下げます。", "Heftet die Kopfzeilen fest; Sheets bringt überhaupt keine Standardtastenfolge mit, nutzen Sie Freeze im Menü View oder ziehen Sie den dicken grauen Balken über den Zeilennummern.", "Fige les lignes d en-tête ; Sheets ne fournit aucune combinaison par défaut, il faut Freeze dans le menu View ou tirer la grosse barre grise au-dessus des numéros de ligne.", "header पंक्तियों को स्क्रीन पर टिका देता है; Sheets में कोई डिफ़ॉल्ट combination ही नहीं है, इसलिए View मेनू का Freeze लें या row संख्याओं के ऊपर की मोटी स्लेटी पट्टी खींचें।", "把标题行钉在屏幕上；Sheets 根本没有默认组合，要用 View 菜单里的 Freeze，或者把行号上方那条粗灰条往下拖。", "把標題列釘在畫面上；Sheets 根本沒有預設組合，要用 View 選單裡的 Freeze，或者把列號上方那條粗灰條往下拖。"],
  /* ═════════ windows ═════════ */
  'windows-start-menu': ["시작 메뉴를 열고 닫습니다. 열린 채로 그냥 글자를 치면 그것이 곧 검색이라, 프로그램 이름을 아는 편이 목록을 뒤지는 것보다 빠릅니다.", "Opens and closes the Start menu; typing right after it goes straight into search, so knowing a program name beats hunting through the list.", "Abre y cierra el menú Inicio; escribir justo después va directo a la búsqueda, así que saber el nombre del programa es más rápido que buscarlo en la lista.", "Abre e fecha o menu Iniciar; digitar em seguida vai direto para a busca, então saber o nome do programa é mais rápido que caçar na lista.", "スタートメニューを開閉します。開いたまま文字を打てばそれが検索になるので、一覧を探すよりプログラム名を知っているほうが速いです。", "Öffnet und schließt das Startmenü; tippt man direkt danach, landet man in der Suche — den Programmnamen zu kennen ist schneller als die Liste zu durchstöbern.", "Ouvre et ferme le menu Démarrer ; taper juste après lance la recherche, donc connaître le nom du programme va plus vite que fouiller la liste.", "Start मेनू खोलता और बंद करता है; खुलने के बाद सीधे टाइप करना ही खोज बन जाता है, इसलिए सूची छानने से program का नाम जानना तेज़ है।", "打开或关闭开始菜单；打开后直接打字就是搜索，所以知道程序名比在列表里翻要快。", "開啟或關閉開始選單；開啟後直接打字就是搜尋，所以知道程式名比在清單裡翻要快。"],
  'windows-search': ["검색 창을 바로 엽니다. 파일 이름뿐 아니라 설정 항목과 웹까지 같은 칸에서 찾습니다.", "Opens the search box directly, and the same box looks through settings and the web as well as file names.", "Abre directamente el cuadro de búsqueda, y ese mismo cuadro busca ajustes y la web además de nombres de archivo.", "Abre direto a caixa de busca, e a mesma caixa procura configurações e a web além de nomes de arquivo.", "検索欄をすぐに開きます。同じ欄でファイル名だけでなく設定項目やウェブまで探します。", "Öffnet direkt das Suchfeld, das neben Dateinamen auch Einstellungen und das Web durchsucht.", "Ouvre directement la zone de recherche, qui explore aussi les paramètres et le web, pas seulement les noms de fichiers.", "सीधे खोज-बॉक्स खोलता है, और वही box फ़ाइल नामों के साथ settings और वेब भी खोजता है।", "直接打开搜索框；同一个框除了文件名，也会搜设置项和网页。", "直接開啟搜尋框；同一個框除了檔名，也會搜設定項目和網頁。"],
  'windows-settings': ["설정 앱을 엽니다. 옛 제어판이 아니라 지금의 설정 창이 열리고, 찾는 항목이 없으면 검색 칸에 이름을 치는 편이 빠릅니다.", "Opens the Settings app — the modern window, not the old Control Panel — and its search box is the fastest way to reach a buried option.", "Abre la aplicación Configuración, la ventana moderna y no el Panel de control antiguo, y su cuadro de búsqueda es la vía rápida a una opción escondida.", "Abre o aplicativo Configurações, a janela moderna e não o antigo Painel de Controle, e a busca dele é o caminho mais rápido para uma opção escondida.", "設定アプリを開きます。昔のコントロールパネルではなく今の設定画面が開き、埋もれた項目は検索欄に名前を打つのが速いです。", "Öffnet die App Einstellungen — das moderne Fenster, nicht die alte Systemsteuerung — und ihr Suchfeld führt am schnellsten zu einer versteckten Option.", "Ouvre l application Paramètres — la fenêtre moderne, pas l ancien Panneau de configuration — et sa zone de recherche mène le plus vite à une option enfouie.", "Settings app खोलता है — पुराना Control Panel नहीं, आज की settings window — और उसका खोज-बॉक्स छिपे विकल्प तक सबसे तेज़ रास्ता है।", "打开设置应用；开的是现在的设置窗口，不是旧控制面板，找不到项目时在它的搜索框里打名字最快。", "開啟設定應用程式；開的是現在的設定視窗，不是舊控制台，找不到項目時在它的搜尋框裡打名字最快。"],
  'windows-run-dialog': ["명령 한 줄을 치는 실행 창을 엽니다. cmd·regedit·control처럼 시작 메뉴에서 찾기 번거로운 것들을 이름으로 바로 부릅니다.", "Opens the Run box for a single command; it calls things like cmd, regedit or control by name when digging through Start would be slower.", "Abre el cuadro Ejecutar para una sola orden; llama por su nombre a cosas como cmd, regedit o control cuando buscar en Inicio sería más lento.", "Abre a caixa Executar para um único comando; chama pelo nome coisas como cmd, regedit ou control quando procurar no Iniciar seria mais lento.", "コマンドを一行打つ実行画面を開きます。cmd・regedit・control のように、スタートから探すより名前で呼ぶほうが早いものに向きます。", "Öffnet das Ausführen-Feld für einen einzelnen Befehl; damit ruft man cmd, regedit oder control direkt beim Namen, statt im Startmenü zu suchen.", "Ouvre la boîte Exécuter pour une seule commande ; elle appelle cmd, regedit ou control par leur nom quand fouiller le menu Démarrer serait plus lent.", "एक पंक्ति का command लिखने वाला Run box खोलता है; cmd, regedit या control जैसी चीज़ें Start में ढूँढने से नाम लेकर बुलाना जल्दी होता है।", "打开只输入一行命令的运行框；像 cmd、regedit、control 这些，直接叫名字比在开始菜单里翻更快。", "開啟只輸入一行命令的執行框；像 cmd、regedit、control 這些，直接叫名字比在開始選單裡翻更快。"],
  'windows-quick-link-menu': ["장치 관리자·터미널·디스크 관리처럼 손 볼 때 필요한 것들이 모인 작은 메뉴를 엽니다. 시작 단추를 오른쪽 단추로 누른 것과 같습니다.", "Opens the small menu of repair tools — Device Manager, Terminal, Disk Management — and it is the same thing as right-clicking the Start button.", "Abre el pequeño menú de herramientas de mantenimiento (Administrador de dispositivos, Terminal, Administración de discos); es lo mismo que hacer clic derecho en Inicio.", "Abre o pequeno menu de ferramentas de manutenção (Gerenciador de Dispositivos, Terminal, Gerenciamento de Disco); é o mesmo que clicar com o botão direito no Iniciar.", "デバイスマネージャー・ターミナル・ディスクの管理といった手入れ用の道具が並ぶ小さなメニューを開きます。スタートボタンを右クリックしたのと同じです。", "Öffnet das kleine Menü der Wartungswerkzeuge — Geräte-Manager, Terminal, Datenträgerverwaltung — und entspricht dem Rechtsklick auf die Start-Schaltfläche.", "Ouvre le petit menu des outils de maintenance — Gestionnaire de périphériques, Terminal, Gestion des disques — l équivalent d un clic droit sur le bouton Démarrer.", "मरम्मत के औज़ारों का छोटा मेनू खोलता है — Device Manager, Terminal, Disk Management — और यह Start बटन पर दायाँ क्लिक करने जैसा ही है।", "打开一小串维护工具的菜单：设备管理器、终端、磁盘管理；效果和右键点开始按钮一样。", "開啟一小串維護工具的選單：裝置管理員、終端機、磁碟管理；效果和右鍵點開始按鈕一樣。"],
  'windows-lock': ["화면을 즉시 잠급니다. 프로그램은 그대로 돌아가니 로그아웃과 다르고, 자리를 뜰 때 가장 짧게 누를 수 있는 조합입니다.", "Locks the screen at once; your programs keep running, so it is not a sign-out, and it is the shortest thing to press when you leave the desk.", "Bloquea la pantalla al instante; los programas siguen corriendo, así que no es cerrar sesión, y es lo más corto que pulsar al levantarte.", "Bloqueia a tela na hora; os programas continuam rodando, então não é sair da conta, e é o mais curto para pressionar ao sair da mesa.", "画面をすぐに施錠します。プログラムはそのまま動くのでサインアウトとは違い、席を離れるときに最も短く押せる組み合わせです。", "Sperrt den Bildschirm sofort; die Programme laufen weiter, es ist also keine Abmeldung, und es ist der kürzeste Griff beim Verlassen des Platzes.", "Verrouille l écran immédiatement ; les programmes continuent de tourner, ce n est donc pas une déconnexion, et c est le geste le plus court en quittant son bureau.", "स्क्रीन तुरंत लॉक कर देता है; programs चलते रहते हैं इसलिए यह sign out नहीं है, और मेज़ छोड़ते समय दबाने के लिए सबसे छोटा combination है।", "立刻锁屏；程序照旧运行，所以这不是注销，是离座时能按的最短组合。", "立刻鎖定螢幕；程式照舊執行，所以這不是登出，是離座時能按的最短組合。"],
  'windows-task-manager': ["작업 관리자를 바로 엽니다. Ctrl+Alt+Delete로 보안 화면을 거치는 길보다 한 걸음 짧아, 프로그램이 멈췄을 때 이쪽이 낫습니다.", "Opens Task Manager directly, one step shorter than going through the security screen with Ctrl+Alt+Delete, which is what you want when something is frozen.", "Abre el Administrador de tareas directamente, un paso menos que pasar por la pantalla de seguridad con Ctrl+Alt+Delete, ideal cuando algo se ha colgado.", "Abre o Gerenciador de Tarefas direto, um passo menos que passar pela tela de segurança com Ctrl+Alt+Delete, o que você quer quando algo travou.", "タスクマネージャーを直に開きます。Ctrl+Alt+Delete で保安画面を経る道より一手短く、固まったときはこちらが向きます。", "Öffnet den Task-Manager direkt — einen Schritt kürzer als der Weg über den Sicherheitsbildschirm mit Ctrl+Alt+Delete, und genau richtig, wenn etwas hängt.", "Ouvre le Gestionnaire des tâches directement, une étape de moins qu en passant par l écran de sécurité avec Ctrl+Alt+Delete, idéal quand tout est figé.", "Task Manager सीधे खोल देता है; Ctrl+Alt+Delete से सुरक्षा-स्क्रीन के रास्ते से एक क़दम छोटा है, और कुछ जम जाए तो यही ठीक है।", "直接打开任务管理器；比用 Ctrl+Alt+Delete 绕安全界面少一步，程序卡死时该按这个。", "直接開啟工作管理員；比用 Ctrl+Alt+Delete 繞安全畫面少一步，程式卡死時該按這個。"],
  'windows-security-screen': ["잠금·로그아웃·작업 관리자가 놓인 보안 화면을 부릅니다. 원격 데스크톱이나 가상 머신 안에서는 이 조합을 바깥 컴퓨터가 가로채니, 메뉴에서 따로 보내야 합니다.", "Brings up the security screen with lock, sign out and Task Manager; inside a remote desktop or a virtual machine the host computer swallows this combination, so you send it from a menu instead.", "Muestra la pantalla de seguridad con bloquear, cerrar sesión y Administrador de tareas; dentro de un escritorio remoto o una máquina virtual el equipo anfitrión intercepta la combinación y hay que enviarla desde un menú.", "Mostra a tela de segurança com bloquear, sair e Gerenciador de Tarefas; dentro de uma área de trabalho remota ou máquina virtual o computador hospedeiro engole a combinação, então você a envia por um menu.", "施錠・サインアウト・タスクマネージャーが並ぶ保安画面を呼び出します。リモートデスクトップや仮想マシンの中では手元の母艦がこの組み合わせを奪うため、メニューから送る必要があります。", "Ruft den Sicherheitsbildschirm mit Sperren, Abmelden und Task-Manager auf; in einer Remotesitzung oder virtuellen Maschine fängt der Wirtsrechner die Folge ab, dort schickt man sie über ein Menü.", "Appelle l écran de sécurité avec verrouiller, se déconnecter et Gestionnaire des tâches ; dans un bureau à distance ou une machine virtuelle, l ordinateur hôte intercepte la combinaison, il faut donc l envoyer depuis un menu.", "lock, sign out और Task Manager वाली सुरक्षा-स्क्रीन लाता है; remote desktop या virtual machine के भीतर मेज़बान कंप्यूटर यह combination छीन लेता है, इसलिए इसे मेनू से भेजना पड़ता है।", "调出带锁定、注销和任务管理器的安全界面；在远程桌面或虚拟机里，这个组合会被本机抢走，只能从菜单里发送。", "調出帶鎖定、登出和工作管理員的安全畫面；在遠端桌面或虛擬機裡，這個組合會被本機搶走，只能從選單裡傳送。"],
  'windows-clipboard-history': ["방금까지 복사한 것들을 목록으로 보여 줍니다. 처음 한 번은 켜 달라는 물음에 예라고 답해야 하고, 그 뒤부터 기록이 쌓입니다.", "Shows a list of the things you copied recently; the first time you must say yes to switching it on, and only from then does it keep a history.", "Muestra una lista de lo que copiaste hace poco; la primera vez hay que aceptar activarlo, y solo desde entonces guarda el historial.", "Mostra uma lista do que você copiou recentemente; na primeira vez é preciso aceitar ligar o recurso, e só a partir daí ele guarda o histórico.", "直前まで複写したものを一覧で見せます。最初の一度だけ有効化の確認に承諾する必要があり、それ以降の分から記録が残ります。", "Zeigt eine Liste der zuletzt kopierten Inhalte; beim ersten Mal müssen Sie das Aktivieren bestätigen, und erst danach wird überhaupt mitgeschrieben.", "Affiche la liste de ce que vous venez de copier ; la première fois il faut accepter de l activer, et l historique ne commence qu ensuite.", "आपने हाल में जो copy किया उसकी सूची दिखाता है; पहली बार इसे चालू करने की सहमति देनी पड़ती है, और इतिहास उसके बाद से ही जमा होता है।", "把最近复制过的东西列成清单；第一次要同意开启，之后才开始记录。", "把最近複製過的東西列成清單；第一次要同意開啟，之後才開始記錄。"],
  'windows-emoji-panel': ["이모지와 특수 기호를 고르는 칸을 엽니다. 그림만이 아니라 화살표·수식 기호·특수 문자도 여기서 찾습니다.", "Opens the panel for emoji and symbols; besides the pictures it holds arrows, maths signs and special characters.", "Abre el panel de emoji y símbolos; además de los dibujos incluye flechas, signos matemáticos y caracteres especiales.", "Abre o painel de emoji e símbolos; além dos desenhos, ele traz setas, sinais matemáticos e caracteres especiais.", "絵文字や記号を選ぶ画面を開きます。絵だけでなく矢印・数式記号・特殊文字もここにあります。", "Öffnet die Leiste für Emoji und Symbole; neben den Bildchen enthält sie Pfeile, Rechenzeichen und Sonderzeichen.", "Ouvre le panneau des emoji et des symboles ; outre les images, il contient flèches, signes mathématiques et caractères spéciaux.", "emoji और चिह्न चुनने वाला panel खोलता है; चित्रों के अलावा तीर, गणित के चिह्न और विशेष अक्षर भी यहीं मिलते हैं।", "打开选表情和符号的面板；除了图形，箭头、数学符号和特殊字符也在这里。", "開啟選表情和符號的面板；除了圖形，箭頭、數學符號和特殊字元也在這裡。"],
  'windows-magnifier': ["돋보기를 켜고 화면을 확대합니다. 끌 때는 Win+Esc로 닫아야 하고, 그러지 않으면 확대한 상태가 그대로 남습니다.", "Starts Magnifier and zooms in; close it with Win+Esc, or the zoomed view simply stays where it is.", "Inicia la Lupa y amplía; ciérrala con Win+Esc o la vista ampliada se queda tal cual.", "Inicia a Lupa e amplia; feche com Win+Esc, ou a visão ampliada simplesmente continua.", "拡大鏡を起動して画面を拡大します。閉じるときは Win+Esc で、そうしないと拡大されたままになります。", "Startet die Bildschirmlupe und zoomt hinein; schließen Sie sie mit Win+Esc, sonst bleibt die vergrößerte Ansicht einfach stehen.", "Lance la Loupe et agrandit ; fermez-la avec Win+Esc, sinon la vue agrandie reste en place.", "Magnifier चालू करके स्क्रीन बड़ी कर देता है; बंद करने के लिए Win+Esc दबाएँ, वरना बड़ा किया दृश्य वैसा ही रह जाता है।", "打开放大镜并放大画面；要用 Win+Esc 关掉，不然放大的状态就一直留着。", "開啟放大鏡並放大畫面；要用 Win+Esc 關掉，不然放大的狀態就一直留著。"],
  'windows-project-display': ["두 번째 화면을 어떻게 쓸지 고르는 칸을 엽니다 — 복제·확장·한쪽만. 회의실에서 화면이 안 나올 때 가장 먼저 눌러 볼 조합입니다.", "Opens the panel for choosing how a second screen behaves — duplicate, extend or one screen only — and it is the first thing to press when a meeting room projector shows nothing.", "Abre el panel para elegir cómo se usa la segunda pantalla: duplicar, extender o solo una; es lo primero que pulsar cuando el proyector de la sala no muestra nada.", "Abre o painel para escolher como a segunda tela se comporta: duplicar, estender ou só uma; é a primeira coisa a apertar quando o projetor da sala não mostra nada.", "二台目の画面をどう使うか選ぶ画面を開きます — 複製・拡張・片方だけ。会議室で映らないとき、まず押してみる組み合わせです。", "Öffnet die Leiste zur Wahl des zweiten Bildschirms — duplizieren, erweitern oder nur einer — und ist der erste Griff, wenn der Beamer im Besprechungsraum schwarz bleibt.", "Ouvre le panneau qui choisit le rôle du second écran — dupliquer, étendre ou un seul — et c est le premier réflexe quand le projecteur de la salle n affiche rien.", "दूसरी स्क्रीन कैसे चले यह चुनने वाला panel खोलता है — duplicate, extend या केवल एक — और मीटिंग रूम में कुछ न दिखे तो पहले यही दबाना चाहिए।", "打开选择第二块屏幕怎么用的面板：复制、扩展或只用一块；会议室投影不出画面时，第一个该按的就是它。", "開啟選擇第二塊螢幕怎麼用的面板：複製、延伸或只用一塊；會議室投影不出畫面時，第一個該按的就是它。"],
  'windows-action-center': ["와이파이·소리·밝기가 모인 빠른 설정을 엽니다. 윈도우 10에서는 같은 조합이 알림 센터였기 때문에 두 키가 뒤바뀐 것처럼 느껴집니다.", "Opens quick settings with Wi-Fi, sound and brightness; in Windows 10 this same combination opened the notification centre, which is why the two keys feel swapped.", "Abre la configuración rápida con Wi-Fi, sonido y brillo; en Windows 10 esta misma combinación abría el centro de notificaciones, y de ahí la sensación de teclas cambiadas.", "Abre as configurações rápidas com Wi-Fi, som e brilho; no Windows 10 essa mesma combinação abria a central de notificações, daí a sensação de teclas trocadas.", "Wi-Fi・音量・明るさが並ぶクイック設定を開きます。Windows 10 では同じ組み合わせが通知センターだったため、二つのキーが入れ替わったように感じられます。", "Öffnet die Schnelleinstellungen mit WLAN, Ton und Helligkeit; unter Windows 10 öffnete dieselbe Folge das Info-Center, weshalb die beiden Tasten vertauscht wirken.", "Ouvre les paramètres rapides avec Wi-Fi, son et luminosité ; sous Windows 10 cette même combinaison ouvrait le centre de notifications, d où l impression de touches inversées.", "Wi-Fi, ध्वनि और चमक वाली quick settings खोलता है; Windows 10 में यही combination notification centre खोलता था, इसलिए दोनों कुंजियाँ बदली हुई लगती हैं।", "打开含 Wi-Fi、声音、亮度的快速设置；在 Windows 10 里同一个组合打开的是通知中心，所以这两个键会让人觉得对调了。", "開啟含 Wi-Fi、聲音、亮度的快速設定；在 Windows 10 裡同一個組合開啟的是通知中心，所以這兩個鍵會讓人覺得對調了。"],
  'windows-notifications': ["알림과 달력이 있는 알림 센터를 엽니다. 윈도우 11에서 알림은 이쪽이고, 빠른 설정은 Win+A입니다.", "Opens the notification centre with the calendar; in Windows 11 notifications live here while quick settings sit on Win+A.", "Abre el centro de notificaciones con el calendario; en Windows 11 las notificaciones están aquí y la configuración rápida en Win+A.", "Abre a central de notificações com o calendário; no Windows 11 as notificações ficam aqui e as configurações rápidas em Win+A.", "通知とカレンダーのある通知センターを開きます。Windows 11 では通知はこちらで、クイック設定は Win+A です。", "Öffnet das Benachrichtigungscenter mit dem Kalender; unter Windows 11 stehen Benachrichtigungen hier, die Schnelleinstellungen auf Win+A.", "Ouvre le centre de notifications avec le calendrier ; sous Windows 11, les notifications sont ici et les paramètres rapides sur Win+A.", "सूचनाओं और कैलेंडर वाला notification centre खोलता है; Windows 11 में सूचनाएँ यहाँ हैं और quick settings Win+A पर।", "打开带日历的通知中心；在 Windows 11 里通知在这边，快速设置是 Win+A。", "開啟帶日曆的通知中心；在 Windows 11 裡通知在這邊，快速設定是 Win+A。"],
  'windows-reset-graphics-driver': ["화면 드라이버를 다시 시작합니다. 화면이 검게 굳었을 때 열려 있던 프로그램은 그대로 두고 화면만 되살리는 마지막 수단이라, 삐 소리와 함께 화면이 한 번 깜빡입니다.", "Restarts the graphics driver; when the screen has gone black it revives the display while leaving your open programs alone, and the screen beeps and blinks once.", "Reinicia el controlador de gráficos; con la pantalla en negro devuelve la imagen sin cerrar tus programas, y la pantalla pita y parpadea una vez.", "Reinicia o driver de vídeo; com a tela preta ele traz a imagem de volta sem fechar seus programas, e a tela emite um bipe e pisca uma vez.", "画面のドライバーを再起動します。画面が黒く固まったとき、開いているプログラムはそのままに表示だけを蘇らせる最後の手で、ビープ音とともに一度画面が瞬きます。", "Startet den Grafiktreiber neu; bei schwarzem Bildschirm holt es die Anzeige zurück, ohne offene Programme anzutasten, dabei piept und blinkt der Bildschirm einmal.", "Redémarre le pilote graphique ; quand l écran est resté noir, il ranime l affichage sans toucher aux programmes ouverts, avec un bip et un clignotement.", "graphics driver फिर से चालू करता है; स्क्रीन काली पड़ जाए तो खुले programs को छेड़े बिना केवल display लौटा देता है, और स्क्रीन एक बार बीप के साथ झपकती है।", "重启显卡驱动；屏幕黑掉时，它在不动已打开程序的前提下把画面救回来，屏幕会响一声并闪一下。", "重啟顯示驅動；螢幕黑掉時，它在不動已開啟程式的前提下把畫面救回來，螢幕會響一聲並閃一下。"],
  'windows-run-as-admin': ["시작 검색에서 고른 프로그램을 관리자 권한으로 띄웁니다. 작업 표시줄 아이콘을 Ctrl+Shift와 함께 누르는 것도 같은 일을 합니다.", "Launches the highlighted result from Start search with administrator rights; Ctrl+Shift with a click on a taskbar icon does the same thing.", "Inicia con permisos de administrador el resultado marcado en la búsqueda de Inicio; Ctrl+Shift más un clic en un icono de la barra de tareas hace lo mismo.", "Inicia com direitos de administrador o resultado selecionado na busca do Iniciar; Ctrl+Shift com um clique em um ícone da barra de tarefas faz o mesmo.", "スタート検索で選んだプログラムを管理者権限で起動します。タスクバーのアイコンを Ctrl+Shift を押しながらクリックしても同じです。", "Startet das markierte Suchergebnis aus dem Startmenü mit Administratorrechten; Ctrl+Shift plus Klick auf ein Taskleistensymbol bewirkt dasselbe.", "Lance avec les droits administrateur le résultat sélectionné dans la recherche Démarrer ; Ctrl+Shift plus un clic sur une icône de la barre des tâches fait pareil.", "Start खोज में चुने हुए program को administrator अधिकारों के साथ चलाता है; taskbar के icon पर Ctrl+Shift के साथ क्लिक भी वही करता है।", "把开始搜索里选中的程序以管理员权限启动；按住 Ctrl+Shift 点任务栏图标效果相同。", "把開始搜尋裡選取的程式以管理員權限啟動；按住 Ctrl+Shift 點工作列圖示效果相同。"],
  'windows-show-desktop': ["열린 창을 모두 내리고, 한 번 더 누르면 그대로 되돌립니다. 되돌리기가 없는 Win+M과 달라 잠깐 바탕화면을 볼 때 알맞습니다.", "Drops every open window and puts them all back on a second press; unlike Win+M, which does not come back, it suits a quick look at the desktop.", "Baja todas las ventanas abiertas y las devuelve al pulsar otra vez; a diferencia de Win+M, que no vuelve, sirve para una mirada rápida al escritorio.", "Abaixa todas as janelas abertas e as devolve ao pressionar de novo; diferente do Win+M, que não volta, serve para uma olhada rápida na área de trabalho.", "開いている窓をすべて下げ、もう一度押すと元に戻します。戻らない Win+M と違い、少しだけデスクトップを見たいときに向きます。", "Legt alle offenen Fenster ab und holt sie beim zweiten Druck zurück; anders als Win+M, das nicht zurückkehrt, passt es für einen kurzen Blick auf den Desktop.", "Abaisse toutes les fenêtres ouvertes et les rétablit à la seconde pression ; contrairement à Win+M qui ne revient pas, il convient à un coup d oeil rapide au bureau.", "सारी खुली windows नीचे कर देता है और दोबारा दबाने पर वापस ला देता है; Win+M की तरह यह एकतरफ़ा नहीं है, इसलिए desktop पर एक झलक के लिए ठीक है।", "把所有打开的窗口收下去，再按一次原样恢复；和不会回来的 Win+M 不同，适合快速看一眼桌面。", "把所有開啟的視窗收下去，再按一次原樣恢復；和不會回來的 Win+M 不同，適合快速看一眼桌面。"],
  'windows-peek-desktop': ["누르고 있는 동안만 창들을 투명하게 만들어 바탕화면을 엿봅니다. 손을 떼면 곧 원래대로 돌아옵니다.", "Makes the windows see-through only while you hold the keys, so you can peek at the desktop and have everything back the moment you let go.", "Vuelve transparentes las ventanas solo mientras mantienes las teclas, para asomarte al escritorio y recuperarlo todo al soltar.", "Deixa as janelas transparentes só enquanto você segura as teclas, para espiar a área de trabalho e ter tudo de volta ao soltar.", "押している間だけ窓を透かしてデスクトップを覗きます。指を離せばすぐ元に戻ります。", "Macht die Fenster nur solange durchscheinend, wie Sie die Tasten halten — ein Blick auf den Desktop, und beim Loslassen ist alles zurück.", "Rend les fenêtres transparentes tant que vous maintenez les touches, le temps de jeter un oeil au bureau ; tout revient dès que vous lâchez.", "जब तक कुंजियाँ दबाए रखें तब तक windows पारदर्शी कर देता है, ताकि desktop झाँक सकें और छोड़ते ही सब वापस आ जाए।", "只在按住的时候把窗口变透明，让你瞄一眼桌面，一松手就全恢复。", "只在按住的時候把視窗變透明，讓你瞄一眼桌面，一放手就全恢復。"],
  'windows-task-view': ["열린 창과 가상 데스크톱을 한 화면에 펼칩니다. Alt+Tab처럼 손을 떼면 사라지지 않고 열린 채 남아 있어 창을 끌어 옮길 수 있습니다.", "Spreads the open windows and virtual desktops on one screen; unlike Alt+Tab it stays open after you let go, so you can drag windows between desktops.", "Despliega las ventanas abiertas y los escritorios virtuales en una pantalla; a diferencia de Alt+Tab permanece abierto al soltar, así puedes arrastrar ventanas entre escritorios.", "Espalha as janelas abertas e as áreas de trabalho virtuais em uma tela; diferente do Alt+Tab, fica aberto após soltar, então você arrasta janelas entre elas.", "開いている窓と仮想デスクトップを一画面に広げます。Alt+Tab のように指を離すと消えるのではなく開いたまま残るので、窓を掴んで移せます。", "Breitet offene Fenster und virtuelle Desktops auf einem Bild aus; anders als Alt+Tab bleibt es nach dem Loslassen offen, sodass Sie Fenster hinüberziehen können.", "Étale les fenêtres ouvertes et les bureaux virtuels sur un écran ; contrairement à Alt+Tab, il reste ouvert après le relâchement, ce qui permet de faire glisser les fenêtres.", "खुली windows और virtual desktops एक ही स्क्रीन पर फैला देता है; Alt+Tab की तरह छोड़ने पर गायब नहीं होता, खुला रहता है, इसलिए windows खींचकर ले जा सकते हैं।", "把打开的窗口和虚拟桌面摊在一个界面上；和 Alt+Tab 不同，松手后它仍然开着，可以把窗口拖到别的桌面。", "把開啟的視窗和虛擬桌面攤在一個畫面上；和 Alt+Tab 不同，放手後它仍然開著，可以把視窗拖到別的桌面。"],
  'windows-new-virtual-desktop': ["빈 가상 데스크톱을 하나 더 만들고 그리로 옮겨 갑니다. 창을 닫지 않고 일감을 갈라 두는 데 씁니다.", "Creates one more empty virtual desktop and moves you onto it, which is how you split two jobs apart without closing any windows.", "Crea otro escritorio virtual vacío y te lleva a él, la forma de separar dos tareas sin cerrar ninguna ventana.", "Cria mais uma área de trabalho virtual vazia e leva você para ela, o jeito de separar dois trabalhos sem fechar janelas.", "空の仮想デスクトップをもう一つ作り、そこへ移ります。窓を閉じずに仕事を分けておくのに使います。", "Erstellt einen weiteren leeren virtuellen Desktop und wechselt dorthin — so trennt man zwei Aufgaben, ohne ein Fenster zu schließen.", "Crée un bureau virtuel vide de plus et vous y emmène, la façon de séparer deux tâches sans fermer aucune fenêtre.", "एक और ख़ाली virtual desktop बनाकर आपको उस पर ले जाता है; बिना कोई window बंद किए दो काम अलग रखने का यही तरीक़ा है।", "再建一个空的虚拟桌面并把你带过去；不关任何窗口就把两摊活分开，靠的就是它。", "再建一個空的虛擬桌面並把你帶過去；不關任何視窗就把兩攤活分開，靠的就是它。"],
  'windows-switch-virtual-desktop': ["오른쪽 가상 데스크톱으로 넘어갑니다. Left를 누르면 반대 방향이고, 끝에 이르면 더 넘어가지 않습니다.", "Moves to the virtual desktop on the right; Left goes the other way, and it stops rather than wrapping around at the end.", "Pasa al escritorio virtual de la derecha; Left va en sentido contrario y al llegar al final se detiene en vez de dar la vuelta.", "Vai para a área de trabalho virtual da direita; Left segue no sentido oposto e, no fim, ele para em vez de dar a volta.", "右の仮想デスクトップへ移ります。Left は逆方向で、端に来ると巡回せずそこで止まります。", "Wechselt zum virtuellen Desktop rechts; Left geht in die andere Richtung, und am Ende hält es an statt umzulaufen.", "Passe au bureau virtuel de droite ; Left va dans l autre sens, et au bout il s arrête au lieu de boucler.", "दाईं ओर के virtual desktop पर चला जाता है; Left उलटी दिशा में जाता है, और अंत में यह घूमकर शुरू में नहीं आता, रुक जाता है।", "切到右边的虚拟桌面；按 Left 是反方向，到最后一个就停住，不会绕回第一个。", "切到右邊的虛擬桌面；按 Left 是反方向，到最後一個就停住，不會繞回第一個。"],
  'windows-close-virtual-desktop': ["지금 있는 가상 데스크톱을 닫습니다. 그 안에 있던 창들은 함께 닫히지 않고 옆 데스크톱으로 옮겨 갑니다.", "Closes the virtual desktop you are on; the windows that were there are not closed with it but move over to the next desktop.", "Cierra el escritorio virtual en el que estás; las ventanas que había no se cierran, se trasladan al escritorio vecino.", "Fecha a área de trabalho virtual em que você está; as janelas que estavam lá não fecham, elas passam para a vizinha.", "今いる仮想デスクトップを閉じます。中にあった窓は一緒に閉じるのではなく、隣のデスクトップへ移されます。", "Schließt den virtuellen Desktop, auf dem Sie sind; die dortigen Fenster werden nicht mitgeschlossen, sondern auf den nächsten Desktop verschoben.", "Ferme le bureau virtuel où vous êtes ; les fenêtres qui s y trouvaient ne se ferment pas, elles passent sur le bureau voisin.", "आप जिस virtual desktop पर हैं उसे बंद कर देता है; उसमें रखी windows बंद नहीं होतीं, पड़ोसी desktop पर चली जाती हैं।", "关掉你当前所在的虚拟桌面；里面的窗口不会跟着关，而是挪到旁边那个桌面。", "關掉你目前所在的虛擬桌面；裡面的視窗不會跟著關，而是挪到旁邊那個桌面。"],
  'windows-snap-left': ["지금 창을 화면 왼쪽 절반에 붙입니다. 붙인 뒤에는 반대쪽 후보 창이 뜨므로 화살표로 골라 두 창을 나란히 놓을 수 있습니다.", "Snaps the window to the left half of the screen; Windows then offers candidates for the other half, which you can pick with the arrows to set two windows side by side.", "Ajusta la ventana a la mitad izquierda; después Windows ofrece candidatas para la otra mitad, que eliges con las flechas para dejar dos ventanas lado a lado.", "Encaixa a janela na metade esquerda; depois o Windows oferece candidatas para a outra metade, que você escolhe com as setas para deixar duas janelas lado a lado.", "今の窓を画面の左半分に寄せます。寄せた後に反対側の候補が出るので、矢印で選べば二つの窓を並べられます。", "Dockt das Fenster an die linke Bildhälfte; danach schlägt Windows Kandidaten für die andere Hälfte vor, die Sie mit den Pfeilen wählen, um zwei Fenster nebeneinander zu stellen.", "Ancre la fenêtre sur la moitié gauche de l écran ; Windows propose ensuite des candidates pour l autre moitié, à choisir aux flèches pour poser deux fenêtres côte à côte.", "मौजूदा window को स्क्रीन के बाएँ आधे हिस्से में लगा देता है; इसके बाद Windows दूसरी आधी के लिए उम्मीदवार दिखाता है, जिन्हें तीरों से चुनकर दो windows साथ रख सकते हैं।", "把当前窗口贴到屏幕左半边；贴好后 Windows 会给出右半边的候选窗口，用方向键选一个就并排放好了。", "把目前視窗貼到畫面左半邊；貼好後 Windows 會給出右半邊的候選視窗，用方向鍵選一個就並排放好了。"],
  'windows-snap-right': ["지금 창을 화면 오른쪽 절반에 붙입니다. 이미 붙어 있는 창에 또 누르면 다음 화면으로 넘어가니 두 번 누르는 것을 조심해야 합니다.", "Snaps the window to the right half of the screen; pressing it again on an already snapped window pushes it onto the next monitor, so mind the second press.", "Ajusta la ventana a la mitad derecha; volver a pulsar sobre una ventana ya ajustada la empuja al monitor siguiente, así que cuidado con la segunda pulsación.", "Encaixa a janela na metade direita; apertar de novo em uma janela já encaixada a empurra para o monitor seguinte, então cuidado com a segunda vez.", "今の窓を画面の右半分に寄せます。既に寄っている窓でもう一度押すと次の画面へ送られるので、二度押しに注意します。", "Dockt das Fenster an die rechte Bildhälfte; ein weiterer Druck auf ein bereits gedocktes Fenster schiebt es auf den nächsten Monitor — Vorsicht beim zweiten Mal.", "Ancre la fenêtre sur la moitié droite ; une nouvelle pression sur une fenêtre déjà ancrée l envoie sur l écran suivant, attention au second appui.", "मौजूदा window को स्क्रीन के दाएँ आधे में लगा देता है; पहले से लगी window पर दोबारा दबाने से वह अगले monitor पर चली जाती है, इसलिए दूसरी बार सोच लें।", "把当前窗口贴到屏幕右半边；对已经贴好的窗口再按一次，它会被推到下一块显示器，第二下要小心。", "把目前視窗貼到畫面右半邊；對已經貼好的視窗再按一次，它會被推到下一塊顯示器，第二下要小心。"],
  'windows-maximize': ["창을 화면 가득 키웁니다. 반쪽에 붙여 둔 창에 누르면 그 반쪽의 위쪽 사분면으로 가는 것이 아니라 화면 전체로 커집니다.", "Blows the window up to fill the screen; on a window already snapped to a half it goes full screen rather than shrinking into a quarter.", "Amplía la ventana a pantalla completa; en una ventana ya ajustada a una mitad pasa a ocupar todo, no un cuarto.", "Amplia a janela para tela cheia; em uma janela já encaixada em metade, ela vai para tela inteira, não para um quarto.", "窓を画面いっぱいに広げます。半分に寄せてある窓で押しても四分の一にはならず、画面全体に広がります。", "Vergrößert das Fenster auf Vollbild; bei einem bereits halb gedockten Fenster wird es ganz groß und nicht auf ein Viertel gestaucht.", "Agrandit la fenêtre à tout l écran ; sur une fenêtre déjà ancrée sur une moitié, elle passe en plein écran et non en quart.", "window को पूरी स्क्रीन पर बड़ा कर देता है; आधे में लगी window पर दबाने से यह चौथाई नहीं, पूरी स्क्रीन हो जाती है।", "把窗口放大到占满屏幕；对已经贴在半边的窗口，它是变成全屏，而不是缩成四分之一。", "把視窗放大到佔滿螢幕；對已經貼在半邊的視窗，它是變成全螢幕，而不是縮成四分之一。"],
  'windows-minimize': ["창을 작업 표시줄로 내립니다. 최대화된 창에서는 첫 번째 누름이 먼저 원래 크기로 되돌리고, 그다음 누름에서 내려갑니다.", "Sends the window down to the taskbar; on a maximised window the first press only restores its old size and the next one minimises it.", "Manda la ventana a la barra de tareas; en una ventana maximizada la primera pulsación solo la devuelve a su tamaño y la segunda la minimiza.", "Manda a janela para a barra de tarefas; em uma janela maximizada a primeira vez só devolve o tamanho antigo e a segunda minimiza.", "窓をタスクバーへ下げます。最大化された窓では一度目で元の大きさに戻り、二度目で下がります。", "Schickt das Fenster in die Taskleiste; bei einem maximierten Fenster stellt der erste Druck erst die alte Größe wieder her, der zweite minimiert.", "Envoie la fenêtre dans la barre des tâches ; sur une fenêtre maximisée, la première pression rétablit d abord sa taille et la seconde la minimise.", "window को taskbar में नीचे भेज देता है; बड़ी की गई window पर पहली बार वह पुराने आकार में लौटती है और दूसरी बार छोटी होती है।", "把窗口收进任务栏；对最大化的窗口，第一下只是还原原来大小，第二下才最小化。", "把視窗收進工作列；對最大化的視窗，第一下只是還原原來大小，第二下才最小化。"],
  'windows-snap-layouts': ["창을 어떤 격자로 놓을지 고르는 판을 엽니다. 윈도우 11에서 들어온 기능이라 옛 판에는 없습니다.", "Opens the grid of layouts for placing the window; it arrived with Windows 11 and is not on older versions.", "Abre la rejilla de diseños para colocar la ventana; llegó con Windows 11 y no existe en versiones anteriores.", "Abre a grade de layouts para posicionar a janela; chegou com o Windows 11 e não existe em versões antigas.", "窓をどの格子に置くかを選ぶ盤を開きます。Windows 11 で入った機能なので、古い版にはありません。", "Öffnet das Raster der Anordnungen für das Fenster; es kam mit Windows 11 und fehlt in älteren Versionen.", "Ouvre la grille des dispositions pour placer la fenêtre ; arrivée avec Windows 11, elle n existe pas sur les versions antérieures.", "window को किस जाली में रखना है यह चुनने वाला पट खोलता है; यह Windows 11 के साथ आया है, पुराने संस्करणों में नहीं है।", "打开选择窗口摆放网格的面板；这是 Windows 11 才有的功能，旧版本上没有。", "開啟選擇視窗擺放格線的面板；這是 Windows 11 才有的功能，舊版本上沒有。"],
  'windows-move-to-next-monitor': ["지금 창을 오른쪽 화면으로 옮깁니다. 크기는 그대로 두고 자리만 바뀌며, Left를 누르면 왼쪽 화면으로 돌아옵니다.", "Moves the window to the monitor on the right, keeping its size and changing only where it sits; Left brings it back to the screen on the left.", "Mueve la ventana al monitor de la derecha, conservando su tamaño y cambiando solo su sitio; Left la devuelve a la pantalla izquierda.", "Move a janela para o monitor da direita, mantendo o tamanho e mudando só o lugar; Left a traz de volta para a tela da esquerda.", "今の窓を右の画面へ移します。大きさはそのままで位置だけが変わり、Left で左の画面へ戻ります。", "Verschiebt das Fenster auf den rechten Monitor, behält die Größe und ändert nur den Platz; Left holt es zum linken Bildschirm zurück.", "Déplace la fenêtre vers l écran de droite en gardant sa taille et en changeant seulement sa place ; Left la ramène à gauche.", "मौजूदा window को दाईं स्क्रीन पर ले जाता है, आकार वही रहता है और केवल जगह बदलती है; Left से यह बाईं स्क्रीन पर लौट आती है।", "把当前窗口移到右边那块显示器；大小不变，只换位置，按 Left 就回到左边的屏幕。", "把目前視窗移到右邊那塊顯示器；大小不變，只換位置，按 Left 就回到左邊的螢幕。"],
  'windows-switch-window': ["열린 창 사이를 오갑니다. Alt를 계속 누른 채 Tab을 두드리면 고를 수 있고, Ctrl+Alt+Tab을 쓰면 손을 떼도 목록이 남습니다.", "Steps between the open windows; hold Alt and tap Tab to choose, and Ctrl+Alt+Tab leaves the picker on screen after you let go.", "Recorre las ventanas abiertas; mantén Alt y toca Tab para elegir, y Ctrl+Alt+Tab deja el selector en pantalla al soltar.", "Percorre as janelas abertas; segure Alt e toque Tab para escolher, e Ctrl+Alt+Tab deixa o seletor na tela depois de soltar.", "開いている窓を渡り歩きます。Alt を押したまま Tab を叩けば選べ、Ctrl+Alt+Tab なら指を離しても一覧が残ります。", "Wandert zwischen den offenen Fenstern; halten Sie Alt und tippen Sie Tab zum Auswählen, und Ctrl+Alt+Tab lässt die Auswahl nach dem Loslassen stehen.", "Passe d une fenêtre ouverte à l autre ; gardez Alt enfoncé et tapotez Tab pour choisir, et Ctrl+Alt+Tab laisse le sélecteur affiché après le relâchement.", "खुली windows के बीच घूमता है; Alt दबाए रखकर Tab थपथपाएँ और चुनें, और Ctrl+Alt+Tab से छोड़ने के बाद भी सूची टिकी रहती है।", "在打开的窗口之间切换；按住 Alt 连点 Tab 来挑，用 Ctrl+Alt+Tab 则松手后列表还留在屏幕上。", "在開啟的視窗之間切換；按住 Alt 連點 Tab 來挑，用 Ctrl+Alt+Tab 則放手後清單還留在畫面上。"],
  'windows-close-window': ["지금 창을 닫습니다. 바탕화면을 고른 상태에서 누르면 창이 아니라 컴퓨터를 끄겠느냐는 물음이 뜨는 것을 조심해야 합니다.", "Closes the active window; with the desktop itself focused there is no window to close, so it opens the shut-down box instead.", "Cierra la ventana activa; si el foco está en el escritorio no hay ventana que cerrar y aparece el cuadro de apagado.", "Fecha a janela ativa; se o foco estiver na área de trabalho não há janela para fechar e aparece a caixa de desligar.", "今の窓を閉じます。デスクトップを選んだ状態で押すと閉じる窓が無いため、代わりに電源を切るか尋ねる画面が出ます。", "Schließt das aktive Fenster; liegt der Fokus auf dem Desktop, gibt es kein Fenster, und stattdessen erscheint der Dialog zum Herunterfahren.", "Ferme la fenêtre active ; si le focus est sur le bureau, il n y a pas de fenêtre à fermer et la boîte d arrêt apparaît.", "मौजूदा window बंद कर देता है; ध्यान desktop पर हो तो बंद करने के लिए कोई window नहीं होती और बदले में शटडाउन का box खुल जाता है।", "关掉当前窗口；如果焦点在桌面上，没有窗口可关，弹出来的就是关机对话框。", "關掉目前視窗；如果焦點在桌面上，沒有視窗可關，跳出來的就是關機對話框。"],
  'windows-file-explorer': ["파일 탐색기를 새 창으로 엽니다. 이미 열려 있어도 새 창이 하나 더 뜨므로, 두 폴더를 나란히 볼 때 이 조합을 씁니다.", "Opens File Explorer in a new window; it opens another one even if Explorer is already running, which is how you get two folders side by side.", "Abre el Explorador de archivos en una ventana nueva; abre otra aunque ya esté abierto, y así consigues dos carpetas lado a lado.", "Abre o Explorador de Arquivos em uma nova janela; abre outra mesmo se ele já estiver aberto, e é assim que você põe duas pastas lado a lado.", "エクスプローラーを新しい窓で開きます。既に開いていてももう一つ増えるので、二つのフォルダーを並べて見るときに使います。", "Öffnet den Datei-Explorer in einem neuen Fenster; auch wenn er schon läuft, kommt ein weiteres dazu — so stellt man zwei Ordner nebeneinander.", "Ouvre l Explorateur de fichiers dans une nouvelle fenêtre ; il en ouvre une autre même s il tourne déjà, d où deux dossiers côte à côte.", "File Explorer को नई window में खोलता है; पहले से खुला हो तो भी एक और खुल जाती है, इसी तरह दो folder साथ-साथ देखे जाते हैं।", "在新窗口里打开文件资源管理器；即使已经开着也会再开一个，想并排看两个文件夹就用它。", "在新視窗裡開啟檔案總管；即使已經開著也會再開一個，想並排看兩個資料夾就用它。"],
  'windows-new-folder': ["지금 폴더 안에 새 폴더를 만듭니다. 만든 직후 이름이 고쳐 쓸 수 있는 상태이니 바로 이름을 치면 됩니다.", "Creates a new folder in the current one; the name is already selected for editing, so you can just type it.", "Crea una carpeta nueva en la actual; el nombre queda seleccionado para editar, así que basta escribirlo.", "Cria uma pasta nova dentro da atual; o nome já fica selecionado para edição, então basta digitar.", "今のフォルダーの中に新しいフォルダーを作ります。作った直後は名前が編集できる状態なので、そのまま打てます。", "Erstellt im aktuellen Ordner einen neuen; der Name ist schon zum Bearbeiten markiert, Sie können ihn einfach tippen.", "Crée un nouveau dossier dans le dossier courant ; le nom est déjà sélectionné pour l édition, il suffit de taper.", "मौजूदा folder के भीतर नया folder बनाता है; बनते ही नाम बदलने के लिए चुना हुआ होता है, इसलिए सीधे टाइप करें।", "在当前文件夹里新建一个文件夹；建好后名字已处于可编辑状态，直接打字就行。", "在目前資料夾裡新增一個資料夾；建好後名字已處於可編輯狀態，直接打字就行。"],
  'windows-rename': ["고른 파일의 이름을 고칩니다. 이름을 치고 Tab을 누르면 다음 파일의 이름으로 넘어가, 여러 개를 잇달아 바꿀 수 있습니다.", "Renames the selected file; after typing the name, Tab jumps to the next file so you can rename several in a row.", "Renombra el archivo seleccionado; tras escribir el nombre, Tab salta al siguiente archivo para renombrar varios seguidos.", "Renomeia o arquivo selecionado; depois de digitar o nome, Tab pula para o próximo arquivo e você renomeia vários em sequência.", "選んだファイルの名前を変えます。名前を打って Tab を押すと次のファイルの名前へ移り、続けて何個も変えられます。", "Benennt die markierte Datei um; nach dem Tippen springt Tab zur nächsten Datei, sodass Sie mehrere hintereinander umbenennen.", "Renomme le fichier sélectionné ; après avoir tapé le nom, Tab passe au fichier suivant pour en renommer plusieurs d affilée.", "चुनी हुई फ़ाइल का नाम बदलता है; नाम लिखकर Tab दबाएँ तो अगली फ़ाइल के नाम पर पहुँच जाते हैं और कई एक साथ बदल सकते हैं।", "给选中的文件改名；输完名字按 Tab 会跳到下一个文件的名字，可以连着改好几个。", "給選取的檔案改名；輸完名字按 Tab 會跳到下一個檔案的名字，可以連著改好幾個。"],
  'windows-delete-permanently': ["휴지통을 건너뛰고 곧바로 지웁니다. 휴지통에 아무것도 들어가지 않으니 되돌릴 것도 없고, 큰 파일을 지울 때 확인 창이 한 번 뜹니다.", "Deletes straight away, skipping the Recycle Bin — nothing lands in the bin, so there is nothing to restore, and you get one confirmation first.", "Borra directamente, saltándose la Papelera: nada llega a ella, así que no hay nada que restaurar, y primero aparece una confirmación.", "Apaga direto, pulando a Lixeira: nada cai nela, então não há o que restaurar, e antes aparece uma confirmação.", "ごみ箱を通さずその場で消します。ごみ箱に何も入らないので戻すものも無く、先に確認の画面が一度出ます。", "Löscht sofort und überspringt den Papierkorb — dort landet nichts, also gibt es nichts wiederherzustellen, vorher kommt eine Rückfrage.", "Supprime immédiatement en contournant la Corbeille : rien n y arrive, donc rien à restaurer, avec une confirmation au préalable.", "Recycle Bin को छोड़कर सीधे मिटा देता है — bin में कुछ नहीं जाता, इसलिए लौटाने को भी कुछ नहीं होता, और पहले एक पुष्टि दिखती है।", "跳过回收站直接删除；回收站里什么都不会留，所以也没有可还原的，删之前会先确认一次。", "跳過回收筒直接刪除；回收筒裡什麼都不會留，所以也沒有可還原的，刪之前會先確認一次。"],
  'windows-properties': ["고른 것의 속성 창을 엽니다. 파일이면 크기와 만든 날짜, 드라이브면 남은 용량을 여기서 봅니다.", "Opens the properties window of what you selected — size and dates for a file, free space for a drive.", "Abre la ventana de propiedades de lo seleccionado: tamaño y fechas para un archivo, espacio libre para una unidad.", "Abre a janela de propriedades do que está selecionado: tamanho e datas para um arquivo, espaço livre para um disco.", "選んだものの属性画面を開きます。ファイルなら大きさと日付、ドライブなら空き容量がここで見えます。", "Öffnet das Eigenschaftenfenster des Ausgewählten — Größe und Datum bei einer Datei, freier Platz bei einem Laufwerk.", "Ouvre la fenêtre des propriétés de l élément choisi : taille et dates pour un fichier, espace libre pour un disque.", "चुनी हुई चीज़ की properties window खोलता है — फ़ाइल के लिए आकार और तारीख़, drive के लिए बची जगह।", "打开所选对象的属性窗口；文件看大小和日期，驱动器看剩余空间。", "開啟所選對象的屬性視窗；檔案看大小和日期，磁碟機看剩餘空間。"],
  'windows-parent-folder': ["한 단계 위 폴더로 올라갑니다. 방금 있던 폴더로 돌아가는 Alt+Left와 다른 일이라, 갈래길에서 헷갈리기 쉽습니다.", "Goes up one level in the folder path; Alt+Left instead returns to the folder you were in before, which is not the same move.", "Sube un nivel en la ruta de carpetas; Alt+Left en cambio vuelve a la carpeta anterior, que no es lo mismo.", "Sobe um nível no caminho de pastas; Alt+Left, por outro lado, volta para a pasta anterior, o que não é a mesma coisa.", "一つ上のフォルダーへ上がります。直前のフォルダーへ戻る Alt+Left とは別の動きなので、分かれ道で混同しやすいです。", "Geht eine Ebene im Ordnerpfad nach oben; Alt+Left kehrt dagegen zum vorher besuchten Ordner zurück, was nicht dasselbe ist.", "Remonte d un niveau dans le chemin ; Alt+Left revient au contraire au dossier précédemment visité, ce n est pas le même geste.", "folder path में एक स्तर ऊपर जाता है; Alt+Left इसके बदले पिछले folder पर लौटता है, जो अलग बात है।", "在文件夹路径里往上一级；而 Alt+Left 是回到刚才那个文件夹，两者不是一回事。", "在資料夾路徑裡往上一層；而 Alt+Left 是回到剛才那個資料夾，兩者不是一回事。"],
  'windows-snip': ["화면의 일부를 끌어서 잘라 냅니다. 잘라 낸 그림은 클립보드로 들어가고, 알림을 누르면 그때 편집해 저장할 수 있습니다.", "Lets you drag out a piece of the screen; the cut goes to the clipboard, and clicking the notification opens it for editing and saving.", "Permite arrastrar un trozo de la pantalla; el recorte va al portapapeles y, al pulsar la notificación, se abre para editar y guardar.", "Permite arrastar um pedaço da tela; o recorte vai para a área de transferência e, ao clicar na notificação, abre para editar e salvar.", "画面の一部をドラッグで切り取ります。切り取った絵はクリップボードに入り、通知を押せばそこで編集して保存できます。", "Lässt Sie einen Bildschirmausschnitt aufziehen; der Schnitt landet in der Zwischenablage, und ein Klick auf die Benachrichtigung öffnet ihn zum Bearbeiten und Speichern.", "Permet de délimiter un morceau de l écran ; la capture va dans le presse-papiers, et cliquer la notification l ouvre pour la retoucher et l enregistrer.", "स्क्रीन का एक हिस्सा खींचकर काटने देता है; कटा चित्र clipboard में जाता है, और सूचना पर क्लिक करने से वह संपादित करने और सहेजने के लिए खुल जाता है।", "让你拖出屏幕的一小块；截下来的图进剪贴板，点通知就能打开编辑再保存。", "讓你拖出畫面的一小塊；截下來的圖進剪貼簿，點通知就能開啟編輯再儲存。"],
  'windows-print-screen': ["화면 전체를 클립보드로 복사합니다. 윈도우 11에서는 이 글쇠가 기본으로 캡처 도구를 열도록 바뀌었으니, 옛 방식이 필요하면 설정에서 되돌려야 합니다.", "Copies the whole screen to the clipboard; in Windows 11 this key now opens the Snipping Tool by default, so you change the setting back if you want the old behaviour.", "Copia toda la pantalla al portapapeles; en Windows 11 esta tecla abre la Herramienta de recortes por defecto, así que hay que cambiar el ajuste para recuperar el comportamiento antiguo.", "Copia a tela inteira para a área de transferência; no Windows 11 essa tecla passou a abrir a Ferramenta de Captura por padrão, então mude a configuração se quiser o antigo comportamento.", "画面全体をクリップボードに複写します。Windows 11 ではこのキーが既定で切り取り領域ツールを開くようになったので、昔の挙動が要るなら設定で戻します。", "Kopiert den ganzen Bildschirm in die Zwischenablage; unter Windows 11 öffnet diese Taste standardmäßig das Snipping Tool — für das alte Verhalten stellen Sie es in den Einstellungen zurück.", "Copie tout l écran dans le presse-papiers ; sous Windows 11, cette touche ouvre désormais l Outil Capture par défaut, à rétablir dans les paramètres si besoin.", "पूरी स्क्रीन clipboard में copy कर देता है; Windows 11 में यह कुंजी डिफ़ॉल्ट रूप से Snipping Tool खोलती है, इसलिए पुराना व्यवहार चाहिए तो setting बदलनी पड़ती है।", "把整个屏幕复制到剪贴板；在 Windows 11 里这个键默认改成打开截图工具，想要旧行为得去设置里改回来。", "把整個畫面複製到剪貼簿；在 Windows 11 裡這個鍵預設改成開啟剪取工具，想要舊行為得去設定裡改回來。"],
  'windows-screenshot-to-file': ["화면 전체를 그림 파일로 저장합니다. 사진 폴더 안의 Screenshots에 PNG로 쌓이고, 저장되는 순간 화면이 한 번 어두워집니다.", "Saves the whole screen as a file; the PNGs pile up in the Screenshots folder inside Pictures, and the screen dims once as it saves.", "Guarda toda la pantalla como archivo; los PNG se acumulan en la carpeta Screenshots dentro de Imágenes, y la pantalla se atenúa al guardar.", "Salva a tela inteira como arquivo; os PNG vão se juntando na pasta Screenshots dentro de Imagens, e a tela escurece uma vez ao salvar.", "画面全体を画像ファイルとして保存します。ピクチャの中の Screenshots に PNG が溜まり、保存の瞬間に画面が一度暗くなります。", "Speichert den ganzen Bildschirm als Datei; die PNGs sammeln sich im Ordner Screenshots unter Bilder, und der Bildschirm dunkelt beim Speichern einmal ab.", "Enregistre tout l écran dans un fichier ; les PNG s empilent dans le dossier Screenshots sous Images, et l écran s assombrit une fois à l enregistrement.", "पूरी स्क्रीन को फ़ाइल के रूप में सहेजता है; PNG चित्र Pictures के भीतर Screenshots folder में जमा होते हैं, और सहेजते समय स्क्रीन एक बार मंद पड़ती है।", "把整个屏幕存成图片文件；PNG 会堆在图片文件夹下的 Screenshots 里，保存那一下屏幕会暗一次。", "把整個畫面存成圖片檔；PNG 會堆在圖片資料夾下的 Screenshots 裡，儲存那一下畫面會暗一次。"],
  'windows-active-window-screenshot': ["지금 앞에 있는 창만 클립보드로 복사합니다. 화면 전체가 아니라 창 하나만 담기니 뒤에 열린 것이 찍히지 않습니다.", "Copies only the window in front to the clipboard, not the whole screen, so nothing behind it ends up in the picture.", "Copia al portapapeles solo la ventana en primer plano, no toda la pantalla, así nada de lo que hay detrás sale en la imagen.", "Copia para a área de transferência somente a janela da frente, não a tela toda, então nada atrás dela aparece na imagem.", "今前面にある窓だけをクリップボードに複写します。画面全体ではなく窓一つだけなので、後ろに開いているものは写りません。", "Kopiert nur das vorderste Fenster in die Zwischenablage, nicht den ganzen Bildschirm — was dahinter liegt, erscheint nicht im Bild.", "Copie dans le presse-papiers uniquement la fenêtre au premier plan, pas tout l écran, donc rien de ce qui est derrière n apparaît.", "केवल सामने वाली window को clipboard में copy करता है, पूरी स्क्रीन को नहीं, इसलिए पीछे खुली चीज़ें चित्र में नहीं आतीं।", "只把最前面那个窗口复制到剪贴板，不是整个屏幕，所以后面开着的东西不会入镜。", "只把最前面那個視窗複製到剪貼簿，不是整個畫面，所以後面開著的東西不會入鏡。"],
  /* ═════════ macos ═════════ */
  'macos-spotlight': ["어디서든 검색 칸을 띄워 앱·파일·계산·환율까지 한 줄로 처리합니다. 입력원을 둘 이상 쓰면 이 조합이 언어 바꾸기와 다투는 일이 있어, 설정에서 한쪽을 비켜 줘야 합니다.", "Pops up a search field anywhere for apps, files, sums and conversions in one line; with two or more input sources this combination can fight the language switcher, so one of them has to give way in Settings.", "Abre un campo de búsqueda en cualquier sitio para apps, archivos, cuentas y conversiones; con dos o más fuentes de entrada puede chocar con el cambio de idioma, y hay que ceder una en Ajustes.", "Abre um campo de busca em qualquer lugar para apps, arquivos, contas e conversões; com duas ou mais fontes de entrada, essa combinação pode brigar com a troca de idioma, e uma delas precisa ceder nos Ajustes.", "どこでも検索欄を出し、アプリ・ファイル・計算・為替まで一行で片づけます。入力ソースを二つ以上使うとこの組み合わせが言語切り替えと争うことがあり、設定で片方を譲る必要があります。", "Öffnet überall ein Suchfeld für Apps, Dateien, Rechnungen und Umrechnungen in einer Zeile; bei zwei oder mehr Eingabequellen kollidiert die Folge mit dem Sprachwechsel, eine muss in den Einstellungen weichen.", "Ouvre partout un champ de recherche pour applications, fichiers, calculs et conversions ; avec deux sources de saisie ou plus, la combinaison entre en conflit avec le changement de langue, et l une doit céder dans les Réglages.", "कहीं भी एक खोज-पट्टी खोल देता है जिसमें app, फ़ाइल, हिसाब और विनिमय एक ही पंक्ति में होते हैं; दो या अधिक input source हों तो यह combination भाषा बदलने से टकरा सकता है और Settings में एक को हटाना पड़ता है।", "在任何地方弹出搜索框，应用、文件、算式、汇率一行搞定；装了两种以上输入法时，这个组合会和切换语言打架，得在设置里让开一个。", "在任何地方彈出搜尋框，應用程式、檔案、算式、匯率一行搞定；裝了兩種以上輸入法時，這個組合會和切換語言打架，得在設定裡讓開一個。"],
  'macos-input-source': ["입력원을 앞서 쓰던 것으로 바꿉니다. Spotlight를 기대하고 눌렀다가 자판이 바뀌는 일이 잦으니, 두 조합을 함께 기억해 둡니다.", "Switches to the input source you used before; people reaching for Spotlight often land on a language change here, so it pays to know both keys.", "Cambia a la fuente de entrada anterior; quien busca Spotlight acaba cambiando de idioma, así que conviene conocer ambas combinaciones.", "Muda para a fonte de entrada anterior; quem procura o Spotlight acaba trocando de idioma, então vale conhecer as duas combinações.", "入力ソースを直前のものに切り替えます。Spotlight のつもりで押して配列が変わることが多いので、二つの組み合わせを併せて覚えます。", "Wechselt zur zuvor genutzten Eingabequelle; wer Spotlight will, landet hier oft bei einem Sprachwechsel — beide Kürzel zu kennen lohnt sich.", "Passe à la source de saisie précédente ; ceux qui visent Spotlight changent souvent de langue par erreur, mieux vaut connaître les deux.", "पिछले इस्तेमाल किए input source पर बदल देता है; Spotlight सोचकर दबाने वाले यहाँ भाषा बदल बैठते हैं, इसलिए दोनों combination याद रखना अच्छा है।", "切回上一个使用的输入法；本想按 Spotlight 的人常在这儿把键盘语言换了，两个组合最好一起记住。", "切回上一個使用的輸入法；本想按 Spotlight 的人常在這兒把鍵盤語言換了，兩個組合最好一起記住。"],
  'macos-toggle-dock': ["독을 감추거나 다시 꺼냅니다. 창 아래쪽이 독에 가릴 때 창을 옮기지 않고 화면을 넓히는 가장 짧은 길입니다.", "Hides the Dock or brings it back; when it covers the bottom of a window this is the shortest way to win screen space without moving the window.", "Oculta el Dock o lo devuelve; cuando tapa la parte baja de una ventana es la vía más corta para ganar espacio sin mover la ventana.", "Esconde o Dock ou o traz de volta; quando ele cobre a parte de baixo de uma janela, é o caminho mais curto para ganhar espaço sem mover a janela.", "Dock を隠したり戻したりします。窓の下側が Dock に隠れるとき、窓を動かさずに画面を広げる最短の道です。", "Blendet das Dock aus oder wieder ein; verdeckt es den unteren Rand eines Fensters, ist dies der kürzeste Weg zu mehr Fläche, ohne das Fenster zu verschieben.", "Masque le Dock ou le fait revenir ; quand il recouvre le bas d une fenêtre, c est le plus court chemin pour gagner de la place sans déplacer la fenêtre.", "Dock को छिपा देता है या वापस ले आता है; जब यह window के निचले हिस्से को ढके, तो window हिलाए बिना जगह पाने का सबसे छोटा रास्ता यही है।", "隐藏或重新显示程序坞；它挡住窗口下沿时，这是不挪窗口就多出屏幕空间的最短路径。", "隱藏或重新顯示 Dock；它擋住視窗下緣時，這是不挪視窗就多出畫面空間的最短路徑。"],
  'macos-lock-screen': ["화면을 즉시 잠급니다. 앱은 그대로 돌아가니 Cmd+Q로 앱을 끄는 것과는 완전히 다른 일입니다.", "Locks the screen at once; the apps keep running, which makes it a completely different act from quitting one with Cmd+Q.", "Bloquea la pantalla al instante; las apps siguen corriendo, algo muy distinto de cerrar una con Cmd+Q.", "Bloqueia a tela na hora; os apps continuam rodando, o que é bem diferente de encerrar um com Cmd+Q.", "画面をすぐに施錠します。アプリはそのまま動くので、Cmd+Q でアプリを終了するのとは全く別のことです。", "Sperrt den Bildschirm sofort; die Apps laufen weiter, was etwas völlig anderes ist als eine App mit Cmd+Q zu beenden.", "Verrouille l écran immédiatement ; les apps continuent de tourner, ce qui n a rien à voir avec quitter une app par Cmd+Q.", "स्क्रीन तुरंत लॉक कर देता है; apps चलते रहते हैं, इसलिए यह Cmd+Q से app बंद करने से बिलकुल अलग काम है।", "立刻锁屏；应用照旧运行，这和用 Cmd+Q 退出应用完全是两件事。", "立刻鎖定螢幕；應用程式照舊執行，這和用 Cmd+Q 結束應用程式完全是兩件事。"],
  'macos-sleep': ["맥을 잠자기로 보냅니다. 전원 단추가 없는 자판에서는 Cmd+Option과 미디어 꺼내기 글쇠가 그 자리를 대신합니다.", "Puts the Mac to sleep; on a keyboard with no power button, Cmd+Option with the media eject key takes its place.", "Pone el Mac en reposo; en un teclado sin botón de encendido, Cmd+Option con la tecla de expulsión hace lo mismo.", "Coloca o Mac em repouso; em um teclado sem botão de força, Cmd+Option com a tecla de ejetar faz o mesmo.", "Mac をスリープさせます。電源ボタンの無いキーボードでは、Cmd+Option とメディア取り出しキーがその役を担います。", "Versetzt den Mac in den Ruhezustand; auf einer Tastatur ohne Ein-Taste übernimmt Cmd+Option mit der Auswurftaste diese Rolle.", "Met le Mac en veille ; sur un clavier sans bouton d alimentation, Cmd+Option avec la touche d éjection joue ce rôle.", "Mac को नींद में भेज देता है; जिस keyboard पर power बटन नहीं है वहाँ Cmd+Option और media eject कुंजी वही काम करती है।", "让 Mac 进入睡眠；键盘上没有电源键时，用 Cmd+Option 加媒体退出键代替。", "讓 Mac 進入睡眠；鍵盤上沒有電源鍵時，用 Cmd+Option 加媒體退出鍵代替。"],
  'macos-emoji-picker': ["글을 쓰는 어느 칸에서든 이모지와 기호를 고르는 창을 엽니다. 이모지뿐 아니라 화살표와 수식 기호도 같은 창에 있습니다.", "Opens the emoji and symbol picker in any text field; the same window also holds arrows and mathematical signs, not just emoji.", "Abre el selector de emoji y símbolos en cualquier campo de texto; la misma ventana incluye flechas y signos matemáticos, no solo emoji.", "Abre o seletor de emoji e símbolos em qualquer campo de texto; a mesma janela traz setas e sinais matemáticos, não só emoji.", "文字を書くどの欄でも、絵文字と記号を選ぶ画面を開きます。絵文字だけでなく矢印や数式記号も同じ画面にあります。", "Öffnet in jedem Textfeld die Auswahl für Emoji und Symbole; dasselbe Fenster enthält auch Pfeile und mathematische Zeichen.", "Ouvre le sélecteur d emoji et de symboles dans n importe quel champ de texte ; la même fenêtre contient aussi flèches et signes mathématiques.", "किसी भी text field में emoji और चिह्न चुनने वाली window खोलता है; उसी window में तीर और गणित के चिह्न भी होते हैं, केवल emoji नहीं।", "在任何输入框里打开表情和符号选择器；同一个窗口里除了表情，还有箭头和数学符号。", "在任何輸入框裡開啟表情和符號選擇器；同一個視窗裡除了表情，還有箭頭和數學符號。"],
  'macos-function-keys': ["맨 윗줄을 밝기·소리 대신 진짜 F1부터 F12로 씁니다. 설정에서 기본을 바꿨다면 Fn이 반대로 밝기·소리를 부릅니다.", "Makes the top row act as real F1 to F12 instead of brightness and volume; if you flipped that setting, Fn does the opposite and calls the media keys.", "Hace que la fila superior actúe como F1 a F12 reales en vez de brillo y volumen; si cambiaste ese ajuste, Fn hace lo contrario y llama a las teclas multimedia.", "Faz a fileira de cima agir como F1 a F12 de verdade em vez de brilho e volume; se você inverteu essa opção, Fn faz o contrário e chama as teclas de mídia.", "最上段を明るさや音量ではなく本当の F1 から F12 として使います。設定で既定を入れ替えていれば、Fn は逆に明るさや音量を呼びます。", "Lässt die obere Reihe als echte F1 bis F12 wirken statt als Helligkeit und Lautstärke; haben Sie die Einstellung umgestellt, ruft Fn umgekehrt die Medientasten.", "Fait agir la rangée du haut comme de vraies touches F1 à F12 au lieu de la luminosité et du volume ; si vous avez inversé ce réglage, Fn appelle au contraire les touches multimédias.", "ऊपरी पंक्ति को चमक-आवाज़ की जगह असली F1 से F12 की तरह चलाता है; यदि आपने वह setting पलट दी है तो Fn उलटा media कुंजियाँ बुलाता है।", "让最上面一排当成真正的 F1 到 F12，而不是亮度和音量；若你在设置里换了默认，Fn 的作用正好相反。", "讓最上面一排當成真正的 F1 到 F12，而不是亮度和音量；若你在設定裡換了預設，Fn 的作用正好相反。"],
  'macos-switch-app': ["앱과 앱 사이를 오갑니다. 창이 아니라 앱을 넘나드는 것이라, 창을 모두 내려 둔 앱은 창 없이 앞으로만 나옵니다.", "Steps between apps rather than windows, so an app whose windows are all hidden comes to the front with nothing on screen.", "Recorre aplicaciones y no ventanas, así que una app con todas sus ventanas ocultas pasa al frente sin mostrar nada.", "Percorre aplicativos e não janelas, então um app com todas as janelas escondidas vem para a frente sem mostrar nada.", "窓ではなくアプリの間を渡ります。窓をすべて隠したアプリは、窓を出さずに前面へ出るだけです。", "Wandert zwischen Apps, nicht zwischen Fenstern; eine App mit lauter versteckten Fenstern kommt daher ohne sichtbares Fenster nach vorn.", "Passe d une application à l autre et non d une fenêtre à l autre ; une app dont toutes les fenêtres sont masquées revient au premier plan sans rien afficher.", "windows के बीच नहीं, apps के बीच घूमता है; जिस app की सारी windows छिपी हों वह बिना कुछ दिखाए आगे आ जाता है।", "在应用之间切换，而不是窗口之间；一个所有窗口都隐藏了的应用，会只是被拿到前台却什么都不显示。", "在應用程式之間切換，而不是視窗之間；一個所有視窗都隱藏了的應用程式，會只是被拿到前台卻什麼都不顯示。"],
  'macos-switch-window': ["같은 앱의 창들 사이를 오갑니다. Cmd+Tab이 하지 못하는 일이 바로 이것이라, 창을 여러 개 띄우는 앱에서는 둘을 짝으로 씁니다.", "Steps between the windows of one app, which is exactly what Cmd+Tab cannot do, so the two work as a pair in apps that open many windows.", "Recorre las ventanas de una misma app, justo lo que Cmd+Tab no hace, así que ambos se usan en pareja en apps con muchas ventanas.", "Percorre as janelas de um mesmo app, justamente o que o Cmd+Tab não faz, então os dois andam em par em apps com muitas janelas.", "同じアプリの窓の間を渡ります。Cmd+Tab にできないのがまさにこれで、窓を多く開くアプリでは二つを対で使います。", "Wandert zwischen den Fenstern einer App — genau das, was Cmd+Tab nicht kann, weshalb beide in fensterreichen Apps ein Paar bilden.", "Passe d une fenêtre à l autre au sein d une même app, précisément ce que Cmd+Tab ne fait pas, d où l usage des deux en tandem.", "एक ही app की windows के बीच घूमता है, जो Cmd+Tab नहीं कर सकता, इसलिए कई windows खोलने वाले apps में दोनों जोड़ी बनकर काम करते हैं।", "在同一个应用的多个窗口之间切换，这正是 Cmd+Tab 做不到的，所以窗口多的应用里两者要配着用。", "在同一個應用程式的多個視窗之間切換，這正是 Cmd+Tab 做不到的，所以視窗多的應用程式裡兩者要配著用。"],
  'macos-quit-app': ["앱을 완전히 끝냅니다. 창만 닫는 Cmd+W와 다른 점이 여기이고, 독에 있던 점이 사라지는 것으로 정말 끝났는지 알 수 있습니다.", "Quits the app for good; that is the difference from Cmd+W, which closes only a window, and the dot under the Dock icon disappearing tells you it really ended.", "Cierra la aplicación por completo; ahí está la diferencia con Cmd+W, que solo cierra una ventana, y el punto bajo el icono del Dock desaparece cuando de verdad ha terminado.", "Encerra o aplicativo de vez; é essa a diferença em relação ao Cmd+W, que fecha só uma janela, e o ponto sob o ícone do Dock desaparecendo confirma o fim.", "アプリを完全に終了します。窓だけを閉じる Cmd+W との違いはここで、Dock のアイコン下の点が消えれば本当に終わったと分かります。", "Beendet die App vollständig; darin liegt der Unterschied zu Cmd+W, das nur ein Fenster schließt, und der verschwundene Punkt unter dem Dock-Symbol beweist das Ende.", "Quitte complètement l application ; c est là toute la différence avec Cmd+W qui ne ferme qu une fenêtre, et le point sous l icône du Dock qui disparaît confirme la fin.", "app को पूरी तरह बंद कर देता है; Cmd+W से अंतर यही है, जो केवल एक window बंद करता है, और Dock के icon के नीचे का बिंदु मिटना बताता है कि वह सचमुच बंद हुआ।", "彻底退出应用；这就是它和只关窗口的 Cmd+W 的区别，程序坞图标下的小点消失，说明真的退出了。", "徹底結束應用程式；這就是它和只關視窗的 Cmd+W 的區別，Dock 圖示下的小點消失，說明真的結束了。"],
  'macos-close-window': ["창 하나만 닫습니다. 앱은 그대로 돌아가고 독에 점이 남아 있으니, 정말 끄려면 Cmd+Q를 눌러야 합니다.", "Closes just one window; the app keeps running with the dot still under its Dock icon, so quitting takes Cmd+Q.", "Cierra solo una ventana; la app sigue corriendo con su punto en el Dock, así que para cerrarla de verdad hace falta Cmd+Q.", "Fecha apenas uma janela; o app continua rodando com o ponto sob o ícone do Dock, então encerrar exige Cmd+Q.", "窓を一つだけ閉じます。アプリはそのまま動いて Dock に点が残るので、本当に終えるには Cmd+Q が必要です。", "Schließt nur ein Fenster; die App läuft weiter, der Punkt bleibt unter ihrem Dock-Symbol, und zum Beenden braucht es Cmd+Q.", "Ne ferme qu une fenêtre ; l app continue de tourner avec son point sous l icône du Dock, et il faut Cmd+Q pour vraiment la quitter.", "केवल एक window बंद करता है; app चलता रहता है और Dock में उसका बिंदु बना रहता है, इसलिए सचमुच बंद करने के लिए Cmd+Q चाहिए।", "只关掉一个窗口；应用仍在运行，程序坞图标下的点还在，真要退出得按 Cmd+Q。", "只關掉一個視窗；應用程式仍在執行，Dock 圖示下的點還在，真要結束得按 Cmd+Q。"],
  'macos-force-quit': ["응답하지 않는 앱을 골라 강제로 끝내는 목록을 엽니다. Cmd+Option+Shift+Esc를 몇 초 누르고 있으면 목록 없이 앞의 앱이 바로 끝납니다.", "Opens the list where you pick an unresponsive app and force it to quit; holding Cmd+Option+Shift+Esc for a few seconds kills the front app without the list.", "Abre la lista para elegir una app que no responde y forzar su cierre; mantener Cmd+Option+Shift+Esc unos segundos cierra la app en primer plano sin lista.", "Abre a lista para escolher um app que não responde e forçar o encerramento; manter Cmd+Option+Shift+Esc por alguns segundos encerra o app da frente sem lista.", "応答しないアプリを選んで強制終了する一覧を開きます。Cmd+Option+Shift+Esc を数秒押し続けると、一覧なしで最前面のアプリが終了します。", "Öffnet die Liste, in der Sie eine hängende App auswählen und zum Beenden zwingen; hält man Cmd+Option+Shift+Esc einige Sekunden, endet die vorderste App ohne Liste.", "Ouvre la liste où choisir une app qui ne répond plus et la forcer à quitter ; maintenir Cmd+Option+Shift+Esc quelques secondes tue l app au premier plan sans liste.", "जवाब न देने वाले app को चुनकर ज़बरदस्ती बंद करने की सूची खोलता है; Cmd+Option+Shift+Esc कुछ सेकंड दबाए रखें तो सूची के बिना सामने का app बंद हो जाता है।", "打开列表，挑出没响应的应用强制退出；按住 Cmd+Option+Shift+Esc 几秒，可以不开列表直接结束最前面的应用。", "開啟清單，挑出沒回應的應用程式強制結束；按住 Cmd+Option+Shift+Esc 幾秒，可以不開清單直接結束最前面的應用程式。"],
  'macos-preferences': ["지금 앞에 있는 앱의 설정 창을 엽니다. 앱마다 메뉴 자리가 달라도 이 한 조합은 거의 모든 앱에서 통합니다.", "Opens the settings window of whatever app is in front; the menu item sits in a different place in every app, but this one combination works in nearly all of them.", "Abre la ventana de ajustes de la app en primer plano; el menú está en distinto sitio en cada app, pero esta combinación funciona en casi todas.", "Abre a janela de ajustes do app que está à frente; o item de menu fica em lugar diferente em cada app, mas essa combinação funciona em quase todos.", "今前面にあるアプリの設定画面を開きます。メニューの位置はアプリごとに違っても、この一つの組み合わせはほとんどのアプリで通じます.", "Öffnet das Einstellungsfenster der vordersten App; der Menüpunkt liegt in jeder App anders, doch diese eine Folge funktioniert in fast allen.", "Ouvre la fenêtre des réglages de l app au premier plan ; l entrée de menu change de place selon l app, mais cette combinaison marche dans presque toutes.", "सामने खुले app की settings window खोलता है; मेनू की जगह हर app में अलग होती है, पर यह एक combination लगभग सब में चलता है।", "打开最前面那个应用的设置窗口；菜单位置各家不同，但这一个组合几乎在所有应用里都通。", "開啟最前面那個應用程式的設定視窗；選單位置各家不同，但這一個組合幾乎在所有應用程式裡都通。"],
  'macos-hide-app': ["앞에 있는 앱의 창을 모두 감춥니다. 독으로 내리는 최소화와 달리 창 그림이 남지 않고, 그 앱으로 돌아가면 그대로 다시 나타납니다.", "Hides every window of the front app; unlike minimising, no thumbnail is left in the Dock, and the windows reappear as they were when you return to the app.", "Oculta todas las ventanas de la app en primer plano; a diferencia de minimizar, no deja miniatura en el Dock, y vuelven tal cual al regresar a la app.", "Esconde todas as janelas do app da frente; diferente de minimizar, não deixa miniatura no Dock, e elas voltam como estavam quando você retorna ao app.", "前面のアプリの窓をすべて隠します。Dock へ下げる最小化とは違って縮小画が残らず、そのアプリへ戻ればそのまま現れます。", "Versteckt alle Fenster der vordersten App; anders als beim Minimieren bleibt kein Vorschaubild im Dock, und beim Zurückwechseln sind sie unverändert da.", "Masque toutes les fenêtres de l app au premier plan ; contrairement à la réduction, aucune vignette ne reste dans le Dock, et tout revient tel quel.", "सामने के app की सारी windows छिपा देता है; minimize से अलग, Dock में कोई छोटी छवि नहीं रहती, और app पर लौटते ही वे जैसी थीं वैसी दिख जाती हैं।", "把最前面应用的所有窗口都藏起来；和最小化不同，程序坞里不留缩略图，切回这个应用时原样出现。", "把最前面應用程式的所有視窗都藏起來；和最小化不同，Dock 裡不留縮圖，切回這個應用程式時原樣出現。"],
  'macos-hide-others': ["지금 앱만 남기고 나머지 앱의 창을 모두 감춥니다. 화면을 한 가지 일만 남기고 비우는 데 가장 빠른 길입니다.", "Hides the windows of every app except this one, which is the quickest way to clear the screen down to a single task.", "Oculta las ventanas de todas las apps salvo esta, la vía más rápida para dejar la pantalla con una sola tarea.", "Esconde as janelas de todos os apps menos este, o caminho mais rápido para deixar a tela com uma única tarefa.", "今のアプリだけを残し、ほかのアプリの窓をすべて隠します。画面を一つの仕事だけにする最速の道です。", "Versteckt die Fenster aller anderen Apps und lässt nur diese stehen — der schnellste Weg zu einem Bildschirm mit einer einzigen Aufgabe.", "Masque les fenêtres de toutes les autres apps et ne garde que celle-ci, la voie la plus rapide vers un écran dédié à une seule tâche.", "इस app को छोड़कर बाक़ी सब apps की windows छिपा देता है; स्क्रीन को एक ही काम तक सीमित करने का सबसे तेज़ रास्ता।", "除了当前应用，把其他应用的窗口全藏起来；想把屏幕清到只剩一件事，这最快。", "除了目前應用程式，把其他應用程式的視窗全藏起來；想把畫面清到只剩一件事，這最快。"],
  'macos-minimize': ["창을 독으로 접어 내립니다. Cmd+Option+M을 누르면 그 앱의 창을 한꺼번에 다 내립니다.", "Folds the window down into the Dock; Cmd+Option+M sends every window of that app down at once.", "Repliega la ventana en el Dock; Cmd+Option+M baja de golpe todas las ventanas de esa app.", "Recolhe a janela para o Dock; Cmd+Option+M manda todas as janelas daquele app para baixo de uma vez.", "窓を Dock へ折りたたんで下げます。Cmd+Option+M を押すと、そのアプリの窓を一度にすべて下げます。", "Klappt das Fenster ins Dock; Cmd+Option+M schickt alle Fenster dieser App auf einmal hinunter.", "Replie la fenêtre dans le Dock ; Cmd+Option+M y envoie toutes les fenêtres de l app d un coup.", "window को Dock में समेट देता है; Cmd+Option+M उस app की सारी windows एक साथ नीचे भेज देता है।", "把窗口收进程序坞；按 Cmd+Option+M 会一次把该应用的所有窗口都收下去。", "把視窗收進 Dock；按 Cmd+Option+M 會一次把該應用程式的所有視窗都收下去。"],
  'macos-fullscreen': ["창을 전체 화면으로 만들거나 되돌립니다. 전체 화면이 된 창은 그 자체가 하나의 공간이 되어 Mission Control에 새 칸으로 나타납니다.", "Puts the window into full screen or brings it back; a full-screen window becomes a space of its own and shows up as a new tile in Mission Control.", "Pone la ventana en pantalla completa o la devuelve; una ventana a pantalla completa se vuelve un espacio propio y aparece como nuevo recuadro en Mission Control.", "Coloca a janela em tela cheia ou a traz de volta; uma janela em tela cheia se torna um espaço próprio e aparece como novo bloco no Mission Control.", "窓を全画面にしたり戻したりします。全画面になった窓はそれ自体が一つの space となり、Mission Control に新しい枠として現れます。", "Schaltet das Fenster in den Vollbildmodus und zurück; ein Vollbildfenster wird zu einem eigenen Space und erscheint als neue Fläche in Mission Control.", "Passe la fenêtre en plein écran ou la ramène ; une fenêtre en plein écran devient un espace à part et apparaît comme nouvelle tuile dans Mission Control.", "window को पूरी स्क्रीन पर कर देता है या वापस लाता है; पूरी स्क्रीन वाली window ख़ुद एक space बन जाती है और Mission Control में नए खाने की तरह दिखती है।", "把窗口切成全屏或还原；全屏后的窗口本身成了一个独立空间，会作为新的一格出现在调度中心里。", "把視窗切成全螢幕或還原；全螢幕後的視窗本身成了一個獨立空間，會作為新的一格出現在指揮中心裡。"],
  'macos-switch-space': ["오른쪽 데스크톱 공간으로 넘어갑니다. 전체 화면 앱도 하나의 공간으로 세기 때문에, 공간 수가 저절로 늘어난 것처럼 보입니다.", "Moves to the desktop space on the right; a full-screen app counts as a space too, which is why the number of spaces seems to grow on its own.", "Pasa al espacio de escritorio de la derecha; una app a pantalla completa también cuenta como espacio, y por eso parece que se multiplican solos.", "Vai para o espaço de trabalho da direita; um app em tela cheia também conta como espaço, e por isso o número parece crescer sozinho.", "右のデスクトップ space へ移ります。全画面のアプリも一つの space として数えるので、space の数が勝手に増えたように見えます。", "Wechselt zum Desktop-Space rechts; auch eine Vollbild-App zählt als Space, weshalb ihre Zahl scheinbar von selbst wächst.", "Passe à l espace de bureau de droite ; une app en plein écran compte aussi comme un espace, d où l impression qu ils se multiplient tout seuls.", "दाईं ओर के desktop space पर चला जाता है; पूरी स्क्रीन वाला app भी एक space गिना जाता है, इसलिए space की संख्या अपने आप बढ़ी लगती है।", "切到右边的桌面空间；全屏的应用也算一个空间，所以空间数看着像自己变多了。", "切到右邊的桌面空間；全螢幕的應用程式也算一個空間，所以空間數看著像自己變多了。"],
  'macos-screenshot-full': ["화면 전체를 찍어 파일로 저장합니다. 기본 저장 자리는 데스크톱이고, 그 자리는 Cmd+Shift+5 창에서 바꿉니다.", "Captures the whole screen and saves it as a file; the default place is the desktop, and you change that in the Cmd+Shift+5 panel.", "Captura toda la pantalla y la guarda como archivo; el sitio por defecto es el escritorio, y se cambia en el panel de Cmd+Shift+5.", "Captura a tela inteira e salva como arquivo; o lugar padrão é a mesa, e você muda isso no painel do Cmd+Shift+5.", "画面全体を撮ってファイルとして保存します。既定の保存先はデスクトップで、その場所は Cmd+Shift+5 の画面で変えます。", "Nimmt den ganzen Bildschirm auf und speichert ihn als Datei; Standardort ist der Schreibtisch, änderbar im Fenster von Cmd+Shift+5.", "Capture tout l écran et l enregistre en fichier ; l emplacement par défaut est le bureau, modifiable dans le panneau de Cmd+Shift+5.", "पूरी स्क्रीन का चित्र लेकर फ़ाइल में सहेजता है; डिफ़ॉल्ट जगह desktop है, और उसे Cmd+Shift+5 के panel में बदला जाता है।", "拍下整个屏幕并存成文件；默认存到桌面，存放位置在 Cmd+Shift+5 的面板里改。", "拍下整個畫面並存成檔案；預設存到桌面，存放位置在 Cmd+Shift+5 的面板裡改。"],
  'macos-screenshot-selection': ["십자 커서로 원하는 자리만 끌어서 찍습니다. 끌기 전에 Space를 누르면 커서가 사진기로 바뀌어 창 하나만 깔끔하게 담습니다.", "Gives you a crosshair to drag out just the part you want; press Space before dragging and the pointer becomes a camera that captures one whole window cleanly.", "Da una cruz para arrastrar solo la zona que quieres; pulsa Space antes de arrastrar y el puntero se vuelve una cámara que captura una ventana entera.", "Dá uma mira para arrastar só a parte que você quer; aperte Space antes de arrastar e o ponteiro vira uma câmera que captura uma janela inteira.", "十字カーソルで欲しい範囲だけを囲んで撮ります。ドラッグの前に Space を押すとポインタがカメラに変わり、窓一つをきれいに収められます。", "Gibt ein Kreuz, mit dem Sie genau den gewünschten Bereich aufziehen; drücken Sie vor dem Ziehen Space, wird der Zeiger zur Kamera und nimmt ein ganzes Fenster sauber auf.", "Fournit une croix pour délimiter la zone voulue ; appuyez sur Space avant de glisser et le pointeur devient un appareil photo qui capture proprement une fenêtre entière.", "एक क्रॉस cursor देता है जिससे आप केवल मनचाहा हिस्सा खींच सकते हैं; खींचने से पहले Space दबाएँ तो pointer कैमरा बन जाता है और पूरी एक window साफ़ पकड़ लेता है।", "给出十字光标，让你只框出想要的那块；拖之前按 Space，光标会变成相机，干净地拍下整个窗口。", "給出十字游標，讓你只框出想要的那塊；拖之前按 Space，游標會變成相機，乾淨地拍下整個視窗。"],
  'macos-screenshot-toolbar': ["찍기와 화면 녹화, 저장 자리와 타이머까지 고르는 막대를 엽니다. 이 막대에서 정한 저장 자리는 Cmd+Shift+3과 4에도 그대로 쓰입니다.", "Opens the bar with capture and screen recording plus options for where to save and a timer; whatever you set here also applies to Cmd+Shift+3 and 4.", "Abre la barra con captura y grabación de pantalla, además de dónde guardar y un temporizador; lo que fijes aquí también rige para Cmd+Shift+3 y 4.", "Abre a barra com captura e gravação de tela, além de onde salvar e um cronômetro; o que você definir aqui vale também para Cmd+Shift+3 e 4.", "撮影と画面収録、保存先やタイマーまで選べる棒を開きます。ここで決めた保存先は Cmd+Shift+3 と 4 にもそのまま効きます。", "Öffnet die Leiste mit Aufnahme und Bildschirmvideo sowie Speicherort und Timer; was Sie hier festlegen, gilt auch für Cmd+Shift+3 und 4.", "Ouvre la barre avec capture et enregistrement d écran, plus le dossier de destination et un minuteur ; ce que vous réglez ici vaut aussi pour Cmd+Shift+3 et 4.", "चित्र लेने और स्क्रीन रिकॉर्ड करने के साथ सहेजने की जगह और timer चुनने वाली पट्टी खोलता है; यहाँ तय की गई जगह Cmd+Shift+3 और 4 पर भी लागू होती है।", "打开带截图和录屏的工具条，还能选保存位置和定时；这里设的保存位置对 Cmd+Shift+3 和 4 同样有效。", "開啟帶截圖和錄影的工具條，還能選儲存位置和定時；這裡設的儲存位置對 Cmd+Shift+3 和 4 同樣有效。"],
  'macos-screenshot-to-clipboard': ["고른 자리를 파일이 아니라 클립보드로 바로 담습니다. 어떤 찍기 조합에든 Ctrl을 더하면 파일 대신 클립보드로 간다는 규칙입니다.", "Puts the selected area straight into the clipboard instead of a file; the rule is that adding Ctrl to any screenshot combination sends it to the clipboard.", "Manda el área elegida directamente al portapapeles en vez de a un archivo; la regla es que añadir Ctrl a cualquier captura la envía al portapapeles.", "Manda a área escolhida direto para a área de transferência em vez de um arquivo; a regra é que acrescentar Ctrl a qualquer captura a envia para lá.", "選んだ範囲をファイルではなくクリップボードへ直に入れます。どの撮影の組み合わせにも Ctrl を足せばクリップボードへ行く、という決まりです。", "Legt den gewählten Bereich direkt in die Zwischenablage statt in eine Datei; die Regel lautet: Ctrl zu jeder Bildschirmfoto-Folge hinzufügen schickt es in die Zwischenablage.", "Envoie la zone choisie directement dans le presse-papiers plutôt que dans un fichier ; la règle est qu ajouter Ctrl à n importe quelle capture la met au presse-papiers.", "चुने हुए हिस्से को फ़ाइल की जगह सीधे clipboard में डाल देता है; नियम यह है कि किसी भी screenshot combination में Ctrl जोड़ने पर वह clipboard में जाता है।", "把所选区域直接放进剪贴板而不是存成文件；规则是任何截图组合加上 Ctrl，结果就进剪贴板。", "把所選區域直接放進剪貼簿而不是存成檔案；規則是任何截圖組合加上 Ctrl，結果就進剪貼簿。"],
  'macos-go-to-folder': ["경로를 직접 쳐서 그 폴더로 갑니다. 물결표로 홈을 가리킬 수 있고, 이 창에서는 감춰진 폴더도 이름을 치면 들어갑니다.", "Takes you to a folder by typing its path; a tilde stands for your home, and in this box even a hidden folder opens if you type its name.", "Te lleva a una carpeta escribiendo su ruta; la virgulilla representa tu carpeta personal, y aquí incluso una carpeta oculta se abre si escribes su nombre.", "Leva você a uma pasta digitando o caminho; o til representa sua pasta pessoal, e nessa caixa até uma pasta oculta abre se você digitar o nome.", "経路を直に打ってそのフォルダーへ行きます。チルダで自分のホームを指せ、この画面では隠れたフォルダーも名前を打てば入れます。", "Bringt Sie über die eingetippte Pfadangabe zu einem Ordner; die Tilde steht für Ihr Benutzerverzeichnis, und selbst ein versteckter Ordner öffnet sich hier per Namen.", "Vous emmène dans un dossier en tapant son chemin ; le tilde désigne votre dossier personnel, et même un dossier caché s ouvre ici si vous saisissez son nom.", "रास्ता टाइप करके उस folder में ले जाता है; tilde आपके home को दर्शाता है, और इस box में छिपा folder भी नाम लिखने पर खुल जाता है।", "直接输入路径就跳到那个文件夹；波浪号代表个人主目录，在这个框里连隐藏文件夹打出名字也能进去。", "直接輸入路徑就跳到那個資料夾；波浪號代表個人主目錄，在這個框裡連隱藏資料夾打出名字也能進去。"],
  'macos-show-hidden-files': ["점으로 시작하는 감춰진 파일을 보이게 하거나 다시 감춥니다. Finder뿐 아니라 열기·저장 창에서도 같은 조합이 듣습니다.", "Shows the hidden files that begin with a dot, and hides them again; the same combination works in Open and Save dialogs as well as in the Finder.", "Muestra los archivos ocultos que empiezan por punto y los vuelve a esconder; la misma combinación sirve en los cuadros de abrir y guardar, no solo en el Finder.", "Mostra os arquivos ocultos que começam com ponto e os esconde de novo; a mesma combinação funciona nas caixas de abrir e salvar, não só no Finder.", "点で始まる隠しファイルを表示したり、また隠したりします。Finder だけでなく開く・保存の画面でも同じ組み合わせが効きます。", "Zeigt die versteckten Dateien mit führendem Punkt und blendet sie wieder aus; die Folge wirkt auch in Öffnen- und Speichern-Dialogen, nicht nur im Finder.", "Affiche les fichiers cachés commençant par un point, puis les masque à nouveau ; la même combinaison agit aussi dans les boîtes d ouverture et d enregistrement.", "बिंदु से शुरू होने वाली छिपी फ़ाइलें दिखाता है और फिर छिपा देता है; यही combination Finder के साथ open और save वाले box में भी चलता है।", "把以点开头的隐藏文件显示出来，再按一次藏回去；这个组合在打开和保存对话框里也一样有效，不只在 Finder 里。", "把以點開頭的隱藏檔案顯示出來，再按一次藏回去；這個組合在開啟和儲存對話框裡也一樣有效，不只在 Finder 裡。"],
  'macos-enclosing-folder': ["한 단계 위 폴더로 올라갑니다. 반대로 Cmd+Down은 고른 것을 열고 들어가니, 두 키로 폴더를 오르내립니다.", "Goes up one folder; Cmd+Down does the opposite by opening what is selected, so the two keys walk you up and down the tree.", "Sube una carpeta; Cmd+Down hace lo contrario y abre lo seleccionado, así que las dos teclas te suben y bajan por el árbol.", "Sobe uma pasta; Cmd+Down faz o contrário e abre o que está selecionado, então as duas teclas sobem e descem a árvore.", "一つ上のフォルダーへ上がります。逆に Cmd+Down は選んだものを開いて入るので、二つのキーでフォルダーを上下します。", "Geht einen Ordner nach oben; Cmd+Down macht das Gegenteil und öffnet das Ausgewählte, sodass beide Tasten den Baum hinauf und hinab führen.", "Remonte d un dossier ; Cmd+Down fait l inverse en ouvrant l élément sélectionné, les deux touches font donc monter et descendre l arborescence.", "एक folder ऊपर जाता है; इसके उलट Cmd+Down चुनी हुई चीज़ को खोलता है, इसलिए दोनों कुंजियाँ पेड़ पर ऊपर-नीचे ले जाती हैं।", "往上一级文件夹；反过来 Cmd+Down 是打开所选项进去，两个键正好一上一下。", "往上一層資料夾；反過來 Cmd+Down 是開啟所選項進去，兩個鍵正好一上一下。"],
  'macos-move-to-trash': ["고른 것을 휴지통으로 보냅니다. Finder에서 Delete만 누르면 아무 일도 일어나지 않아, 윈도우에서 옮겨 온 사람이 가장 먼저 걸리는 자리입니다.", "Sends the selected item to the Trash; pressing Delete on its own does nothing in the Finder, which is the first thing that catches people coming from Windows.", "Envía lo seleccionado a la Papelera; pulsar solo Delete no hace nada en el Finder, y es lo primero que sorprende a quien viene de Windows.", "Manda o item selecionado para o Lixo; apertar só Delete não faz nada no Finder, e é a primeira coisa que pega quem vem do Windows.", "選んだものをゴミ箱へ送ります。Finder では Delete だけを押しても何も起きないので、Windows から移ってきた人が最初につまずく箇所です。", "Schickt das Ausgewählte in den Papierkorb; ein bloßes Delete tut im Finder nichts — der erste Stolperstein für Umsteiger von Windows.", "Envoie l élément sélectionné à la Corbeille ; appuyer seulement sur Delete ne fait rien dans le Finder, premier piège pour qui vient de Windows.", "चुनी हुई चीज़ को Trash में भेज देता है; Finder में अकेला Delete कुछ नहीं करता, और Windows से आने वाले सबसे पहले यहीं अटकते हैं।", "把所选项目丢进废纸篓；在 Finder 里单按 Delete 什么也不会发生，这是从 Windows 转过来的人最先踩的坑。", "把所選項目丟進垃圾桶；在 Finder 裡單按 Delete 什麼也不會發生，這是從 Windows 轉過來的人最先踩的坑。"],
  'macos-empty-trash': ["휴지통을 비워 되돌릴 수 없게 지웁니다. 물어보는 창이 한 번 뜨고, 그 뒤에는 파일을 찾을 길이 없습니다.", "Empties the Trash and deletes for good; you get one question first, and after that there is no way back to the files.", "Vacía la Papelera y borra definitivamente; primero aparece una pregunta, y después ya no hay forma de recuperar los archivos.", "Esvazia o Lixo e apaga de vez; aparece uma pergunta primeiro, e depois não há como recuperar os arquivos.", "ゴミ箱を空にして取り返せないよう消します。確認の画面が一度出て、その後はファイルを取り戻す道がありません。", "Leert den Papierkorb und löscht endgültig; es kommt eine Rückfrage, danach gibt es keinen Weg zurück zu den Dateien.", "Vide la Corbeille et supprime définitivement ; une question apparaît d abord, ensuite plus aucun retour possible.", "Trash ख़ाली कर देता है और हमेशा के लिए मिटा देता है; पहले एक पुष्टि आती है, उसके बाद फ़ाइलें वापस पाने का रास्ता नहीं बचता।", "清空废纸篓，彻底删除；会先问一次，之后就再没有找回文件的办法。", "清空垃圾桶，徹底刪除；會先問一次，之後就再沒有找回檔案的辦法。"],
  'macos-new-folder': ["지금 Finder 창 안에 새 폴더를 만듭니다. 파일 몇 개를 고른 뒤 Ctrl+Cmd+N을 누르면 그것들을 담은 폴더가 만들어집니다.", "Creates a new folder in the front Finder window; select a few files first and Ctrl+Cmd+N makes a folder with those files already inside.", "Crea una carpeta nueva en la ventana activa del Finder; selecciona antes unos archivos y Ctrl+Cmd+N crea una carpeta con ellos dentro.", "Cria uma nova pasta na janela ativa do Finder; selecione alguns arquivos antes e Ctrl+Cmd+N cria uma pasta já com eles dentro.", "今の Finder の窓の中に新しいフォルダーを作ります。ファイルをいくつか選んでから Ctrl+Cmd+N を押すと、それらを入れたフォルダーができます。", "Erstellt im vordersten Finder-Fenster einen neuen Ordner; markieren Sie erst einige Dateien, erzeugt Ctrl+Cmd+N einen Ordner mit genau diesen darin.", "Crée un nouveau dossier dans la fenêtre du Finder active ; sélectionnez d abord quelques fichiers et Ctrl+Cmd+N crée un dossier les contenant.", "मौजूदा Finder window में नया folder बनाता है; पहले कुछ फ़ाइलें चुनें और Ctrl+Cmd+N दबाएँ तो उन्हीं को समेटे हुए folder बन जाता है।", "在当前 Finder 窗口里新建文件夹；先选几个文件再按 Ctrl+Cmd+N，会建出一个已经装着它们的文件夹。", "在目前 Finder 視窗裡新增資料夾；先選幾個檔案再按 Ctrl+Cmd+N，會建出一個已經裝著它們的資料夾。"],
  'macos-get-info': ["고른 것의 정보 창을 엽니다 — 크기, 놓인 자리, 어떤 앱으로 열리는지. Cmd+Option+I를 쓰면 창이 하나만 열려 고르는 것마다 내용이 바뀝니다.", "Opens the info window for what you selected — size, where it lives, which app opens it; Cmd+Option+I instead gives one inspector window that follows your selection.", "Abre la ventana de información de lo seleccionado: tamaño, ubicación y con qué app se abre; Cmd+Option+I da en cambio una sola ventana que sigue a tu selección.", "Abre a janela de informações do item selecionado: tamanho, onde fica, qual app o abre; Cmd+Option+I dá uma única janela que acompanha a sua seleção.", "選んだものの情報画面を開きます — 大きさ、置かれた場所、どのアプリで開くか。Cmd+Option+I なら窓は一つだけ開き、選ぶものに応じて中身が変わります。", "Öffnet das Infofenster des Ausgewählten — Größe, Ort, öffnende App; Cmd+Option+I liefert stattdessen ein einziges Inspektorfenster, das der Auswahl folgt.", "Ouvre la fenêtre d informations de l élément choisi : taille, emplacement, app qui l ouvre ; Cmd+Option+I donne au contraire une seule fenêtre qui suit la sélection.", "चुनी हुई चीज़ की info window खोलता है — आकार, जगह, कौन सा app उसे खोलता है; Cmd+Option+I से केवल एक window खुलती है जो आपके चयन के साथ बदलती रहती है।", "打开所选项目的信息窗口：大小、所在位置、用哪个应用打开；而 Cmd+Option+I 只开一个检查器窗口，内容随选择变化。", "開啟所選項目的資訊視窗：大小、所在位置、用哪個應用程式開啟；而 Cmd+Option+I 只開一個檢視器視窗，內容隨選擇變化。"],
  'macos-move-file': ["Cmd+C로 복사해 둔 파일을 이 자리로 옮깁니다 — Finder에는 잘라내기가 없으니, 옮기기는 복사한 뒤 이 조합으로 붙이는 것입니다.", "Moves a file you copied with Cmd+C into this folder — the Finder has no Cut, so moving means copying first and then pasting with this combination.", "Mueve a esta carpeta un archivo que copiaste con Cmd+C: el Finder no tiene Cortar, así que mover es copiar y luego pegar con esta combinación.", "Move para esta pasta um arquivo que você copiou com Cmd+C: o Finder não tem Cortar, então mover é copiar e depois colar com esta combinação.", "Cmd+C で複写しておいたファイルをこの場所へ移します — Finder には切り取りが無いので、移動は複写してからこの組み合わせで貼ることを意味します。", "Verschiebt eine mit Cmd+C kopierte Datei in diesen Ordner — der Finder kennt kein Ausschneiden, Verschieben heißt also kopieren und dann mit dieser Folge einfügen.", "Déplace ici un fichier copié avec Cmd+C — le Finder n a pas de Couper, donc déplacer consiste à copier puis coller avec cette combinaison.", "Cmd+C से copy की गई फ़ाइल को इस जगह ले आता है — Finder में Cut नहीं है, इसलिए move का मतलब है पहले copy और फिर इस combination से paste।", "把用 Cmd+C 复制的文件移动到这里——Finder 没有剪切，所谓移动就是先复制、再用这个组合粘贴。", "把用 Cmd+C 複製的檔案移動到這裡——Finder 沒有剪下，所謂移動就是先複製、再用這個組合貼上。"],
};
